window.NHZ_YUWEN = {"grammar":{"categories":[{"id":"cilei","items":[{"name":"名词","例子":["老师、北京（人物/处所）","春天、昨天（时间）","上面、中间（方位）","我的书包、小明的生日","三本书、两个人（名词前能加数量词）","花开了、春天来了（名词能作主语）","妈妈在厨房做饭。","小狗在院子里跑来跑去。","秋天，树叶黄了。","书包里装着课本和文具。","桌子上面放着一杯水。","孩子们在操场上踢足球。"],"口诀":"人事物时地，名词要牢记","易错":"方位词常被误认为副词","讲解":"表示人、事物、时间、处所、方位等的词","深讲":"名词是给人、事物、时间、处所、方位起的名字。分五小类：人物（老师、妈妈）、事物（书包、苹果）、时间（春天、昨天）、处所（北京、学校）、方位（上面、中间）。名词一般能做主语和宾语，前面常能加数量词，如“三本书”“两个人”。","分类":[{"类":"人物名词","说明":"给人起的名字。","代表":"老师、妈妈、小明、爷爷","例子":["小明在教室里看书。"]},{"类":"事物名词","说明":"给具体东西起的名字。","代表":"书包、苹果、桌子","例子":["书包放在桌子上。"]},{"类":"时间名词","说明":"表示时间的词。","代表":"春天、昨天、早上","例子":["春天，花开了。"]},{"类":"处所名词","说明":"表示地方的词。","代表":"学校、北京、家里","例子":["我们在学校上课。"]},{"类":"方位名词","说明":"表示上下、前后、里外的词。","代表":"上面、中间、里、外","例子":["书在桌子上面。"]}],"怎么认":["前面能不能加数量词？能加“三本、两个”的，多半是名词。","能不能回答“谁/什么”？能回答“谁来了、什么掉了”的，多半是名词。","前面能不能加“很”？名词一般不能说“很书包、很北京”。"],"辨析":"名词和代词都指人或事物，但代词是“替身”：他、这、那不指具体名字，换了场合指的东西就变了；名词是固定名字，换场合还是它。方位词是名词里的一小类，只表示方向和位置。","例句解析":[{"句":"小明在北京看书。","析":"“北京”是处所名词，说明看书的地方；“书”是事物名词，是“看”的对象。"},{"句":"春天来了，花开了。","析":"“春天”是时间名词，作主语，说明什么时候；“花”是事物名词。"}],"练习":[{"q":"下面哪个词是名词？","options":["跑步","桌子","很快","在"],"answer":1,"解析":"“桌子”是事物名词；“跑步”是动词，“很快”是副词加形容词，“在”是介词。","类":"事物名词"},{"q":"“昨天”是什么词？","options":["动词","时间名词","副词","形容词"],"answer":1,"解析":"“昨天”表示时间，是时间名词。","类":"时间名词"},{"q":"“书在上面”中，“上面”是？","options":["副词","方位名词","动词","连词"],"answer":1,"解析":"“上面”是方位词，属于名词，不要因为它在句末就当成副词。","类":"方位名词"}],"图示":"<svg viewBox=\"0 0 256 110\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><path d=\"M7,3 13,22 1,22\" fill=\"#7b1fa2\" transform=\"translate(17,5)\"/><text x=\"32\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">他</text><text x=\"32\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">代词</text><path d=\"M15,15 m-9,0 a9,9 0 1,0 18,0 a9,9 0 1,0 -18,0\" fill=\"#d32f2f\" transform=\"translate(81,5)\"/><text x=\"96\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">是</text><text x=\"96\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">动词</text><path d=\"M5,5 h20 v20 h-20 z\" fill=\"#00897b\" transform=\"translate(145,5)\"/><text x=\"160\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">一名</text><text x=\"160\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">数词</text><path d=\"M7,3 13,22 1,22\" fill=\"#222\" transform=\"translate(209,5)\"/><text x=\"224\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">教师</text><text x=\"224\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">名词</text><text x=\"128\" y=\"108\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">每个实词头上戴着自己的符号帽——看形状颜色就知道身份</text></svg>","类比":"名词的符号是一座<b>黑色小山</b>▲，稳稳地立在那里——就像万物的名字，稳定、实在。你能摸到、看到、想到的东西，都有名字：桌子、北京、勇气、昨天。","subtitle":"万物的名字「黑三角」"},{"name":"动词","例子":["跑、吃（动作）","喜欢、害怕（心理）","有、在（存在）","我每天跑步上学","会游泳、能跑步（能愿动词）","跑着、吃了、去过（动词后能加着、了、过）","我每天跑步锻炼身体。","小鸟在枝头唱歌。","他认真地思考问题。","妈妈正在洗衣服。","我们明天去公园春游。","同学们热烈地讨论起来。"],"口诀":"动作心理变化，动词来表达","易错":"“是”有时是动词（判断），有时是副词（强调）","讲解":"表示动作、行为、心理活动、存在变化的词","深讲":"动词表示动作、行为、心理活动和存在变化。分动作（跑、吃）、心理（喜欢、害怕）、存在（有、在）、能愿（会、能、要）、趋向（来、去、上、下）。动词一般能作谓语，常常能带宾语，动作动词后面常能加“着、了、过”。","分类":[{"类":"动作动词","说明":"表示具体动作。","代表":"跑、跳、写、吃","例子":["小明在操场上跑步。"]},{"类":"心理动词","说明":"表示心里想、感觉。","代表":"喜欢、害怕、想、爱","例子":["我喜欢画画。"]},{"类":"存在动词","说明":"表示有、在。","代表":"有、在","例子":["教室里有许多书。"]},{"类":"能愿动词","说明":"表示愿意、能够、应该。","代表":"会、能、要、应该","例子":["我会写自己的名字。"]},{"类":"趋向动词","说明":"表示动作的方向。","代表":"来、去、上、下、进、出","例子":["妈妈走进教室。"]}],"怎么认":["能不能带宾语？“吃什么、看什么”能接上宾语的，多半是动词。","后面能不能加“着、了、过”？“跑着、吃了、去过”都通顺的，多半是动词。","前面能不能加“很”？动作动词一般不能说“很跑、很吃”（喜欢这类心理动词是例外）。"],"辨析":"动词和形容词都常作谓语，但动词讲“做什么”，形容词讲“怎么样”；“他跑得快”里“跑”是动词，“快”是形容词，讲跑的样子。动词和副词也别混：副词是修饰动词的“小跟班”，自己不当谓语中心。","例句解析":[{"句":"小狗在草地上跑。","析":"“跑”是动作动词，作谓语；“在草地上”是地点，说明跑的地方。"},{"句":"我喜欢踢足球。","析":"“喜欢”是心理动词，作谓语；“踢足球”是它带的宾语，说明喜欢什么。"}],"练习":[{"q":"下面哪个词是动词？","options":["美丽","跳绳","很","的"],"answer":1,"解析":"“跳绳”是动作动词；“美丽”是形容词，“很”是副词，“的”是助词。","类":"动作动词"},{"q":"“害怕”属于哪类动词？","options":["动作动词","心理动词","形容词","副词"],"answer":1,"解析":"“害怕”表示心理活动，是心理动词。","类":"心理动词"},{"q":"“他跑得很快”中，“跑”是？","options":["形容词","副词","动词","名词"],"answer":2,"解析":"“跑”讲做什么，是动词；“快”讲跑的样子，是形容词。","类":"动作动词"}],"图示":"<svg viewBox=\"0 0 320 110\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><path d=\"M7,3 13,22 1,22\" fill=\"#222\" transform=\"translate(17,5)\"/><text x=\"32\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">小狗</text><text x=\"32\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">名词</text><path d=\"M15,3 A9,9 0 1,0 15,21\" fill=\"#2e7d32\" transform=\"translate(81,5)\"/><text x=\"96\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">在</text><text x=\"96\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">介词</text><path d=\"M15,15 m-5,0 a5,5 0 1,0 10,0 a5,5 0 1,0 -10,0\" fill=\"#ef6c00\" transform=\"translate(145,5)\"/><text x=\"160\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">飞快</text><text x=\"160\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">副词</text><path d=\"M15,15 m-4,0 a4,4 0 1,0 8,0\" fill=\"#78909c\" transform=\"translate(209,5)\"/><text x=\"224\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">地</text><text x=\"224\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">助词</text><path d=\"M15,15 m-9,0 a9,9 0 1,0 18,0 a9,9 0 1,0 -18,0\" fill=\"#d32f2f\" transform=\"translate(273,5)\"/><text x=\"288\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">跑</text><text x=\"288\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">动词</text><text x=\"160\" y=\"108\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">每个实词头上戴着自己的符号帽——看形状颜色就知道身份</text></svg>","类比":"动词的符号是一颗<b>大红太阳</b>●，散发能量——句子没有动词就像汽车没有发动机，跑不起来。跑、吃、喜欢、是，都是动作或状态。","subtitle":"动作的发动机「大红圆」"},{"name":"形容词","例子":["红、方（形状）","善良、勇敢（性质）","迅速、雪白（状态）","今天的太阳暖洋洋的","很红、非常勇敢（形容词前能加很）","花很红（形容词能作谓语）","这朵花真美丽。","湖水清澈见底。","他跑得很快。","夜晚的星空格外明亮。","她的声音很甜美。","这个问题比较复杂。"],"口诀":"形状性质状态，形容词来扮","易错":"副词“很”+形容词是常见搭配，别把“很”当形容词","讲解":"表示人或事物的形状、性质、状态的词","深讲":"形容词表示人或事物的形状、性质和状态。分性质（善良、勇敢）、形状（方、圆）、状态（雪白、暖洋洋）。形容词一般能受“很、非常”修饰，不能带宾语；作定语时常带“的”，作谓语时直接说明主语怎么样，作补语时说明动作的结果或样子。","分类":[{"类":"性质形容词","说明":"表示人或事物的性质、好坏。","代表":"善良、勇敢、聪明、美丽","例子":["她是一个勇敢的孩子。"]},{"类":"形状形容词","说明":"表示形状、大小。","代表":"方、圆、大、小、长","例子":["桌子是方的。"]},{"类":"状态形容词","说明":"表示当时的样子、状态，常是叠词。","代表":"雪白、暖洋洋、亮晶晶","例子":["雪白的墙，真好看。"]}],"怎么认":["前面能不能加“很”？“很红、很勇敢”通顺的，多半是形容词。","后面能不能带宾语？形容词一般不能说“红书、快饭”这样的搭配。","能不能回答“怎么样”？能回答主语“怎么样”的，多半是形容词。"],"辨析":"形容词和副词都和程度有关，但形容词能作谓语（“花很红”），副词不能单独作谓语，只能修饰别人。“很”本身是副词，不是形容词。状态形容词如“雪白、暖洋洋”一般不受“很”修饰，不能说“很雪白”。","例句解析":[{"句":"今天的太阳暖洋洋的。","析":"“暖洋洋”是状态形容词，作谓语，说明太阳的样子。"},{"句":"雪白的墙真干净。","析":"“雪白”是形容词，作定语，修饰“墙”；“干净”也是形容词，作谓语。"}],"练习":[{"q":"下面哪个词是形容词？","options":["跑","美丽","在","把"],"answer":1,"解析":"“美丽”表示性质，是形容词；“跑”是动词，“在”是介词，“把”是介词。","类":"性质形容词"},{"q":"“雪白的墙”中，“雪白”是？","options":["名词","动词","形容词","副词"],"answer":2,"解析":"“雪白”表示墙的样子，作定语，是形容词。","类":"状态形容词"},{"q":"“很”是什么词？","options":["形容词","副词","动词","名词"],"answer":1,"解析":"“很”修饰形容词和动词，自己是副词，别把跟班当主角。","类":"综合"}],"图示":"<svg viewBox=\"0 0 320 110\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><path d=\"M7,3 13,22 1,22\" fill=\"#1565c0\" transform=\"translate(17,5)\"/><text x=\"32\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">美丽</text><text x=\"32\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">形容词</text><path d=\"M15,15 m-4,0 a4,4 0 1,0 8,0\" fill=\"#78909c\" transform=\"translate(81,5)\"/><text x=\"96\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">的</text><text x=\"96\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">助词</text><path d=\"M7,3 13,22 1,22\" fill=\"#222\" transform=\"translate(145,5)\"/><text x=\"160\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">花</text><text x=\"160\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">名词</text><path d=\"M15,15 m-9,0 a9,9 0 1,0 18,0 a9,9 0 1,0 -18,0\" fill=\"#d32f2f\" transform=\"translate(209,5)\"/><text x=\"224\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">开</text><text x=\"224\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">动词</text><path d=\"M15,15 m-4,0 a4,4 0 1,0 8,0\" fill=\"#78909c\" transform=\"translate(273,5)\"/><text x=\"288\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">了</text><text x=\"288\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">助词</text><text x=\"160\" y=\"108\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">每个实词头上戴着自己的符号帽——看形状颜色就知道身份</text></svg>","subtitle":"名词的化妆师「蓝三角」","类比":"形容词的符号是一座<b>蓝色小山</b>▲，紧挨着名词的黑三角——它是名词的化妆师，专门描述样子：红的花、善良的人、雪白的墙。"},{"name":"数词","例子":["一、两、百","第一、初三","我们班有45个同学","一、二、三（基数）","第一、第二（序数）","几、许多（概数）","三个苹果、第一名","两个人、两本书（量词前用两）","二月、第二名（读数和序数用二）","一年有四个季节。","我们班有三十名同学。","他得了第一名。"],"口诀":"数目次序，数词管住","易错":"“两”和“二”用法不同：序数用“二”，量词前多用“两”","讲解":"表示数目和次序的词","深讲":"数词表示数目和次序。分基数（一、二、三……）、序数（第一、第二……）和概数（几、许多、大约）。数词常常和量词一起用，组成数量短语，如“三个苹果”“第一名”。数词本身不指具体东西，要和量词、名词搭在一起才完整。","分类":[{"类":"基数词","说明":"表示数目多少。","代表":"一、二、三、十","例子":["桌上有三个苹果。"]},{"类":"序数词","说明":"表示第几个。","代表":"第一、第二、第三","例子":["他得了第一名。"]},{"类":"概数词","说明":"表示大概的数目。","代表":"几、许多、大约、十来个","例子":["篮子里有十来个苹果。"]}],"怎么认":["是不是表示“几个、第几个”？是的，多半是数词。","后面能不能跟量词？“三只、五本、第一”后面常跟量词或名词。","“二”和“两”要分场合：读数、序数用“二”（二月、第二），量词前面多用“两”（两个人、两本书）。"],"辨析":"数词和量词是一对搭档：数词管“多少”，量词管“用什么单位量”。“三”单独不能说“三书”，要说“三本书”；“只”单独也不能表数，要说“三只”。","例句解析":[{"句":"教室里有三只小猫。","析":"“三”是数词，“只”是量词，“三只”合起来修饰“小猫”，说明数量。"},{"句":"他在比赛中得了第一名。","析":"“第一”是序数词，表示次序，不是数量；“名”是量词。"}],"练习":[{"q":"下面哪个词是数词？","options":["只","三","本","个"],"answer":1,"解析":"“三”表示数目，是数词；“只、本、个”都是量词。","类":"基数词"},{"q":"“两个人”中，为什么不用“二”？","options":["量词前多用“两”","读数用“两”","序数用“两”","都可以"],"answer":0,"解析":"量词前面多用“两”，如两个人、两本书；读数和序数才用“二”。","类":"基数词"},{"q":"“第二名”中，“第二”是？","options":["基数","序数","量词","概数"],"answer":1,"解析":"“第二”表示次序，是序数词。","类":"序数词"}],"图示":"<svg viewBox=\"0 0 30 30\" width=\"44\" height=\"44\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"5\" y=\"5\" width=\"20\" height=\"20\" rx=\"4\" fill=\"#00897b\"/></svg><div style=\"font-size:12px;color:#888;text-align:center\">蒙特梭利符号：青方</div>"},{"name":"量词","例子":["个、只、条","米、公斤、次","一本书、三只小猫","个、只、条、本（名量词）","次、遍、回（动量词）","三个苹果、这本书","看三遍、跑两趟","一条鱼、一座山","一本鱼（错：量词搭配不对）","一双筷子","一群孩子在公园玩耍。","一阵风吹过，树叶沙沙响。"],"口诀":"名量（个只条）+动量（次回遍）","易错":"量词重叠表“每一”，如“个个”","讲解":"表示计量单位的词","深讲":"量词表示计量单位，分名量词和动量词。名量词量人或事物（个、只、条、本、张、座），动量词量动作的次数（次、遍、回、趟）。量词前面常有数词或指示代词（这、那），后面跟名词或动词，如“这本书”“看三遍”。","分类":[{"类":"名量词","说明":"量人或事物，后面跟名词。","代表":"个、只、条、本、张、座","例子":["一座桥横在河上。"]},{"类":"动量词","说明":"量动作的次数，后面跟动词。","代表":"次、遍、回、趟","例子":["这篇课文我读了三遍。"]}],"怎么认":["是不是跟在数词或“这、那”后面量东西？“三个、这本”里的“个、本”就是量词。","量的是人或物，还是动作次数？量人或物的是名量词，量次数的是动量词。","换一个量词试试：说“一条鱼”通顺，“一本鱼”就不通顺，量词和名词要搭配。"],"辨析":"量词和名词别混：名词是东西的名字，量词是量的单位。“书”是名词，“本”是量词。量词也不能单独表数，“本”不说“有几本”，要说“有几本书”。","例句解析":[{"句":"桌上有一条鱼。","析":"“条”是名量词，和鱼搭配；换成“本”就不通顺，说明量词要和名词配对。"},{"句":"这篇课文我读了三遍。","析":"“遍”是动量词，量动作“读”的次数，不是量课文本身。"}],"练习":[{"q":"“一座桥”中，量词是？","options":["一","座","桥","的"],"answer":1,"解析":"“座”是量词，量桥；“一”是数词，“桥”是名词。","类":"名量词"},{"q":"下面哪个是动量词？","options":["只","本","遍","条"],"answer":2,"解析":"“遍”量动作的次数，是动量词；其余都是名量词。","类":"动量词"},{"q":"下面哪组搭配不对？","options":["一条鱼","一本书","一座山","一本鱼"],"answer":3,"解析":"鱼用“条”不用“本”，量词要和名词搭配。","类":"名量词"}],"图示":"<svg viewBox=\"0 0 30 30\" width=\"44\" height=\"44\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"8\" y=\"5\" width=\"14\" height=\"20\" rx=\"7\" fill=\"#00897b\" opacity=\"0.6\"/></svg><div style=\"font-size:12px;color:#888;text-align:center\">蒙特梭利符号：青椭圆</div>"},{"name":"代词","例子":["我、你、他（人称）","这、那（指示）","谁、怎么（疑问）","这是我的铅笔，那是你的","这、那、这里（指示）","谁、什么、哪里（疑问）","小明来了，他也来了","这是什么、那是谁","我们、你们、他们","这是谁的书包？","他们明天要去爬山。","大家安静一下，听老师讲。"],"口诀":"人称指示疑问，代词三剑客","易错":"“这”“那”+量词+名词是代词性用法","讲解":"代替名词、动词、形容词等的词","深讲":"代词是代替名词、动词、形容词等实词的词，分人称（我、你、他、我们）、指示（这、那、这里、那里）、疑问（谁、什么、哪里、怎么）。代词的好处是不用重复名字：说过“小明”后，后面用“他”代替，句子就简洁了。","分类":[{"类":"人称代词","说明":"代替人的词。","代表":"我、你、他、我们、你们、他们","例子":["小明来了，他也来了。"]},{"类":"指示代词","说明":"指东西、地方的词。","代表":"这、那、这里、那里","例子":["这是我的铅笔，那是你的。"]},{"类":"疑问代词","说明":"用来提问的词。","代表":"谁、什么、哪里、怎么","例子":["这是什么？"]}],"怎么认":["是不是在代替前面出现过的人或事物？是的，多半是代词。","换一个具体名字试试：把“他”换成“小明”，句子意思不变，说明“他”是代词。","是不是在提问？“谁、什么、哪里”提问的，多半是疑问代词。"],"辨析":"代词和名词都能指人指物，但名词是固定名字，代词是“替身”，离开上下文就不知道指谁。“他”在不同句子里可以是小明，也可以是小刚；“小明”永远是小明。","例句解析":[{"句":"小明来了，他手里拿着一本书。","析":"第二个分句的“他”代替前面的“小明”，避免重复。"},{"句":"这是什么？","析":"“这”是指示代词，指眼前这个东西；“什么”是疑问代词，用来提问。"}],"练习":[{"q":"下面哪个词是代词？","options":["桌子","他们","跑步","美丽"],"answer":1,"解析":"“他们”是人称代词；“桌子”是名词，“跑步”是动词，“美丽”是形容词。","类":"人称代词"},{"q":"“谁来了？”中，“谁”是？","options":["名词","疑问代词","动词","副词"],"answer":1,"解析":"“谁”用来提问，是疑问代词。","类":"疑问代词"},{"q":"“他”在不同句子里指的人一样吗？","options":["一样","不一定，要看上下文","永远是小明","不能指人"],"answer":1,"解析":"代词是替身，指谁要看上下文，不能只看词本身。","类":"人称代词"}],"图示":"<svg viewBox=\"0 0 320 110\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><path d=\"M7,3 13,22 1,22\" fill=\"#7b1fa2\" transform=\"translate(17,5)\"/><text x=\"32\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">这</text><text x=\"32\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">代词</text><path d=\"M15,15 m-9,0 a9,9 0 1,0 18,0 a9,9 0 1,0 -18,0\" fill=\"#d32f2f\" transform=\"translate(81,5)\"/><text x=\"96\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">是</text><text x=\"96\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">动词</text><path d=\"M7,3 13,22 1,22\" fill=\"#7b1fa2\" transform=\"translate(145,5)\"/><text x=\"160\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">我</text><text x=\"160\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">代词</text><path d=\"M15,15 m-4,0 a4,4 0 1,0 8,0\" fill=\"#78909c\" transform=\"translate(209,5)\"/><text x=\"224\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">的</text><text x=\"224\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">助词</text><path d=\"M7,3 13,22 1,22\" fill=\"#222\" transform=\"translate(273,5)\"/><text x=\"288\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">书</text><text x=\"288\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">名词</text><text x=\"160\" y=\"108\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">每个实词头上戴着自己的符号帽——看形状颜色就知道身份</text></svg>","subtitle":"名词的替身「紫三角」","类比":"代词的符号是一座<b>紫色小山</b>▲，和名词的黑三角是亲戚——它是名词的替身演员：我、你、他、这、那、谁，不用每次都喊全名。"},{"name":"副词","例子":["很、非常（程度）","都、只（范围）","已经、正在（时间）","他跑得非常快","常常、总是（频率）","不、没（否定）","也许、大概（语气）","他非常喜欢读书。","我们都去过北京。","小明也参加了比赛。","天渐渐黑了下来。","妈妈已经做好了晚饭。"],"口诀":"程度范围时间，副词来限制","易错":"副词一般不能单独做谓语","讲解":"修饰动词、形容词，表示程度、范围、时间等的词","深讲":"副词修饰动词、形容词，表示程度、范围、时间、频率、语气、否定等。分程度（很、非常）、范围（都、只）、时间（已经、正在）、频率（常常、总是）、否定（不、没）、语气（也许、大概）。副词一般放在谓语前面，不能修饰名词，前面一般不能再加“很”。","分类":[{"类":"程度副词","说明":"表示程度深浅。","代表":"很、非常、最、更","例子":["他跑得非常快。"]},{"类":"范围副词","说明":"表示范围大小。","代表":"都、只、也、全","例子":["同学们都来了。"]},{"类":"时间副词","说明":"表示动作的时间。","代表":"已经、正在、马上","例子":["火车已经到了。"]},{"类":"频率副词","说明":"表示动作常常发生。","代表":"常常、总是、有时","例子":["他常常帮妈妈做家务。"]},{"类":"否定副词","说明":"表示否定。","代表":"不、没、别","例子":["我不去，你去吧。"]},{"类":"语气副词","说明":"表示说话人的推测、语气。","代表":"也许、大概、一定","例子":["也许明天会下雨。"]}],"怎么认":["是不是站在动词或形容词前面修饰它？“已经来了、非常快”里的“已经、非常”就是副词。","能不能修饰名词？副词一般不能说“很书包、都桌子”。","删掉它试试：删掉副词，句子主干还在，只是程度、时间、范围的意思弱了。"],"辨析":"副词和形容词都和程度有关，但形容词能作谓语（“花很红”），副词不能单独作谓语，只能修饰别人。“很”本身是副词，不是形容词。","例句解析":[{"句":"他已经写完了作业。","析":"“已经”是时间副词，放在动词“写”前面，说明动作完成了。"},{"句":"同学们都来了。","析":"“都”是范围副词，说明“同学们”一个不落，全都来了。"}],"练习":[{"q":"下面哪个词是副词？","options":["桌子","已经","跑步","美丽"],"answer":1,"解析":"“已经”表示时间，是副词；“桌子”是名词，“跑步”是动词，“美丽”是形容词。","类":"时间副词"},{"q":"“非常快”中，“非常”是？","options":["形容词","副词","动词","名词"],"answer":1,"解析":"“非常”修饰形容词“快”，自己是副词。","类":"程度副词"},{"q":"副词一般不能修饰？","options":["动词","形容词","名词","谓语"],"answer":2,"解析":"副词修饰动词和形容词，一般不能修饰名词。","类":"综合"}],"图示":"<svg viewBox=\"0 0 448 110\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><path d=\"M7,3 13,22 1,22\" fill=\"#7b1fa2\" transform=\"translate(17,5)\"/><text x=\"32\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">他</text><text x=\"32\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">代词</text><path d=\"M15,15 m-5,0 a5,5 0 1,0 10,0 a5,5 0 1,0 -10,0\" fill=\"#ef6c00\" transform=\"translate(81,5)\"/><text x=\"96\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">已经</text><text x=\"96\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">副词</text><path d=\"M15,15 m-5,0 a5,5 0 1,0 10,0 a5,5 0 1,0 -10,0\" fill=\"#ef6c00\" transform=\"translate(145,5)\"/><text x=\"160\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">飞快</text><text x=\"160\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">副词</text><path d=\"M15,15 m-4,0 a4,4 0 1,0 8,0\" fill=\"#78909c\" transform=\"translate(209,5)\"/><text x=\"224\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">地</text><text x=\"224\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">助词</text><path d=\"M15,15 m-9,0 a9,9 0 1,0 18,0 a9,9 0 1,0 -18,0\" fill=\"#d32f2f\" transform=\"translate(273,5)\"/><text x=\"288\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">跑</text><text x=\"288\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">动词</text><path d=\"M15,15 m-9,0 a9,9 0 1,0 18,0 a9,9 0 1,0 -18,0\" fill=\"#d32f2f\" transform=\"translate(337,5)\"/><text x=\"352\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">出</text><text x=\"352\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">动词</text><path d=\"M7,3 13,22 1,22\" fill=\"#222\" transform=\"translate(401,5)\"/><text x=\"416\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">教室</text><text x=\"416\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">名词</text><text x=\"224\" y=\"108\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">每个实词头上戴着自己的符号帽——看形状颜色就知道身份</text></svg>","subtitle":"动词的小跟班「小橙圆」","类比":"副词的符号是一颗<b>小橙圆</b>，紧挨着动词的大红圆——小圆是大圆的跟班，专门给动作加说明：怎么跑（飞快地跑）、多深（很爱）、什么时候（已经走了）。"},{"name":"介词","例子":["在、从、向（方向）","把、被（对象）","关于、对于","我在教室里写作业","在教室、从北京（处所）","给妈妈、对他（对象）","向老师请教（方向）","为班级争光（目的）","比他高（比较）","把书放在桌上（处置）"],"口诀":"在从把被关于，介词引对象","易错":"“把”字句和“被”字句是中考重点句式","讲解":"用在名词、代词前，组成介词短语，表示方向、对象等的词","深讲":"介词引出时间、处所、对象、方式、原因等，和后面的名词、代词组成介宾短语。常见介词有在、从、向、往、给、对、为、比、跟、把、被。介宾短语常常作状语（“在教室里读书”）、补语（“来自北京”）或定语（“对他的关心”），但介词自己不能单独作谓语中心。","分类":[{"类":"处所方向介词","说明":"表示地方、方向。","代表":"在、向、往、从","例子":["他在教室里读书。"]},{"类":"时间介词","说明":"表示时间。","代表":"从、自、到","例子":["我们从早上读到中午。"]},{"类":"对象介词","说明":"表示动作的对象。","代表":"对、给、为、跟","例子":["妈妈给弟弟讲故事。"]},{"类":"方式介词","说明":"表示用的办法、工具。","代表":"用、按、照","例子":["他用铅笔画画。"]}],"怎么认":["后面是不是跟了一个名词或代词？“在教室、给妈妈、对他”这种结构，多半是介词短语。","能不能单独作谓语？介词自己不能单独作谓语中心，要和后面的词组成短语。","换成动词试试还通不通？介词后面的词不能像动词那样带“着、了、过”。"],"辨析":"介词和连词最容易混，关键看换位：连词“和”连接的“苹果和香蕉”可以换成“香蕉和苹果”，意思不变；介词引出的部分换位置就变味或不通，如“他向老师请教”换成“老师向他请教”，主角就换了人。","例句解析":[{"句":"小明在教室里看书。","析":"“在教室里”是介宾短语，作状语，说明看书的地点；“在”是介词。"},{"句":"妈妈给弟弟讲故事。","析":"“给弟弟”是介宾短语，说明讲故事的对象；这里的“给”引出对象，是介词。"}],"练习":[{"q":"“在教室里”中，“在”是？","options":["动词","介词","副词","连词"],"answer":1,"解析":"“在”引出地点，和“教室里”组成介宾短语，是介词。","类":"处所方向介词"},{"q":"下面哪个是介词短语？","options":["跑得快","在学校","很美丽","三本书"],"answer":1,"解析":"“在学校”是介词加名词组成的介宾短语；其余不是。","类":"处所方向介词"},{"q":"介词一般不能？","options":["跟名词","作状语","单独作谓语中心","组成短语"],"answer":2,"解析":"介词要和后面的词组成短语，不能单独作谓语中心。","类":"综合"}],"图示":"<svg viewBox=\"0 0 384 110\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><path d=\"M7,3 13,22 1,22\" fill=\"#7b1fa2\" transform=\"translate(17,5)\"/><text x=\"32\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">我</text><text x=\"32\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">代词</text><path d=\"M15,3 A9,9 0 1,0 15,21\" fill=\"#2e7d32\" transform=\"translate(81,5)\"/><text x=\"96\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">从</text><text x=\"96\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">介词</text><path d=\"M7,3 13,22 1,22\" fill=\"#222\" transform=\"translate(145,5)\"/><text x=\"160\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">北京</text><text x=\"160\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">名词</text><path d=\"M15,3 A9,9 0 1,0 15,21\" fill=\"#2e7d32\" transform=\"translate(209,5)\"/><text x=\"224\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">到</text><text x=\"224\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">介词</text><path d=\"M7,3 13,22 1,22\" fill=\"#222\" transform=\"translate(273,5)\"/><text x=\"288\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">上海</text><text x=\"288\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">名词</text><path d=\"M15,15 m-9,0 a9,9 0 1,0 18,0 a9,9 0 1,0 -18,0\" fill=\"#d32f2f\" transform=\"translate(337,5)\"/><text x=\"352\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">去</text><text x=\"352\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">动词</text><text x=\"192\" y=\"108\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">每个实词头上戴着自己的符号帽——看形状颜色就知道身份</text></svg>","subtitle":"方位的月亮「绿新月」","类比":"介词的符号是一弯<b>绿色新月</b>☽，总在名词前面带路：在哪里（在公园）、从哪里（从北京）、向哪里（向南）。它像路标，指引方向。"},{"name":"连词","例子":["和、跟（并列）","但是、然而（转折）","因为、所以（因果）","我喜欢画画，也喜欢唱歌","苹果和香蕉（并列）","虽然累，但是坚持（转折）","因为下雨，所以取消（因果）","如果下雨，就回家（假设）","不是苹果，而是香蕉（选择）","老师和同学（可换位）"],"口诀":"连接上下，关系靠它","易错":"关联词搭配要完整，如“不仅……而且”不能丢一半","讲解":"连接词、短语、句子，表示并列、转折等关系的词","深讲":"连词连接词、短语或分句，表示并列、转折、因果、假设、选择等关系。常见连词有和、及、或、但是、因为、所以、如果、虽然。连词本身没有实在意义，只起连接作用；它连接的两部分在逻辑上是并列或有关系，不是修饰关系。","分类":[{"类":"并列连词","说明":"连接平等的两部分。","代表":"和、及、以及","例子":["苹果和香蕉都很好吃。"]},{"类":"转折连词","说明":"前后意思转折。","代表":"但是、可是、然而","例子":["他累了，可是还坚持跑。"]},{"类":"因果连词","说明":"表示原因和结果。","代表":"因为、所以、因此","例子":["因为下雨，所以我们没去公园。"]},{"类":"假设连词","说明":"表示假设。","代表":"如果、假如","例子":["如果努力，就会进步。"]},{"类":"选择连词","说明":"表示二选一。","代表":"或者、还是","例子":["你喝水还是喝牛奶？"]}],"怎么认":["是不是在连接两个词、短语或句子？“苹果和香蕉、虽然累但是坚持”里的“和、虽然……但是”就是连词。","连接的两个部分能不能换位置？并列连词连接的部分换位置意思基本不变。","删掉它试试：删掉连词，两部分就散了，关系也看不出来了。"],"辨析":"连词和介词最容易混，关键看换位：连词“和”连接的“老师和同学”可以换成“同学和老师”，意思不变；介词引出的对象换位置意思就变了，如“他向老师请教”不能随便换成“老师向他请教”。","例句解析":[{"句":"老师和同学一起打扫教室。","析":"“和”是连词，连接“老师”和“同学”，两个都是打扫的人，地位平等。"},{"句":"虽然下雨，但是运动会照常进行。","析":"“虽然……但是”是一对连词，连接两个分句，表示转折关系。"}],"练习":[{"q":"下面哪个词是连词？","options":["在","和","的","很"],"answer":1,"解析":"“和”连接两个词，是连词；“在”是介词，“的”是助词，“很”是副词。","类":"并列连词"},{"q":"“苹果和香蕉”换成“香蕉和苹果”，意思？","options":["变了","基本不变","变成介词","不能换"],"answer":1,"解析":"并列连词连接的部分换位置，意思基本不变。","类":"并列连词"},{"q":"“虽然……但是”表示？","options":["因果","转折","并列","选择"],"answer":1,"解析":"“虽然……但是”表示转折关系。","类":"转折连词"}],"图示":"<svg viewBox=\"0 0 30 30\" width=\"44\" height=\"44\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"3\" y=\"10\" width=\"24\" height=\"10\" rx=\"2\" fill=\"#ec407a\"/></svg><div style=\"font-size:12px;color:#888;text-align:center\">蒙特梭利符号：粉长方</div>"},{"name":"助词","例子":["的、地、得（结构助词）","了、着、过（动态助词）","吗、呢（语气助词）","妈妈做的饭真好吃","我的书、红红的苹果（的）","快地跑、认真地写（地）","跑得快、写得好（得）","吃了、看着、去过（了、着、过）","好吗、走吧（吗、吧）","的、地、得分工要记牢"],"口诀":"的定地状得后补，时态语气也清楚","易错":"“的地得”用法：“的”定语、“地”状语、“得”补语","讲解":"附着在词、短语后表示语法意义的词","深讲":"助词附着在词、短语或句子后面，起结构、动态或语气作用，本身没有实在意义。分结构助词（的、地、得）、动态助词（了、着、过）、语气助词（吗、呢、吧、啊）。助词不能单独作句子成分，要和前面的词一起看。","分类":[{"类":"结构助词","说明":"放在词后面，起连接、结构作用。","代表":"的、地、得","例子":["红红的苹果真好看。"]},{"类":"动态助词","说明":"表示动作完成、进行、经历。","代表":"了、着、过","例子":["我看过这本书。"]},{"类":"语气助词","说明":"放在句末，表语气。","代表":"吗、呢、吧、啊","例子":["你去吗？"]}],"怎么认":["是不是附在别的词后面？“我的、快地、跑得快、吃了、好吗”里的“的、地、得、了、吗”就是助词。","删掉它试试：删掉助词，句子主干还在，但结构关系或语气就不清楚了。","“的、地、得”分工：的后跟名词，地后跟动词、形容词，得后跟补充说明。"],"辨析":"助词和语气词、叹词别混：语气词是助词里的一小类，只在句末表语气；叹词是独立成句的感叹词，多在句首。助词“了”表完成或变化，“着”表持续，“过”表经历，三者不能互换。","例句解析":[{"句":"红红的苹果真好吃。","析":"“的”是结构助词，连接定语“红红”和名词“苹果”。"},{"句":"他吃过北京烤鸭。","析":"“过”是动态助词，放在动词“吃”后面，表示曾经有过的经历。"}],"练习":[{"q":"“快地跑”中，“地”是？","options":["介词","结构助词","副词","连词"],"answer":1,"解析":"“地”连接状语和动词，是结构助词。","类":"结构助词"},{"q":"“吃了饭”中，“了”表示？","options":["持续","经历","完成","疑问"],"answer":2,"解析":"动词后的“了”表示动作完成。","类":"动态助词"},{"q":"下面哪个是语气助词？","options":["的","着","吗","得"],"answer":2,"解析":"“吗”在句末表示疑问语气，是语气助词。","类":"语气助词"}],"图示":"<svg viewBox=\"0 0 30 30\" width=\"44\" height=\"44\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"15\" cy=\"15\" r=\"5\" fill=\"#78909c\"/></svg><div style=\"font-size:12px;color:#888;text-align:center\">蒙特梭利符号：灰小圆</div>"},{"name":"语气词","例子":["吗、呢、吧、啊","明天一起去打球吧！","好吗、吃饭了吗（吗）","一起去吧、走吧（吧）","你呢、他呢（呢）","真美啊、好啊（啊）","走吧是商量、走吗是提问","语气词在句末","你去过长城吗？","多美的风景啊！","我们一起去吧。","你怎么还没来呢？"],"口诀":"句尾表语气，吗呢吧啊","易错":"语气词不重读","讲解":"表示语气，常用在句尾的词","深讲":"语气词用在句末，表示陈述、疑问、祈使、感叹等语气。常见语气词有吗、呢、吧、啊、呀、么。语气词不表示实在意义，读起来语气不同，意思和态度就不同：说“走吧”是商量，说“走吗”是提问。","分类":[{"类":"陈述语气词","说明":"句末表平静陈述的语气。","代表":"了、啊","例子":["下雨了。"]},{"类":"疑问语气词","说明":"表提问。","代表":"吗、呢","例子":["你去吗？"]},{"类":"祈使语气词","说明":"表商量、希望对方做。","代表":"吧、啊","例子":["我们一起去吧。"]},{"类":"感叹语气词","说明":"表感叹。","代表":"啊、呀、哇","例子":["多美的花呀！"]}],"怎么认":["是不是在句末？句末的“吗、呢、吧、啊”多半是语气词。","换一个语气词试试：把“好吗”换成“好吧”，句子从提问变成了商量，说明语气词管的是语气。","删掉它试试：删掉语气词，句子意思还在，但语气、态度就没了。"],"辨析":"语气词和叹词都和语气有关，但语气词在句末、附着在句子上；叹词独立成句、多在句首。“啊，真美！”里的“啊”是叹词；“这花真美啊”里的“啊”是语气词。","例句解析":[{"句":"我们一起去公园吧。","析":"句末的“吧”是语气词，表示商量、建议。"},{"句":"你吃饭了吗？","析":"句末的“吗”是语气词，把陈述句变成了疑问句。"}],"练习":[{"q":"“一起去吧”中，“吧”是？","options":["动词","语气词","叹词","名词"],"answer":1,"解析":"句末的“吧”表示商量语气，是语气词。","类":"祈使语气词"},{"q":"语气词一般在？","options":["句首独立","句末","动词前","名词后"],"answer":1,"解析":"语气词用在句末，表示全句的语气。","类":"综合"},{"q":"“好吗”换成“好吧”，变的是？","options":["主语","语气","宾语","时间"],"answer":1,"解析":"换语气词，句子意思基本不变，变的是语气和态度。","类":"综合"}],"图示":"<svg viewBox=\"0 0 30 30\" width=\"44\" height=\"44\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"15\" cy=\"15\" r=\"9\" fill=\"none\" stroke=\"#f9a825\" stroke-width=\"3\"/></svg><div style=\"font-size:12px;color:#888;text-align:center\">蒙特梭利符号：金环</div>"},{"name":"叹词","例子":["啊、哎、哦、喂","哎呀，我忘带作业了！","啊，真美（感叹）","喂，你好（呼唤）","嗯，知道了（应答）","哈哈，真有趣（笑声）","哎呀，疼死我了","啊在句首是叹词、在句末是语气词","哎呀，我忘带钥匙了！","嘿，加油啊！","哇，这座山真高！","哼，我才不信呢！"],"口诀":"感叹呼唤应答，叹词来表达","易错":"叹词常独立成句，后用逗号或感叹号","讲解":"表示感叹、呼唤、应答的词","深讲":"叹词表示感叹、呼唤、应答等，独立成句或独立成分，常常在句首，后面常带感叹号或逗号。常见叹词有啊、哎呀、哦、喂、嗯、哈哈。叹词不作句子的主要成分，删掉它，句子主干还在，只是感情色彩弱了。","分类":[{"类":"感叹叹词","说明":"表惊讶、高兴、心疼等感情。","代表":"啊、哎呀、哇","例子":["哎呀，太好了！"]},{"类":"呼唤叹词","说明":"表叫人、引起注意。","代表":"喂、嘿","例子":["喂，你听到了吗？"]},{"类":"应答叹词","说明":"表答应、明白。","代表":"嗯、哦、好","例子":["嗯，我知道了。"]}],"怎么认":["是不是独立在句首、后面有感叹号或逗号？“啊，真美！喂，你好！”里的“啊、喂”就是叹词。","是不是在表示感叹、呼唤或应答？是的，多半是叹词。","删掉它试试：删掉叹词，句子还能成立，只是少了那股感情劲儿。"],"辨析":"叹词和语气词最容易混：叹词独立、多在句首（“啊，真美！”）；语气词附着在句末（“真美啊！”）。同一个“啊”字，位置不同，词类就不同——这正是“看位置、看作用”的好例子。","例句解析":[{"句":"啊，祖国的山河真壮丽！","析":"句首的“啊”是叹词，独立成成分，表达赞叹，后面用逗号隔开。"},{"句":"喂，你听见了吗？","析":"“喂”是叹词，表示呼唤，引起对方注意；句末的“吗”才是语气词。"}],"练习":[{"q":"“哎呀，疼死我了！”中，“哎呀”是？","options":["语气词","叹词","副词","形容词"],"answer":1,"解析":"句首独立的“哎呀”表示感叹，是叹词。","类":"感叹叹词"},{"q":"叹词常常在？","options":["句末","句首独立","动词后","名词前"],"answer":1,"解析":"叹词独立成句或成分，常常在句首。","类":"综合"},{"q":"“真美啊”中，“啊”是？","options":["叹词","语气词","动词","介词"],"answer":1,"解析":"句末的“啊”附着在句子上表语气，是语气词，不是叹词。","类":"综合"}],"图示":"<svg viewBox=\"0 0 30 30\" width=\"44\" height=\"44\" xmlns=\"http://www.w3.org/2000/svg\"><polygon points=\"15,4 20,15 15,26 10,15\" fill=\"#f9a825\"/></svg><div style=\"font-size:12px;color:#888;text-align:center\">蒙特梭利符号：金菱</div>"}],"name":"词的分类（12类）"},{"id":"duanyu","items":[{"name":"并列式","例子":["老师和同学","又高又大","调查研究","爸爸和妈妈","花草树木","聪明伶俐","吃喝玩乐","风雨雷电","父母兄弟","山川河流","笔墨纸砚","春夏秋冬"],"口诀":"地位平等是并列","易错":"“和”连接的也可能是介词短语，要看语境","讲解":"前后成分地位平等，无主次之分","深讲":"并列式是前后成分地位平等、谁也不修饰谁的短语，中间常有顿号、“和”“又……又……”连接；去掉任何一个成分，剩下的还能说得通，只是意思少了一半。","分类":[{"类":"名词并列","说明":"并列的成分是名词。","代表":"老师和同学、花草","例子":["老师和同学一起去春游。"]},{"类":"动词并列","说明":"并列的成分是动词。","代表":"调查研究、又唱又跳","例子":["同学们调查研究了校园植物。"]},{"类":"形容词并列","说明":"并列的成分是形容词。","代表":"又高又大、又红又香","例子":["苹果又红又香。"]}],"怎么认":["前后换个位置，意思基本不变？是的，多半是并列。","中间有没有顿号、“和”“又……又……”？有，多半是并列。","去掉一个成分，剩下的还能成话？能，说明地位平等。"],"辨析":"并列和偏正的区别：偏正是一个修饰一个（红旗：红修饰旗），并列是谁也不修饰谁（红花绿草：红花和绿草平等）。“又高又大”里高和大谁也不修饰谁，是并列，不是偏正。","例句解析":[{"句":"老师和同学一起去春游。","析":"“老师”和“同学”地位平等，中间用“和”连接，去掉一个，句子还通，只是人少了。"},{"句":"苹果又红又香。","析":"“红”和“香”都说苹果，地位平等，是形容词并列。"}],"练习":[{"q":"下面哪个是并列式短语？","options":["红旗","老师和同学","认真学习","跑得快"],"answer":1,"解析":"老师和同学地位平等，是并列；红旗是偏正，认真学习是偏正，跑得快是补充。","类":"名词并列"},{"q":"“又高又大”中，“高”和“大”的关系是？","options":["修饰关系","并列关系","支配关系","补充关系"],"answer":1,"解析":"高和大都说同一个人或物，地位平等。","类":"形容词并列"},{"q":"“调查研究”属于？","options":["并列式","偏正式","动宾式","主谓式"],"answer":0,"解析":"调查和研究都是动词，地位平等。","类":"动词并列"}]},{"name":"偏正式","例子":["红旗（定中）","认真学习（状中）","伟大的祖国","漂亮的新书包","红苹果","三本书","认真学习","飞快地跑","美丽的校园","轻轻地放","新衣服","大声朗读"],"口诀":"前偏后正，修饰中心","易错":"是短语中数量最多的一种","讲解":"前偏后正，修饰限制关系","深讲":"偏正式是前偏后正、一个修饰一个的短语：前面的词说明后面的词怎么样、什么样的；后面的词是中心，前面的词去掉，中心还在，只是说得不具体了。","分类":[{"类":"定中式","说明":"前面定语修饰后面的中心语，中心语是名词。","代表":"红旗、伟大的祖国","例子":["伟大的祖国真美丽。"]},{"类":"状中式","说明":"前面状语修饰后面的中心语，中心语是动词或形容词。","代表":"认真学习、快快跑","例子":["小明认真学习。"]}],"怎么认":["后面的词是不是中心？是的，前面在修饰它。","前后能不能加“的”（名词中心）或“地”（动词、形容词中心）？能，多半是偏正。","去掉前面的词，句子还通吗？通，只是变笼统了。"],"辨析":"偏正和并列的区别：偏正前偏后正，有主次；并列地位平等，无主次。“红旗”红修饰旗，是偏正；“红花绿草”红花和绿草平等，是并列。","例句解析":[{"句":"伟大的祖国真美丽。","析":"“伟大”修饰“祖国”，祖国是中心，是定中式。"},{"句":"小明认真学习。","析":"“认真”修饰“学习”，学习是中心，是状中式。"}],"练习":[{"q":"下面哪个是偏正式短语？","options":["老师和同学","红旗","祖国繁荣","学习语文"],"answer":1,"解析":"红修饰旗，前偏后正；其他分别是并列、主谓、动宾。","类":"定中式"},{"q":"“认真学习”中，“认真”和“学习”的关系是？","options":["并列","修饰（状中）","支配","补充"],"answer":1,"解析":"认真修饰学习，学习是中心。","类":"状中式"},{"q":"“漂亮的新书包”中，中心语是？","options":["漂亮","新","书包","的"],"answer":2,"解析":"漂亮、新都修饰书包，书包是中心。","类":"定中式"}]},{"name":"主谓式","例子":["祖国繁荣","他来了","天气晴朗","小鸟唱歌","花开了","天黑了","他笑了","心情好","成绩提高","春天来了","太阳升起来了","我们胜利了"],"口诀":"谁怎么样，主谓来讲","易错":"主谓短语可作主语、宾语、定语","讲解":"陈述关系，前后可加“是”","深讲":"主谓式是陈述关系的短语：前面说谁、什么，后面说他怎么样、是什么；前后中间常常能加“是”来检查，意思不变。","分类":[{"类":"动词谓语","说明":"谓语是动词，说明主语做什么。","代表":"小鸟唱歌、他来了","例子":["小鸟在枝头唱歌。"]},{"类":"形容词谓语","说明":"谓语是形容词，说明主语怎么样。","代表":"天气晴朗、祖国繁荣","例子":["今天天气晴朗。"]}],"怎么认":["能不能分成“谁”+“怎么样”两部分？能，多半是主谓。","中间加“是”意思变不变？不变，多半是主谓。","前面是不是在说后面那个动作、状态是谁做的？是的。"],"辨析":"主谓和动宾的区别：主谓是“谁怎么样”（小鸟唱歌：小鸟是主语），动宾是“动词+受动者”（唱歌：唱是动词，歌是宾语）。一个短语里“小鸟唱歌”是主谓，单看“唱歌”是动宾。","例句解析":[{"句":"小鸟在枝头唱歌。","析":"“小鸟”是主语，“唱歌”是谓语，说小鸟怎么样。"},{"句":"今天天气晴朗。","析":"“天气”是主语，“晴朗”是形容词谓语，说天气怎么样。"}],"练习":[{"q":"下面哪个是主谓式短语？","options":["学习语文","祖国繁荣","红旗","跑得快"],"answer":1,"解析":"祖国是主语，繁荣是谓语；其他是动宾、偏正、补充。","类":"形容词谓语"},{"q":"“他来了”中，“他”是？","options":["宾语","主语","定语","状语"],"answer":1,"解析":"他是陈述对象，是主语。","类":"动词谓语"},{"q":"“小鸟唱歌”中，“唱歌”是？","options":["主语","谓语","宾语","定语"],"answer":1,"解析":"唱歌说明小鸟怎么样，是谓语。","类":"动词谓语"}]},{"name":"动宾式","例子":["学习语文","打扫教室","热爱祖国","踢足球","读书","写字","吃饭","唱歌","画画","洗衣服","开门"],"口诀":"动词在前，宾语在后","易错":"不及物动词不能带宾语（如“出发”不能直接带宾语）","讲解":"支配关系，动词+受动者","深讲":"动宾式是支配关系的短语：前面是动词，后面是动词管着的人或事物；动词和宾语中间常常能加“什么”来提问，问的就是宾语。","分类":[{"类":"名词宾语","说明":"宾语是名词。","代表":"学习语文、踢足球","例子":["他打扫教室。"]},{"类":"代词宾语","说明":"宾语是代词。","代表":"帮助他、爱护它","例子":["老师帮助他。"]},{"类":"动词宾语","说明":"宾语是动词或动词短语。","代表":"喜欢游泳、开始跑步","例子":["我喜欢游泳。"]}],"怎么认":["前面是不是动词？后面是不是它管着的人或物？是的。","在动词后问“什么”，能问出后面的词吗？能，它就是宾语。","把动词和后面的词换个位置，意思变不变？变了，说明有支配关系，不是并列。"],"辨析":"动宾和主谓的区别：动宾是动词在前、宾语在后（打扫教室）；主谓是主语在前、谓语在后（教室干净）。“学习语文”学习是动词，语文是宾语；“语文难学”语文是主语，难学是谓语。","例句解析":[{"句":"他打扫教室。","析":"“打扫”是动词，“教室”是它管着的对象，是宾语。"},{"句":"我喜欢游泳。","析":"“喜欢”是动词，“游泳”是动词宾语，说明喜欢什么。"}],"练习":[{"q":"下面哪个是动宾式短语？","options":["祖国繁荣","学习语文","红旗","又高又大"],"answer":1,"解析":"学习是动词，语文是宾语；其他是主谓、偏正、并列。","类":"名词宾语"},{"q":"“帮助他”中，“他”是？","options":["主语","宾语","定语","谓语"],"answer":1,"解析":"他是帮助的对象，是代词宾语。","类":"代词宾语"},{"q":"“喜欢游泳”中，“游泳”是？","options":["名词宾语","动词宾语","主语","状语"],"answer":1,"解析":"游泳是动词，作喜欢的宾语。","类":"动词宾语"}]},{"name":"补充式","例子":["写得好","跑得快","热极了","笑得很开心","说清楚","洗干净","长高了","热得满头大汗","写完了","打破了","坐下"],"口诀":"补充说明在后头","易错":"常由“得”字连接","讲解":"后补前，补充说明动作结果/程度","深讲":"补充式是后补前、补充说明的短语：后面的词补充前面的动词或形容词，说明结果怎么样、程度怎么样、方向往哪去；补充部分常常由“得”连接，去掉它，动作还在，只是不具体了。","分类":[{"类":"结果补语","说明":"补充动作的结果。","代表":"写完了、洗干净","例子":["衣服洗干净了。"]},{"类":"程度补语","说明":"补充动作、状态的程度，常由“得”连接。","代表":"跑得快、笑得很开心","例子":["他跑得很快。"]},{"类":"趋向补语","说明":"补充动作的方向。","代表":"走进来、飞上去","例子":["小鸟飞上去了。"]}],"怎么认":["后面的词是不是在补充前面的动词、形容词？是的。","中间有没有“得”“极了”？有，多半是补充。","去掉后面的词，动作还成立吗？成立，只是结果、程度不清楚了。"],"辨析":"补充和偏正的区别：偏正是前面修饰后面（认真学习：认真在前），补充是后面补充前面（跑得快：快在后，补充跑）。看修饰在前还是补充在后。","例句解析":[{"句":"衣服洗干净了。","析":"“干净”补充“洗”的结果，说明洗成什么样。"},{"句":"他跑得很快。","析":"“快”由“得”连接，补充“跑”的程度。"}],"练习":[{"q":"下面哪个是补充式短语？","options":["红旗","学习语文","跑得快","老师和同学"],"answer":2,"解析":"快补充跑的程度；其他是偏正、动宾、并列。","类":"程度补语"},{"q":"“洗干净”中，“干净”是什么补语？","options":["结果补语","程度补语","趋向补语","定语"],"answer":0,"解析":"干净说明洗的结果。","类":"结果补语"},{"q":"“走进来”中，“进来”是什么补语？","options":["结果补语","程度补语","趋向补语","状语"],"answer":2,"解析":"进来说明走的方向。","类":"趋向补语"}]}],"name":"短语的结构（5种）"},{"id":"juzichengfen","items":[{"name":"主语","例子":["〔他〕来了","〔祖国的明天〕会更好","〔小明〕在踢球","我们班得了第一名。（我们班是主语）","小鸟在天上飞。（小鸟是主语）","春天来了。（春天是主语）","他认真地写作业。（他是主语）","鲜艳的红旗迎风飘扬。（红旗是主语）","勤劳的蜜蜂在花丛中飞舞。（蜜蜂是主语）","这本书很有趣。（书是主语）","外面下起了大雨。（雨是主语）","老师表扬了他。（老师是主语）"],"口诀":"主语回答谁什么","易错":"主语多余或残缺是常见病句","讲解":"谓语陈述的对象，回答“谁/什么”","深讲":"主语是谓语陈述的对象，回答“谁”或“什么”；找主语先找谓语，再问“谁怎么样、什么怎么样”，答的就是主语；主语常常在句首。","分类":[{"类":"名词主语","说明":"主语是名词或名词短语。","代表":"小明、祖国","例子":["小明在踢球。"]},{"类":"代词主语","说明":"主语是代词。","代表":"他、我们","例子":["他来了。"]},{"类":"短语主语","说明":"主语是短语。","代表":"祖国的明天、读书","例子":["祖国的明天会更好。"]}],"怎么认":["先找谓语（说明怎么样的词），再问谁、什么。","主语多在句首。","去掉主语，句子就不知道说谁了。"],"辨析":"主语和宾语都回答谁、什么，区别在位置和关系：主语在谓语前，是陈述对象；宾语在动词后，是动作对象。“我爱妈妈”我主语，妈妈宾语。","例句解析":[{"句":"他来了。","析":"“他”是主语，“来了”是谓语，说他怎么样。"},{"句":"祖国的明天会更好。","析":"“祖国的明天”是主语，“会更好”是谓语，说它怎么样。"}],"练习":[{"q":"“小明在踢球”中，主语是？","options":["小明","在","踢球","球"],"answer":0,"解析":"小明是陈述对象，是名词主语。","类":"名词主语"},{"q":"“他来了”中，主语是？","options":["他","来了","了","来"],"answer":0,"解析":"他是陈述对象，是代词主语。","类":"代词主语"},{"q":"“祖国的明天会更好”中，主语是？","options":["祖国","明天","祖国的明天","更好"],"answer":2,"解析":"祖国的明天整体作主语，是短语主语。","类":"短语主语"}],"类比":"主语就像电影的\"主角\"：一句话讲谁，ta 就是主语。","图示":"<svg viewBox=\"0 0 400 80\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"30\" y1=\"40\" x2=\"370\" y2=\"40\" stroke=\"#333\" stroke-width=\"2\"/><text x=\"60\" y=\"32\" font-size=\"15\">主语</text><text x=\"180\" y=\"32\" font-size=\"15\">‖</text><text x=\"210\" y=\"32\" font-size=\"15\">谓语</text><text x=\"60\" y=\"65\" font-size=\"12\" fill=\"#888\">黎锦熙图解：主谓宾在线上，定状补在线下</text></svg>"},{"name":"谓语","例子":["他〔来了〕","祖国〔是花园〕","小狗〔汪汪叫〕","我爱我的祖国。（爱是谓语）","小狗汪汪地叫。（叫是谓语）","他跑得很快。（跑是谓语）","妈妈在做饭。（做饭是谓语）","花儿开了。（开是谓语）","同学们认真听讲。（听讲是谓语）","太阳升起来了。（升是谓语）","我们胜利了。（胜利是谓语）","鸟儿在枝头唱歌。（唱歌是谓语）"],"口诀":"谓语说明怎么样","易错":"谓语残缺会导致句子不完整","讲解":"陈述主语，回答“怎么样/是什么/做什么”","深讲":"谓语陈述主语，回答怎么样、是什么、做什么；谓语是句子的中心，没有谓语，句子就不完整；谓语可以是动词、形容词、名词短语。","分类":[{"类":"动词谓语","说明":"谓语是动词，说明主语做什么。","代表":"来了、踢球","例子":["他来了。"]},{"类":"形容词谓语","说明":"谓语是形容词，说明主语怎么样。","代表":"晴朗、美丽","例子":["天气晴朗。"]},{"类":"名词谓语","说明":"谓语是名词短语，说明主语是什么。","代表":"是花园、是老师","例子":["祖国是花园。"]}],"怎么认":["先找主语，再问它怎么样、是什么、做什么。","谓语多在主语后。","去掉谓语，只剩主语，句子说不完整。"],"辨析":"谓语和宾语：谓语说明主语，宾语是动词的对象。“他学习语文”学习是谓语，语文是宾语；不能把宾语当谓语。","例句解析":[{"句":"他来了。","析":"“来了”是谓语，说明他怎么样。"},{"句":"祖国是花园。","析":"“是花园”是谓语，说明祖国是什么。"}],"练习":[{"q":"“小狗汪汪叫”中，谓语是？","options":["小狗","汪汪叫","汪汪","叫"],"answer":1,"解析":"汪汪叫说明小狗怎么样，是动词谓语。","类":"动词谓语"},{"q":"“天气晴朗”中，谓语是？","options":["天气","晴朗","今天","很"],"answer":1,"解析":"晴朗说明天气怎么样，是形容词谓语。","类":"形容词谓语"},{"q":"“祖国是花园”中，谓语是？","options":["祖国","是花园","花园","是"],"answer":1,"解析":"是花园说明祖国是什么，是名词谓语。","类":"名词谓语"}],"类比":"谓语就像主角的\"动作戏\"：主角在干什么，谓语就讲什么。"},{"name":"宾语","例子":["学习〔语文〕","热爱〔祖国〕","我爱〔妈妈〕","我喜欢读书。（书是宾语）","妈妈买了苹果。（苹果是宾语）","他踢足球。（足球是宾语）","我们参观了博物馆。（博物馆是宾语）","小明写完了作业。（作业是宾语）","老师表扬了他。（他是宾语）","我喝了一杯牛奶。（牛奶是宾语）","姐姐织毛衣。（毛衣是宾语）","他修好了自行车。（自行车是宾语）"],"口诀":"动词之后找宾语","易错":"及物动词缺宾语是成分残缺","讲解":"动作的对象，回答“谁/什么”","深讲":"宾语是动作的对象，回答谁、什么；宾语在动词后面，动词问“什么”，答的就是宾语；不及物动词不能直接带宾语。","分类":[{"类":"名词宾语","说明":"宾语是名词。","代表":"语文、祖国","例子":["学习语文。"]},{"类":"代词宾语","说明":"宾语是代词。","代表":"他、它","例子":["我喜欢他。"]},{"类":"动词宾语","说明":"宾语是动词或动词短语。","代表":"游泳、跑步","例子":["我喜欢游泳。"]}],"怎么认":["先找动词，再问动词什么。","宾语多在动词后。","去掉宾语，动作就不知道对谁、做什么了。"],"辨析":"宾语和主语：都回答谁、什么，主语在前是陈述对象，宾语在后是动作对象。“妈妈爱我”妈妈主语，我宾语；换位置意思就变了。","例句解析":[{"句":"学习语文。","析":"“语文”是宾语，说明学习什么。"},{"句":"我爱妈妈。","析":"“妈妈”是宾语，说明爱谁。"}],"练习":[{"q":"“学习语文”中，宾语是？","options":["学习","语文","语","文"],"answer":1,"解析":"语文是学习的对象，是名词宾语。","类":"名词宾语"},{"q":"“我喜欢他”中，宾语是？","options":["我","喜欢","他","欢"],"answer":2,"解析":"他是喜欢的对象，是代词宾语。","类":"代词宾语"},{"q":"“我喜欢游泳”中，宾语是？","options":["我","喜欢","游泳","游"],"answer":2,"解析":"游泳是动词，作喜欢的宾语。","类":"动词宾语"}],"类比":"宾语就像动作的\"接球手\"：动词这个球扔出去，砸到谁，谁就是宾语。"},{"name":"定语","例子":["（红色的）旗","（我）的书","（粉色的）铅笔盒","红红的苹果真好看。（红红的是定语）","勤劳的蜜蜂采蜜忙。（勤劳的是定语）","高高的山上有座庙。（高高的是定语）","聪明的孩子爱动脑。（聪明的是定语）","美丽的校园里花香扑鼻。（美丽的是定语）","洁白的雪覆盖了大地。（洁白的是定语）","勇敢的战士冲上前去。（勇敢的是定语）","新买的书包真漂亮。（新买的是定语）","慈祥的奶奶讲故事。（慈祥的是定语）"],"口诀":"定语修饰名词，常带“的”字","易错":"多重定语语序：领属+数量+动词性+形容词性+名词","讲解":"修饰名词，回答“什么样的”","深讲":"定语修饰名词，回答什么样的、谁的、哪一个；定语在名词前面，常带“的”；定语去掉，名词还在，只是说得不具体。","分类":[{"类":"形容词定语","说明":"定语是形容词。","代表":"红色的、粉色的","例子":["红色的旗。"]},{"类":"名词定语","说明":"定语是名词，常表领属、材料。","代表":"我的、木头的","例子":["我的书。"]},{"类":"动词定语","说明":"定语是动词或动词短语。","代表":"刚买的、会唱歌的","例子":["刚买的书真好看。"]}],"怎么认":["看它修饰的是不是名词。","前面有没有“的”。","问“什么样的+名词”，答的就是定语。"],"辨析":"定语和状语：定语修饰名词（红色的旗），状语修饰动词、形容词（认真地学习）；看中心语是名词还是动词、形容词，再看“的”还是“地”。","例句解析":[{"句":"红色的旗。","析":"“红色的”修饰旗，是形容词定语。"},{"句":"我的书。","析":"“我的”修饰书，是名词定语。"}],"练习":[{"q":"“红色的旗”中，定语是？","options":["红色的","旗","飘扬","高"],"answer":0,"解析":"红色的修饰旗，是形容词定语。","类":"形容词定语"},{"q":"“我的书”中，定语是？","options":["我","我的","书","本"],"answer":1,"解析":"我的修饰书，是名词定语。","类":"名词定语"},{"q":"“刚买的书”中，定语是？","options":["刚","刚买的","书","买"],"answer":1,"解析":"刚买的修饰书，是动词定语。","类":"动词定语"}],"类比":"定语就像\"标签\"：贴在名词前面，告诉你这是哪一个。"},{"name":"状语","例子":["〔认真地〕学习","〔在教室里〕读书","〔高兴地〕跳起来","他认真地听讲。（认真地是状语）","同学们在操场上跑步。（在操场上是状语）","妈妈高兴地笑了。（高兴地是状语）","我们明天去春游。（明天是状语）","小鸟快乐地唱歌。（快乐地是状语）","他飞快地跑回家。（飞快地是状语）","老师耐心地讲解。（耐心地是状语）","大家热烈地鼓掌。（热烈地是状语）","我昨天去了公园。（昨天是状语）"],"口诀":"状语修饰动形，常带“地”字","易错":"状语位置一般在谓语前","讲解":"修饰动词/形容词，回答“怎样/何时/何地”","深讲":"状语修饰动词、形容词，回答怎样、何时、何地；状语在谓语前面，常带“地”，也可以是时间、处所短语；去掉状语，句子主干还在，只是不具体。","分类":[{"类":"时间状语","说明":"说明动作的时间。","代表":"昨天、早上","例子":["昨天我们去春游。"]},{"类":"处所状语","说明":"说明动作的地点。","代表":"在教室里、在家里","例子":["在教室里读书。"]},{"类":"方式状语","说明":"说明动作的方式、样子，常带“地”。","代表":"认真地、高兴地","例子":["认真地学习。"]}],"怎么认":["看它修饰的是不是动词、形容词。","在谓语前，有没有“地”或时间、处所词。","问怎样、何时、何地，答的就是状语。"],"辨析":"状语和定语：状语修饰动词、形容词（认真地学习），定语修饰名词（认真的学生）；“地”前是状语，“的”前是定语。","例句解析":[{"句":"认真地学习。","析":"“认真地”修饰学习，是方式状语。"},{"句":"在教室里读书。","析":"“在教室里”修饰读书，说明地点，是处所状语。"}],"练习":[{"q":"“认真地学习”中，状语是？","options":["认真","认真地","学习","地"],"answer":1,"解析":"认真地修饰学习，是方式状语。","类":"方式状语"},{"q":"“在教室里读书”中，状语是？","options":["在","在教室里","读书","教室"],"answer":1,"解析":"在教室里修饰读书，说明地点，是处所状语。","类":"处所状语"},{"q":"“昨天我们去春游”中，状语是？","options":["昨天","我们","去","春游"],"answer":0,"解析":"昨天修饰去，说明时间，是时间状语。","类":"时间状语"}],"类比":"状语就像\"滤镜\"：加在动词/形容词前面，告诉你动作怎么发生的。"},{"name":"补语","例子":["写得〔好〕","跑得〔快〕","写得〔很工整〕","他跑得很快。（很快是补语）","作业写完了。（完了是补语）","衣服洗干净了。（干净是补语）","她长高了许多。（许多是补语）","热得满头大汗。（满头大汗是补语）","说得清清楚楚。（清清楚楚是补语）","天黑下来了。（下来是补语）","花开得很美。（很美是补语）","他气得说不出话。（说不出话是补语）"],"口诀":"补语补充在后头，常带“得”字","易错":"“得”后补语与“地”前状语不要混","讲解":"补充说明谓语，回答“到什么程度/结果”","深讲":"补语补充说明谓语，回答到什么程度、什么结果、往哪去；补语在谓语后面，常由“得”连接；去掉补语，动作还在，只是不具体。","分类":[{"类":"结果补语","说明":"补充动作的结果。","代表":"完、干净、好","例子":["衣服洗干净了。"]},{"类":"程度补语","说明":"补充动作、状态的程度，常由“得”连接。","代表":"快、很工整","例子":["他跑得很快。"]},{"类":"趋向补语","说明":"补充动作的方向。","代表":"进来、上去","例子":["小鸟飞上去了。"]}],"怎么认":["看它是不是在谓语后面补充说明。","中间有没有“得”。","问程度、结果、方向，答的就是补语。"],"辨析":"补语和状语：补语在谓语后补充（跑得快：快在后），状语在谓语前修饰（快快跑：快快在前）；“得”后是补语，“地”前是状语。","例句解析":[{"句":"写得好。","析":"“好”补充写的程度，是程度补语。"},{"句":"衣服洗干净了。","析":"“干净”补充洗的结果，是结果补语。"}],"练习":[{"q":"“跑得快”中，补语是？","options":["跑","得","快","跑得"],"answer":2,"解析":"快补充跑的程度，是程度补语。","类":"程度补语"},{"q":"“衣服洗干净了”中，补语是？","options":["衣服","洗","干净","了"],"answer":2,"解析":"干净补充洗的结果，是结果补语。","类":"结果补语"},{"q":"“小鸟飞上去了”中，补语是？","options":["小鸟","飞","上去","了"],"answer":2,"解析":"上去补充飞的方向，是趋向补语。","类":"趋向补语"}],"类比":"补语就像\"赛后采访\"：动作结束了，补一句\"结果如何\"。"}],"name":"单句的成分（6种）"},{"id":"fuju","items":[{"name":"并列复句","例子":["他来了，我也来了","我写作业，弟弟看书","花儿红，草儿绿。","他会唱歌，也会跳舞。","天晴了，风停了。","小明爱读书，小红爱画画。","春天播种，秋天收获。","妈妈做饭，爸爸洗碗。","太阳升起，公鸡打鸣。","教室里安静，操场上热闹。","他个子高，她个子矮。","白天很热，夜里很凉。"],"口诀":"关联词：既……又、也、还","易错":"","讲解":"分句间平等并列","深讲":"并列复句是两个或两个以上分句地位平等、并列在一起的复句；分句间没有主次，谁也不比谁更进一层；判断并列，先看意思是不是平行的，再看有没有既……又、也、还这类关联词。","分类":[{"类":"既……又……式","说明":"用既……又连接两个平行的方面。","代表":"既……又……","例子":["他既会唱歌，又会跳舞。"]},{"类":"也、还式","说明":"后分句用也、还表示同样、并列。","代表":"也、还","例子":["他来了，我也来了。"]},{"类":"一边……一边……式","说明":"两个动作同时进行。","代表":"一边……一边……","例子":["他一边走路，一边唱歌。"]}],"怎么认":["分句间是不是平行的，谁也不比谁更进一层？是的。","有没有既……又、也、还、一边……一边？有，多半是并列。","去掉一个分句，剩下的还能成话？能，说明地位平等。"],"辨析":"并列和递进的区别：并列是平行的（既会唱歌，又会跳舞），递进是后句更进一层（不但会唱歌，而且会作曲）。把“不但……而且”换成“既……又”，意思就变了味，说明不是并列。","例句解析":[{"句":"我写作业，弟弟看书。","析":"两个分句说两件事，地位平等，没有主次，是并列复句。"},{"句":"他既会唱歌，又会跳舞。","析":"既……又连接两个平行的本领，是并列复句。"}],"练习":[{"q":"下面哪个是并列复句？","options":["他不但会唱歌，而且会跳舞","他既会唱歌，又会跳舞","因为努力，所以成功","如果下雨，就不去了"],"answer":1,"解析":"既……又表示平行，是并列；其他是递进、因果、假设。","类":"既……又……式"},{"q":"“他来了，我也来了”中，“也”表示？","options":["递进","并列","转折","因果"],"answer":1,"解析":"也表示同样、并列。","类":"也、还式"},{"q":"“他一边走路，一边唱歌”属于？","options":["并列复句","递进复句","选择复句","条件复句"],"answer":0,"解析":"两个动作同时进行，地位平等，是并列。","类":"一边……一边……式"}]},{"name":"递进复句","例子":["他不但会唱歌，而且会跳舞","她不但画画好，而且字也写得漂亮","他不但会唱歌，而且会跳舞。","这本书不仅有趣，还很有道理。","小明不但聪明，而且勤奋。","她不但跑得快，而且跳得远。","这件事不但重要，而且紧急。","他不仅是学生，还是运动员。","教室不但干净，而且整齐。","妈妈不但会做饭，还会织毛衣。","这个问题不但难，而且很关键。","他不但答对了，而且全对。"],"口诀":"关联词：不但……而且、甚至","易错":"递进顺序不能颠倒","讲解":"后分句比前分句更进一层","深讲":"递进复句是后分句比前分句更进一层的复句；前句说一层意思，后句再进一层，顺序不能颠倒；常用不但……而且、不仅……还、甚至。","分类":[{"类":"不但……而且……式","说明":"最常用的递进搭配。","代表":"不但……而且……","例子":["他不但会唱歌，而且会跳舞。"]},{"类":"不仅……还……式","说明":"不仅引出前一层，还引出更进一层。","代表":"不仅……还……","例子":["她不仅画画好，还写得一手好字。"]},{"类":"甚至式","说明":"后句用甚至，表示进到出乎意料的一层。","代表":"甚至","例子":["他不但会唱歌，甚至会作曲。"]}],"怎么认":["后句是不是比前句更进一层？是的。","有没有不但……而且、不仅……还、甚至？有，多半是递进。","前后换个位置，意思还顺吗？不顺，说明顺序不能颠倒。"],"辨析":"递进和并列的区别：并列是平行的，递进是进一层的。“不但会唱歌，而且会跳舞”后句是新本领、更进一层；“既会唱歌，又会跳舞”只是平行列举。","例句解析":[{"句":"他不但会唱歌，而且会跳舞。","析":"后句跳舞比前句唱歌更进一层，是递进复句。"},{"句":"她不但画画好，而且字也写得漂亮。","析":"后句字漂亮比前句画画好更进一层，是递进复句。"}],"练习":[{"q":"下面哪个是递进复句？","options":["他既会唱歌，又会跳舞","他不但会唱歌，而且会跳舞","他来了，我也来了","你去还是留"],"answer":1,"解析":"不但……而且表示更进一层，是递进。","类":"不但……而且……式"},{"q":"递进复句前后顺序能颠倒吗？","options":["能","不能","有时能","看情况"],"answer":1,"解析":"递进是进一层的关系，顺序不能颠倒。","类":"不但……而且……式"},{"q":"“她不仅画画好，还写得一手好字”属于？","options":["并列复句","递进复句","转折复句","因果复句"],"answer":1,"解析":"不仅……还表示更进一层，是递进。","类":"不仅……还……式"}]},{"name":"选择复句","例子":["是去还是留，你定吧","放学后去打球还是回家，你选吧","你是喝茶，还是喝咖啡？","与其在这里等，不如先回家。","宁可站着死，不肯跪着生。","他不是去北京，就是去上海。","与其抱怨，不如行动。","要么好好学，要么别学了。","你喜欢红色，还是喜欢蓝色？","不是你去，就是我去。","与其空想，不如实干。","他宁可走路，也不坐车。"],"口诀":"关联词：或者……或者、是……还是","易错":"“或者”表选择，“还是”用于问句","讲解":"列出两种情况供选择","深讲":"选择复句是列出两种或两种以上情况，供人选择的复句；分句间是选择关系，不是并列，也不是转折；常用或者……或者、是……还是、要么……要么。","分类":[{"类":"或者……或者……式","说明":"在两种情况中选一种，常用于陈述。","代表":"或者……或者……","例子":["你或者去打球，或者回家。"]},{"类":"是……还是……式","说明":"用于问句，让对方选。","代表":"是……还是……","例子":["是去还是留，你定吧。"]},{"类":"要么……要么……式","说明":"在两种情况中选一种，语气较肯定。","代表":"要么……要么……","例子":["要么去，要么留，你定吧。"]}],"怎么认":["是不是在两种情况中选一种？是的。","有没有或者、还是、要么？有，多半是选择。","是不是在问对方选哪个？是的，多半是是……还是。"],"辨析":"选择和并列的区别：并列是两件事都发生（既唱歌又跳舞），选择是二选一（或者唱歌，或者跳舞）。“或者”表选择，“还是”用于问句，不要混。","例句解析":[{"句":"是去还是留，你定吧。","析":"是……还是让对方在去和留中选，是选择复句。"},{"句":"放学后去打球还是回家，你选吧。","析":"打球和回家二选一，是选择复句。"}],"练习":[{"q":"下面哪个是选择复句？","options":["他既会唱歌，又会跳舞","是去还是留，你定吧","因为努力，所以成功","虽然累，但是坚持"],"answer":1,"解析":"是……还是让对方选，是选择。","类":"是……还是……式"},{"q":"“或者”一般表？","options":["并列","选择","转折","因果"],"answer":1,"解析":"或者列出两种情况供选择。","类":"或者……或者……式"},{"q":"“要么去，要么留”属于？","options":["选择复句","并列复句","假设复句","条件复句"],"answer":0,"解析":"要么……要么是二选一，是选择。","类":"要么……要么……式"}]},{"name":"转折复句","例子":["虽然下雨，但是没耽误","虽然我很累，但是我坚持跑完了","虽然下雨，但是运动会照常举行。","他虽然累，却很开心。","尽管困难很多，我们还是完成了。","虽然他年纪小，但是懂得很多。","这件衣服虽然贵，但是质量好。","虽然天黑了，但是路灯亮了。","他虽然失败了，却没有气馁。","尽管下着大雨，农民还在抢收。","这道题虽然难，但是我做出来了。","虽然他病了，但是坚持上课。"],"口诀":"关联词：虽然……但是、尽管……还是","易错":"转折连词不能单独省略后半","讲解":"前后意思相反或相对","深讲":"转折复句是前后意思相反或相对的复句；前句先说一层意思，后句一转，说出相反或相对的意思；常用虽然……但是、尽管……还是。","分类":[{"类":"虽然……但是……式","说明":"最常用的转折搭配。","代表":"虽然……但是……","例子":["虽然下雨，但是没耽误。"]},{"类":"尽管……还是……式","说明":"尽管让步，还是表示转折的结果。","代表":"尽管……还是……","例子":["尽管很累，他还是坚持跑完了。"]},{"类":"转折词单独式","说明":"只用可是、但是、却表示转折。","代表":"可是、但是、却","例子":["他很累，可是还坚持着。"]}],"怎么认":["前后意思是不是相反或相对？是的。","有没有虽然……但是、尽管……还是、可是？有，多半是转折。","去掉后句，前句的意思还完整吗？不完整，说明转折在后句。"],"辨析":"转折和因果的区别：转折是前后相反（虽然下雨，但是没耽误），因果是前因后果（因为下雨，所以没去）。看前后是相反还是因果，不要只看有没有但是。","例句解析":[{"句":"虽然下雨，但是没耽误。","析":"前句下雨，后句没耽误，意思一转，是转折复句。"},{"句":"虽然我很累，但是我坚持跑完了。","析":"累和坚持跑完相对，是转折复句。"}],"练习":[{"q":"下面哪个是转折复句？","options":["因为努力，所以成功","虽然下雨，但是没耽误","如果下雨，就不去了","他既会唱歌，又会跳舞"],"answer":1,"解析":"虽然……但是表示转折。","类":"虽然……但是……式"},{"q":"“尽管很累，他还是坚持跑完了”属于？","options":["转折复句","因果复句","递进复句","并列复句"],"answer":0,"解析":"尽管……还是表示转折。","类":"尽管……还是……式"},{"q":"转折复句前后意思的关系是？","options":["平行","相反或相对","因果","选择"],"answer":1,"解析":"转折是前后相反或相对。","类":"虽然……但是……式"}],"类比":"转折就像\"先扬后抑\"：前面夸一句，后面\"但是\"一转才是真心话。","图示":"<svg viewBox=\"0 0 320 160\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">转折复句：意思拐了个弯</text><text x=\"12\" y=\"44\" font-size=\"15\" class=\"svg-ink\">虽然他生病了，</text><text x=\"117\" y=\"44\" font-size=\"15\" class=\"svg-red\">但是</text><text x=\"147\" y=\"44\" font-size=\"15\" class=\"svg-ink\">还是来了。</text><path d=\"M30,80 L170,80 Q200,80 200,110 L200,132\" stroke-width=\"12\" fill=\"none\" stroke-linecap=\"round\" opacity=\"0.3\"/ class=\"svg-muted-s\"><circle r=\"6\" class=\"svg-accent\"><animateMotion dur=\"6s\" repeatCount=\"indefinite\" path=\"M30,80 L170,80 Q200,80 200,110 L200,132\"/></circle><text x=\"212\" y=\"100\" font-size=\"12\" class=\"svg-red\">拐弯！</text><text x=\"12\" y=\"150\" font-size=\"12\" class=\"svg-muted\">\"虽然\"先让步，\"但是\"后面才是真正想说的</text></svg>"},{"name":"因果复句","例子":["因为努力，所以成功","因为我生病了，所以没去上学","因为努力，所以他成功了。","由于下雨，比赛推迟了。","他之所以迟到，是因为堵车。","因为天气冷，所以多穿了衣服。","既然你来了，就一起吃饭吧。","因为坚持，他终于学会了游泳。","由于缺水，禾苗枯黄了。","他因为生病，所以请假了。","因为准备充分，考试很顺利。","之所以成功，是因为从不放弃。"],"口诀":"关联词：因为……所以、由于","易错":"因果倒置会造成逻辑错误","讲解":"前因后果","深讲":"因果复句是前因后果的复句；前句说原因，后句说结果，顺序一般是先因后果，也可以先果后因；常用因为……所以、由于……因此。","分类":[{"类":"因为……所以……式","说明":"最常用的因果搭配，先因后果。","代表":"因为……所以……","例子":["因为努力，所以成功。"]},{"类":"由于……因此……式","说明":"由于引出原因，因此引出结果。","代表":"由于……因此……","例子":["由于下雨，因此我们没去公园。"]},{"类":"先果后因式","说明":"先说结果，后说原因。","代表":"……，因为……","例子":["他没去上学，因为生病了。"]}],"怎么认":["前后是不是原因和结果？是的。","有没有因为……所以、由于……因此？有，多半是因果。","问“为什么”，能问出前句吗？能，说明前句是原因。"],"辨析":"因果和条件的区别：因果是原因已经发生、结果跟着来（因为生病，所以没去）；条件是条件还没发生、结果跟着条件来（只有努力，才能成功）。看原因是不是已经发生了。","例句解析":[{"句":"因为努力，所以成功。","析":"努力是原因，成功是结果，是因果复句。"},{"句":"因为我生病了，所以没去上学。","析":"生病是原因，没去上学是结果，是因果复句。"}],"练习":[{"q":"下面哪个是因果复句？","options":["虽然累，但是坚持","因为努力，所以成功","如果下雨，就不去了","他既会唱歌，又会跳舞"],"answer":1,"解析":"因为……所以表示因果。","类":"因为……所以……式"},{"q":"“他没去上学，因为生病了”中，原因是？","options":["没去上学","生病了","上学","他"],"answer":1,"解析":"生病了是原因，没去上学是结果，先果后因。","类":"先果后因式"},{"q":"因果倒置会造成？","options":["逻辑错误","语气变化","意思不变","变成并列"],"answer":0,"解析":"原因和结果颠倒，逻辑就错了。","类":"因为……所以……式"}],"类比":"因果就像\"多米诺\"：前一张牌倒了（因），后一张跟着倒（果）。","图示":"<svg viewBox=\"0 0 320 150\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">因果复句：原因 → 结果</text><rect x=\"12\" y=\"36\" width=\"120\" height=\"44\" rx=\"10\" fill=\"none\" stroke-width=\"2\" class=\"svg-accent-s\"><animate attributeName=\"opacity\" values=\"1;1;0.35;0.35;1\" keyTimes=\"0;0.45;0.5;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/></rect><text x=\"72\" y=\"63\" font-size=\"15\" text-anchor=\"middle\" class=\"svg-ink\">因为下雨了</text><line x1=\"136\" y1=\"58\" x2=\"184\" y2=\"58\" stroke-width=\"2\"/ class=\"svg-muted-s\"><circle r=\"5\" class=\"svg-accent\"><animateMotion dur=\"2s\" repeatCount=\"indefinite\" path=\"M136,58 L184,58\"/></circle><polygon points=\"184,58 176,53 176,63\"/ class=\"svg-accent\"><rect x=\"188\" y=\"36\" width=\"120\" height=\"44\" rx=\"10\" fill=\"none\" stroke-width=\"2\" class=\"svg-red-s\"><animate attributeName=\"opacity\" values=\"0.35;0.35;1;1;0.35\" keyTimes=\"0;0.45;0.5;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/></rect><text x=\"248\" y=\"63\" font-size=\"15\" text-anchor=\"middle\" class=\"svg-ink\">所以没去踢球</text><text x=\"12\" y=\"122\" font-size=\"12\" class=\"svg-muted\">金点从原因流向结果：\"因为\"和\"所以\"是固定搭档</text></svg>"},{"name":"假设复句","例子":["如果下雨，就不去了","如果周末不下雨，我们就去爬山","如果下雨，我们就不去了。","假如我是鸟，就能自由飞翔。","要是早点出发，就不会迟到了。","如果努力，就一定有收获。","假如下雪，学校就放假了。","如果我是你，就会道歉。","要是没有水，植物会枯死。","假如时光倒流，我会更珍惜。","如果明天晴，就去爬山。","要是认真听，就能听懂。"],"口诀":"关联词：如果……就、假如","易错":"假设与条件的区别：假设多为未然","讲解":"假设条件下的结果","深讲":"假设复句是假设条件下的结果的复句；前句假设一种还没发生的情况，后句说在这种情况下会怎么样；常用如果……就、假如……就、要是……就。","分类":[{"类":"如果……就……式","说明":"最常用的假设搭配。","代表":"如果……就……","例子":["如果下雨，就不去了。"]},{"类":"假如……就……式","说明":"假如引出假设。","代表":"假如……就……","例子":["假如明天不下雨，我们就去爬山。"]},{"类":"要是……就……式","说明":"要是引出假设，口语常用。","代表":"要是……就……","例子":["要是努力，就会进步。"]}],"怎么认":["前句是不是在假设一种还没发生的情况？是的。","有没有如果、假如、要是？有，多半是假设。","后句是不是在说假设成立会怎么样？是的。"],"辨析":"假设和条件的区别：假设多为未然（如果下雨，就不去了：雨还没下）；条件多为必要或充分（只有努力，才能成功：努力是必要条件）。看前句是假设还是条件。","例句解析":[{"句":"如果下雨，就不去了。","析":"下雨是假设，还没发生；不去了是假设下的结果。"},{"句":"如果周末不下雨，我们就去爬山。","析":"周末不下雨是假设，去爬山是假设下的结果。"}],"练习":[{"q":"下面哪个是假设复句？","options":["因为努力，所以成功","虽然累，但是坚持","如果下雨，就不去了","只有努力，才能成功"],"answer":2,"解析":"如果……就表示假设。","类":"如果……就……式"},{"q":"假设复句前句的情况一般是？","options":["已经发生","还没发生","正在发生","不会发生"],"answer":1,"解析":"假设多为未然，还没发生。","类":"如果……就……式"},{"q":"“假如明天不下雨，我们就去爬山”属于？","options":["假设复句","条件复句","因果复句","选择复句"],"answer":0,"解析":"假如……就表示假设。","类":"假如……就……式"}]},{"name":"条件复句","例子":["只有努力，才能成功","只有多练习，才能写好字","只有努力，才能成功。","只要下雨，地就会湿。","无论多难，我们都不放弃。","不管刮风下雨，他都坚持跑步。","只有团结，才能战胜困难。","只要有信心，就没有办不成的事。","无论走到哪里，都要诚实。","不管多晚，妈妈都等我回家。","只有多读多写，作文才能进步。","只要肯动脑，就没有难题。"],"口诀":"关联词：只有……才、只要……就","易错":"“只有……才”表必要条件，“只要……就”表充分条件","讲解":"条件与结果","深讲":"条件复句是条件与结果的复句；前句说条件，后句说在这个条件下会怎么样；条件分必要条件和充分条件，还有无条件。","分类":[{"类":"只有……才……式","说明":"必要条件：缺了这个条件就不行。","代表":"只有……才……","例子":["只有努力，才能成功。"]},{"类":"只要……就……式","说明":"充分条件：有了这个条件就够了。","代表":"只要……就……","例子":["只要多练习，就能写好字。"]},{"类":"无论……都……式","说明":"无条件：不管什么条件，结果都一样。","代表":"无论……都……","例子":["无论多难，我们都要坚持。"]}],"怎么认":["前句是不是在说条件？是的。","有没有只有……才、只要……就、无论……都？有，多半是条件。","问“在什么条件下”，能问出前句吗？能，说明前句是条件。"],"辨析":"只有……才和只要……就的区别：只有……才是必要条件（缺了不行：只有努力，才能成功）；只要……就是充分条件（有了就够：只要多练习，就能写好字）。不要混。","例句解析":[{"句":"只有努力，才能成功。","析":"努力是必要条件，缺了不行，是条件复句。"},{"句":"只有多练习，才能写好字。","析":"多练习是必要条件，是条件复句。"}],"练习":[{"q":"下面哪个是条件复句？","options":["因为努力，所以成功","如果下雨，就不去了","只有努力，才能成功","虽然累，但是坚持"],"answer":2,"解析":"只有……才表示必要条件，是条件。","类":"只有……才……式"},{"q":"“只有……才”表？","options":["充分条件","必要条件","假设","因果"],"answer":1,"解析":"只有……才表示缺了这个条件就不行。","类":"只有……才……式"},{"q":"“只要多练习，就能写好字”中，“只要……就”表？","options":["必要条件","充分条件","假设","转折"],"answer":1,"解析":"只要……就表示有了这个条件就够了。","类":"只要……就……式"}]}],"name":"复句的类型（7种）"},{"id":"guanlianci","name":"关联词（10组）","items":[{"name":"因为…所以…","讲解":"表示因果关系：前因后果。","深讲":"因为……所以……表示因果关系：前句说原因，后句说结果；前后主语相同，关联词放主语后；主语不同，关联词放主语前；因为和但是不能配对，不能说“因为……但是……”。","分类":[{"类":"因为……所以……式","说明":"最常用的因果搭配，先因后果。","代表":"因为……所以……","例子":["因为下雨，所以运动会取消了。"]},{"类":"由于……因此……式","说明":"由于引出原因，因此引出结果。","代表":"由于……因此……","例子":["由于生病，因此他没去上学。"]},{"类":"先果后因式","说明":"先说结果，后说原因。","代表":"……，因为……","例子":["他没去上学，因为生病了。"]}],"怎么认":["前后是不是原因和结果？是的。","有没有因为、由于这类表原因的词？有。","问“为什么”，能问出前句吗？能，说明前句是原因。"],"辨析":"因为……所以……不能和但是配对。“因为下雨，但是没耽误”是错的：因为表原因，但是表转折，两者不能混用。想表转折，用虽然……但是。","例句解析":[{"句":"因为下雨，所以运动会取消了。","析":"下雨是原因，运动会取消是结果，是因果关系。"},{"句":"因为他努力，所以考了第一。","析":"努力是原因，考第一是结果；前后主语不同，关联词在句首。"}],"练习":[{"q":"下面哪个搭配是对的？","options":["因为……但是……","因为……所以……","因为……而且……","因为……还是……"],"answer":1,"解析":"因为配所以表因果，不能配但是。","类":"因为……所以……式"},{"q":"“他没去上学，因为生病了”属于？","options":["先因后果","先果后因","转折","假设"],"answer":1,"解析":"先说结果没去上学，后说原因生病了。","类":"先果后因式"},{"q":"“由于生病，因此他没去上学”中，原因是？","options":["没去上学","生病","他","因此"],"answer":1,"解析":"由于引出原因生病，因此引出结果。","类":"由于……因此……式"}],"例子":["因为下雨，所以运动会取消了","因为他努力，所以考了第一","因为下雨，所以地面湿了。","因为生病，所以他请假了。","因为坚持锻炼，所以身体很好。","因为粗心，所以他算错了题。","因为天黑，所以打开了路灯。","因为缺水，所以禾苗枯了。","因为准备充分，所以考得很好。","因为帮助别人，所以大家喜欢他。","因为起得早，所以赶上了火车。","因为爱读书，所以知识丰富。"],"口诀":"前因后果","易错":"不能说“因为…但是…”"},{"name":"如果…就…","讲解":"表示假设：假设条件下的结果。","深讲":"如果……就……表示假设：前句假设一种还没发生的情况，后句说在这种情况下会怎么样；前后主语相同，关联词放主语后；不同，放主语前。","分类":[{"类":"如果……就……式","说明":"最常用的假设搭配。","代表":"如果……就……","例子":["如果明天下雨，我们就不去春游了。"]},{"类":"假如……就……式","说明":"假如引出假设。","代表":"假如……就……","例子":["假如你来，我就告诉你。"]},{"类":"要是……就……式","说明":"要是引出假设，口语常用。","代表":"要是……就……","例子":["要是努力，就会进步。"]}],"怎么认":["前句是不是在假设还没发生的情况？是的。","有没有如果、假如、要是？有。","后句是不是在说假设成立会怎么样？是的。"],"辨析":"如果……就……和只有……才……的区别：如果表假设（如果下雨，就不去了），只有表必要条件（只有努力，才能成功）。看前句是假设还是必要条件。","例句解析":[{"句":"如果明天下雨，我们就不去春游了。","析":"明天下雨是假设，不去春游是假设下的结果。"},{"句":"如果你来，我就告诉你。","析":"你来是假设，告诉你是假设下的结果；前后主语不同，关联词在主语前。"}],"练习":[{"q":"下面哪个是假设关系？","options":["因为努力，所以成功","如果下雨，就不去了","只有努力，才能成功","虽然累，但是坚持"],"answer":1,"解析":"如果……就表示假设。","类":"如果……就……式"},{"q":"“假如你来，我就告诉你”属于？","options":["假设","条件","因果","转折"],"answer":0,"解析":"假如……就表示假设。","类":"假如……就……式"},{"q":"假设的情况一般是？","options":["已经发生","还没发生","正在发生","不会发生"],"answer":1,"解析":"假设多为未然，还没发生。","类":"如果……就……式"}],"例子":["如果明天下雨，我们就不去春游了","如果你来，我就告诉你","如果明天下雨，我们就待在家里。","如果你有困难，就告诉我。","如果努力学习，就能取得好成绩。","如果他来了，就一起出发。","如果不抓紧，就来不及了。","如果你同意，我们就签约。","如果天晴，我们就去放风筝。","如果累了，就休息一会儿。","如果遇到难题，就问老师。","如果我是你，就会接受。"],"口诀":"假设条件","易错":"假设多为还没发生的事"},{"name":"虽然…但是…","讲解":"表示转折：前后意思相反或相对。","深讲":"虽然……但是……表示转折：前句先让一步，后句一转，说出相反或相对的意思；前后主语相同，关联词放主语后；不同，放主语前；转折的后句不能省。","分类":[{"类":"虽然……但是……式","说明":"最常用的转折搭配。","代表":"虽然……但是……","例子":["虽然下雨了，但是我们照常上课。"]},{"类":"尽管……还是……式","说明":"尽管让步，还是表示转折的结果。","代表":"尽管……还是……","例子":["尽管他很累，还是坚持跑完了。"]},{"类":"虽然……，……式","说明":"后句转折词省略，但意思仍是转折。","代表":"虽然……，……","例子":["虽然下雨，我们照常上课。"]}],"怎么认":["前后意思是不是相反或相对？是的。","有没有虽然、尽管这类让步词？有。","去掉后句，前句的意思还完整吗？不完整，说明转折在后句。"],"辨析":"虽然……但是……和因为……所以……的区别：虽然表转折（虽然下雨，但是照常上课），因为表因果（因为下雨，所以取消）。不能说“因为……但是……”。","例句解析":[{"句":"虽然下雨了，但是我们照常上课。","析":"下雨和照常上课相对，是转折关系。"},{"句":"虽然他很累，但是坚持跑完了。","析":"累和坚持跑完相对，是转折关系；前后主语相同，关联词在主语后。"}],"练习":[{"q":"下面哪个是转折关系？","options":["因为努力，所以成功","虽然下雨，但是照常上课","如果下雨，就不去了","只有努力，才能成功"],"answer":1,"解析":"虽然……但是表示转折。","类":"虽然……但是……式"},{"q":"“尽管他很累，还是坚持跑完了”属于？","options":["转折","因果","递进","并列"],"answer":0,"解析":"尽管……还是表示转折。","类":"尽管……还是……式"},{"q":"“因为……但是……”对吗？","options":["对","不对","有时对","看情况"],"answer":1,"解析":"因为表原因，但是表转折，不能配对。","类":"虽然……但是……式"}],"例子":["虽然下雨了，但是我们照常上课","虽然他很累，但是坚持跑完了","虽然天气很冷，但是他坚持跑步。","虽然作业很多，但是他很快写完了。","虽然失败了，但是他不灰心。","虽然年纪小，但是他很懂事。","虽然路很远，但是我们走到了。","虽然很累，但是妈妈还在做饭。","虽然下雨，但是比赛继续进行。","虽然他病了，但是坚持上学。","虽然时间紧，但是任务完成了。","虽然贵了点，但是很实用。"],"口诀":"先让后转","易错":"前后意思要相反或相对"},{"name":"不但…而且…","讲解":"表示递进：后分句比前分句更进一层。","深讲":"不但……而且……表示递进：后句比前句更进一层，顺序不能颠倒；前后主语相同，关联词放主语后；不同，放主语前。","分类":[{"类":"不但……而且……式","说明":"最常用的递进搭配。","代表":"不但……而且……","例子":["他不但学习好，而且爱运动。"]},{"类":"不仅……还……式","说明":"不仅引出前一层，还引出更进一层。","代表":"不仅……还……","例子":["她不仅画画好，还写得一手好字。"]},{"类":"不但……，甚至……式","说明":"后句用甚至，表示进到出乎意料的一层。","代表":"不但……，甚至……","例子":["他不但会唱歌，甚至会作曲。"]}],"怎么认":["后句是不是比前句更进一层？是的。","有没有不但、不仅、甚至？有。","前后换个位置，意思还顺吗？不顺，说明顺序不能颠倒。"],"辨析":"不但……而且……和既……又……的区别：不但表递进（更进一层），既表并列（平行）。“不但学习好，而且爱运动”是递进；“既聪明又勤奋”是并列。","例句解析":[{"句":"他不但学习好，而且爱运动。","析":"爱运动比学习好更进一层，是递进关系。"},{"句":"她不但画画好，而且字也写得漂亮。","析":"字漂亮比画画好更进一层，是递进关系。"}],"练习":[{"q":"下面哪个是递进关系？","options":["他既聪明又勤奋","他不但学习好，而且爱运动","他来了，我也来了","因为努力，所以成功"],"answer":1,"解析":"不但……而且表示更进一层。","类":"不但……而且……式"},{"q":"递进关系前后顺序能颠倒吗？","options":["能","不能","有时能","看情况"],"answer":1,"解析":"递进是进一层的关系，顺序不能颠倒。","类":"不但……而且……式"},{"q":"“她不仅画画好，还写得一手好字”属于？","options":["并列","递进","转折","因果"],"answer":1,"解析":"不仅……还表示更进一层。","类":"不仅……还……式"}],"例子":["他不但学习好，而且爱运动","她不但画画好，而且字也写得漂亮","他不但学习好，而且体育好。","这家店不但便宜，而且质量好。","小明不但聪明，而且勤奋。","春天不但温暖，而且多彩。","她不但会唱歌，而且会弹琴。","这本书不但有趣，而且有用。","他不但跑得快，而且跳得高。","妈妈不但会做饭，而且会织毛衣。","这个问题不但重要，而且紧急。","教室不但干净，而且明亮。"],"口诀":"层层递进","易错":"递进顺序不能颠倒"},{"name":"只有…才…","讲解":"表示必要条件：缺了这个条件就不行。","深讲":"只有……才……表示必要条件：缺了这个条件就不行；别和只要……就……搞混，那是充分条件，有了就够了。","分类":[{"类":"只有……才……式","说明":"最常用的必要条件搭配。","代表":"只有……才……","例子":["只有努力，才能成功。"]},{"类":"唯有……才……式","说明":"唯有和只有意思一样，语气较正式。","代表":"唯有……才……","例子":["唯有努力，才有收获。"]},{"类":"除非……才……式","说明":"除非引出必要条件，意思和只有一样。","代表":"除非……才……","例子":["除非努力，才会成功。"]}],"怎么认":["前句是不是缺了就不行的条件？是的。","有没有只有、唯有、除非？有。","把前句去掉，后句还能成立吗？不能，说明前句是必要条件。"],"辨析":"只有……才……和只要……就……的区别：只有是必要条件（缺了不行：只有努力，才能成功），只要是充分条件（有了就够：只要多练习，就能写好字）。","例句解析":[{"句":"只有努力，才能成功。","析":"努力是必要条件，缺了不行，是条件关系。"},{"句":"只有多练习，才能写好字。","析":"多练习是必要条件，是条件关系。"}],"练习":[{"q":"下面哪个是必要条件？","options":["只要多练习，就能写好字","只有努力，才能成功","如果下雨，就不去了","因为努力，所以成功"],"answer":1,"解析":"只有……才表示缺了不行。","类":"只有……才……式"},{"q":"“除非努力，才会成功”属于？","options":["必要条件","充分条件","假设","因果"],"answer":0,"解析":"除非……才和只有……才一样，表必要条件。","类":"除非……才……式"},{"q":"“唯有努力，才有收获”中，“唯有”的意思是？","options":["只要","只有","如果","因为"],"answer":1,"解析":"唯有和只有意思一样，表必要条件。","类":"唯有……才……式"}],"例子":["只有努力，才能成功","只有多练习，才能写好字","只有努力学习，才能考上好学校。","只有团结一心，才能战胜困难。","只有多练习，才能写好字。","只有诚实，才能赢得信任。","只有坚持，梦想才能实现。","只有爱护环境，家园才更美丽。","只有认真听讲，才能真正学会。","只有付出，才有回报。","只有经历风雨，才能见彩虹。","只有打好基础，才能走得更远。"],"口诀":"必要条件","易错":"别和“只要…就…”搞混（那是充分条件）"},{"name":"无论…都…","讲解":"表示无条件：不管什么情况，结果都一样。","深讲":"无论……都……表示无条件：不管什么情况，结果都一样；无论后面常跟疑问词，如谁、哪儿、什么。","分类":[{"类":"无论……都……式","说明":"最常用的无条件搭配。","代表":"无论……都……","例子":["无论刮风下雨，他都按时到校。"]},{"类":"不管……都……式","说明":"不管和无论意思一样，口语常用。","代表":"不管……都……","例子":["不管多难，我们都要坚持。"]},{"类":"无论+疑问词式","说明":"无论后跟疑问词，表示任何情况都一样。","代表":"无论谁、哪儿、什么……都……","例子":["无论谁问，他都不说。"]}],"怎么认":["不管什么情况，结果是不是都一样？是的。","有没有无论、不管？有。","无论后是不是跟了疑问词（谁、哪儿、什么）？是的，多半是无条件。"],"辨析":"无论……都……和如果……就……的区别：无论表无条件（不管怎样结果都一样），如果表假设（假设成立结果才来）。看结果是不是不依赖条件。","例句解析":[{"句":"无论刮风下雨，他都按时到校。","析":"刮风下雨与否，结果都一样按时到校，是无条件。"},{"句":"无论谁问，他都不说。","析":"谁问都一样不说，是无条件；无论后跟疑问词谁。"}],"练习":[{"q":"下面哪个是无条件关系？","options":["如果下雨，就不去了","无论刮风下雨，他都按时到校","只有努力，才能成功","因为努力，所以成功"],"answer":1,"解析":"无论……都表示不管怎样结果都一样。","类":"无论……都……式"},{"q":"“无论谁问，他都不说”中，“无论”后跟的是？","options":["名词","疑问词","动词","形容词"],"answer":1,"解析":"无论后可跟疑问词谁。","类":"无论+疑问词式"},{"q":"“不管多难，我们都要坚持”属于？","options":["无条件","假设","必要条件","因果"],"answer":0,"解析":"不管……都和无论……都一样，表无条件。","类":"不管……都……式"}],"例子":["无论刮风下雨，他都按时到校","无论谁问，他都不说","无论多么困难，我们都不放弃。","无论刮风下雨，他都按时到校。","无论走到哪里，我都想念家乡。","无论多忙，妈妈都记得我的生日。","无论结果如何，我们都尽力了。","无论多晚，他都坚持把作业写完。","无论谁问起，他都实话实说。","无论天气怎样，运动会都照常举行。","无论多累，战士们都不停下脚步。","无论遇到什么，都要勇敢面对。"],"口诀":"条件再多都不怕","易错":"“无论”后可跟疑问词：无论谁/哪儿/什么"},{"name":"既…又…","讲解":"表示并列：两个方面同时成立。","深讲":"既……又……表示并列：两个方面同时成立，地位平等；前后感情色彩要一致，不能既好又坏。","分类":[{"类":"品格并列式","说明":"并列的两个方面都是人的品格、优点。","代表":"既……又……","例子":["他既聪明又勤奋。"]},{"类":"特点并列式","说明":"并列的两个方面都是事物的特点。","代表":"既……又……","例子":["这件衣服既好看又便宜。"]}],"怎么认":["两个方面是不是同时成立、地位平等？是的。","有没有既……又……？有。","前后感情色彩一致吗？一致，才是规范的既……又……。"],"辨析":"既……又……和不但……而且……的区别：既表并列（平行：既聪明又勤奋），不但表递进（更进一层：不但聪明，而且勤奋得出了名）。看后句是不是更进一层。","例句解析":[{"句":"他既聪明又勤奋。","析":"聪明和勤奋同时成立、地位平等，是并列关系。"},{"句":"这件衣服既好看又便宜。","析":"好看和便宜都是这件衣服的特点，地位平等，是并列关系。"}],"练习":[{"q":"下面哪个是并列关系？","options":["他不但聪明，而且勤奋","他既聪明又勤奋","因为聪明，所以成功","如果聪明，就成功"],"answer":1,"解析":"既……又表示平行并列。","类":"品格并列式"},{"q":"“既……又……”前后感情色彩要？","options":["相反","一致","无关","递进"],"answer":1,"解析":"前后感情色彩要一致，不能既好又坏。","类":"品格并列式"},{"q":"“这件衣服既好看又便宜”属于？","options":["并列","递进","转折","因果"],"answer":0,"解析":"好看和便宜平行，是并列。","类":"特点并列式"}],"例子":["他既聪明又勤奋","这件衣服既好看又便宜","他既聪明又勤奋。","这苹果既大又甜。","教室里既干净又安静。","她既会唱歌又会跳舞。","这件衣服既好看又便宜。","小狗既可爱又听话。","秋天既凉爽又美丽。","他既是班长又是课代表。","这个问题既有趣又有意义。","湖水既清又静。"],"口诀":"两个优点一起夸","易错":"前后感情色彩要一致（不能既好又坏）"},{"name":"不是…而是…","讲解":"表示选择：否定前者，肯定后者。","深讲":"不是……而是……表示选择：否定前者，肯定后者；前后要是同一类事物才能这样选，不能拿不同类的东西比。","分类":[{"类":"否定原因式","说明":"否定一个原因，肯定另一个原因。","代表":"不是……而是……","例子":["他不是不认真，而是方法不对。"]},{"类":"否定事物式","说明":"否定一个事物，肯定另一个事物。","代表":"不是……而是……","例子":["这不是苹果，而是梨子。"]}],"怎么认":["是不是先否定一个，再肯定一个？是的。","有没有不是……而是……？有。","前后是不是同一类事物？是的，才能这样选。"],"辨析":"不是……而是……和是……还是……的区别：不是……而是……是说话人自己选定后者（不是苹果，而是梨子）；是……还是……是让对方选（是苹果还是梨子）。","例句解析":[{"句":"他不是不认真，而是方法不对。","析":"否定不认真，肯定方法不对，是选择关系。"},{"句":"我不是不想去，而是有事。","析":"否定不想去，肯定有事，是选择关系。"}],"练习":[{"q":"下面哪个是“不是……而是……”关系？","options":["是去还是留","他不是不认真，而是方法不对","因为认真，所以成功","虽然累，但是坚持"],"answer":1,"解析":"先否定不认真，再肯定方法不对。","类":"否定原因式"},{"q":"“这不是苹果，而是梨子”属于？","options":["选择","并列","因果","转折"],"answer":0,"解析":"否定苹果，肯定梨子，是选择。","类":"否定事物式"},{"q":"“不是……而是……”前后要是？","options":["不同类事物","同一类事物","无关事物","相反事物"],"answer":1,"解析":"前后要是同一类事物才能这样选。","类":"否定事物式"}],"例子":["他不是不认真，而是方法不对","我不是不想去，而是有事","他不是不努力，而是方法不对。","这不是失败，而是新的开始。","成功不是偶然，而是坚持的结果。","他不是生病，而是有事出去了。","这不是批评，而是真诚的建议。","爱不是占有，而是付出。","他不是不想去，而是没时间。","这道题不是不会，而是有点难。","真正的朋友不是锦上添花，而是雪中送炭。","学习不是为了分数，而是为了成长。"],"口诀":"否定一个，肯定一个","易错":"前后要是同一类事物才能这样选"},{"name":"先…然后…","讲解":"表示承接：按顺序做事情。","深讲":"先……然后……表示承接：按顺序做事情，先做的放前面，后做的放后面，顺序不能乱；这是承接关系，在复句7种里没有单列，在关联词里学。","分类":[{"类":"先……然后……式","说明":"最常用的承接搭配。","代表":"先……然后……","例子":["先洗手，然后吃饭。"]},{"类":"先……，再……式","说明":"再和然后意思一样，表接着做。","代表":"先……，再……","例子":["先洗手，再吃饭。"]},{"类":"先……，接着……式","说明":"接着表示紧接着做下一步。","代表":"先……，接着……","例子":["先写作业，接着看电视。"]}],"怎么认":["是不是按顺序做事情？是的。","有没有先……然后、先……再？有。","前后换个位置，顺序还对吗？不对，说明顺序不能乱。"],"辨析":"先……然后……和一……就……的区别：先然后表顺序（先洗手，然后吃饭：两件事有先后），一就表紧接（我一回家就写作业：两件事挨得很紧）。","例句解析":[{"句":"先洗手，然后吃饭。","析":"洗手在前，吃饭在后，按顺序做，是承接关系。"},{"句":"先写作业，然后才能看电视。","析":"写作业在前，看电视在后，是承接关系。"}],"练习":[{"q":"下面哪个是承接关系？","options":["我一回家就写作业","先洗手，然后吃饭","因为累，所以休息","虽然累，但是坚持"],"answer":1,"解析":"先……然后表示按顺序做事情。","类":"先……然后……式"},{"q":"承接关系前后顺序能乱吗？","options":["能","不能","有时能","看情况"],"answer":1,"解析":"先做的放前面，顺序不能乱。","类":"先……然后……式"},{"q":"“先洗手，再吃饭”属于？","options":["承接","紧接","因果","并列"],"answer":0,"解析":"先……再……和先……然后……一样，表承接。","类":"先……，再……式"}],"例子":["先洗手，然后吃饭","先写作业，然后才能看电视","先洗手，然后吃饭。","先读题目，然后再下笔。","先穿上外套，然后再出门。","做数学题要先审题，然后计算。","先把桌子擦干净，然后摆好书本。","他先跑完步，然后去洗澡。","先听老师讲，然后自己练习。","做饭要先洗菜，然后切菜。","先完成作业，然后才能玩。","他先道歉，然后解释了原因。"],"口诀":"事情有先后","易错":"顺序不能乱，先做的放前面"},{"name":"一…就…","讲解":"表示紧接：两个动作挨得很紧。","深讲":"一……就……表示紧接：两个动作挨得很紧，前一个动作一发生，后一个动作马上跟着发生；一……就……中间别加太多字。","分类":[{"类":"一……就……式","说明":"最常用的紧接搭配。","代表":"一……就……","例子":["我一回家就写作业。"]},{"类":"刚……就……式","说明":"刚表示刚刚发生，就表示马上跟着。","代表":"刚……就……","例子":["他刚回家就写作业。"]},{"类":"一听一看就……式","说明":"一听、一看这类感官动作一发生，反应马上来。","代表":"一……就……","例子":["他一听音乐就开心。"]}],"怎么认":["两个动作是不是挨得很紧？是的。","有没有一……就、刚……就？有。","前一个动作一发生，后一个是不是马上跟着？是的。"],"辨析":"一……就……和先……然后……的区别：一就表紧接（我一回家就写作业：挨得很紧），先然后表顺序（先洗手，然后吃饭：有先后，不一定紧接）。","例句解析":[{"句":"我一回家就写作业。","析":"回家一发生，写作业马上跟着，是紧接关系。"},{"句":"他一听音乐就开心。","析":"一听音乐，开心马上来，是紧接关系。"}],"练习":[{"q":"下面哪个是紧接关系？","options":["先洗手，然后吃饭","我一回家就写作业","因为累，所以休息","虽然累，但是坚持"],"answer":1,"解析":"一……就表示两个动作挨得很紧。","类":"一……就……式"},{"q":"“他刚回家就写作业”属于？","options":["紧接","承接","因果","并列"],"answer":0,"解析":"刚……就和一……就一样，表紧接。","类":"刚……就……式"},{"q":"“一……就……”中间别加？","options":["太多字","关联词","主语","谓语"],"answer":0,"解析":"一……就……中间别加太多字。","类":"一……就……式"}],"例子":["我一回家就写作业","他一听音乐就开心","我一回家就写作业。","他一看到我就笑了。","天一黑，路灯就亮了。","妈妈一回来，小狗就摇尾巴。","他一上车就睡着了。","春天一到，花儿就开了。","铃声一响，同学们就进教室了。","我一打开书，就被吸引住了。","他一听说，就赶来了。","雨一停，孩子们就跑出去玩了。"],"口诀":"紧接着发生","易错":"“一…就…”中间别加太多字"}]},{"id":"xiuci","items":[{"name":"比喻","例子":["他像豹子一样快","天上的云像棉花糖","天上的云像棉花糖一样白。","他跑得像豹子一样快。","月亮像玉盘挂在天上。","老师的爱像春雨滋润心田。","西湖像一面明镜。","她的脸红得像苹果。","时间像流水一去不回。","柳条像姑娘的长发随风飘。","雪花像鹅毛纷纷落下。","他高兴得像吃了蜜一样甜。"],"口诀":"生动形象","易错":"有“像”不一定是比喻（如表示举例）","讲解":"打比方，生动形象","深讲":"比喻是打比方：把一个事物比作另一个事物，让人一听就明白、一想就形象；本体和喻体必须是不同类的事物，否则就不是比喻，只是比较。","分类":[{"类":"明喻","说明":"有像、如、似这类喻词，本体、喻体都出现。","代表":"像、如、似","例子":["天上的云像棉花糖。"]},{"类":"暗喻","说明":"用是、变成连接，本体、喻体都出现，没有像。","代表":"是、变成","例子":["老师是辛勤的园丁。"]},{"类":"借喻","说明":"只出现喻体，本体不出现，借喻体来说本体。","代表":"只说喻体","例子":["一群花朵走进了教室。"]}],"怎么认":["句子里有没有把甲说成乙？有。","甲和乙是不是不同类的事物？是的，才是比喻。","有没有像、是这类喻词？有，帮助判断是明喻还是暗喻。"],"辨析":"有“像”不一定是比喻。表示举例、比较的“像”不是比喻：他像他爸爸一样高，是比较（人和人同类），不是比喻；天上的云像棉花糖，是比喻（云和棉花糖不同类）。","例句解析":[{"句":"天上的云像棉花糖。","析":"云是本体，棉花糖是喻体，像是喻词，是明喻。"},{"句":"他像豹子一样快。","析":"他是本体，豹子是喻体，像是喻词，是明喻。"}],"练习":[{"q":"下面哪个是比喻？","options":["他像他爸爸一样高","天上的云像棉花糖","他比我高","他和我一样大"],"answer":1,"解析":"云和棉花糖不同类，是比喻；他和爸爸同类，是比较。","类":"明喻"},{"q":"“老师是辛勤的园丁”属于？","options":["明喻","暗喻","借喻","拟人"],"answer":1,"解析":"用是连接，没有像，是暗喻。","类":"暗喻"},{"q":"“一群花朵走进了教室”属于？","options":["明喻","暗喻","借喻","夸张"],"answer":2,"解析":"只出现喻体花朵，本体孩子不出现，是借喻。","类":"借喻"}],"图示":"<svg viewBox=\"0 0 320 160\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">比喻：本体＋喻词＋喻体，三件套</text><text x=\"12\" y=\"42\" font-size=\"11\" class=\"svg-accent\">本体<animate attributeName=\"opacity\" values=\"1;1;0.35;0.35;1\" keyTimes=\"0;0.3;0.33;0.97;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"105\" y=\"42\" font-size=\"11\" class=\"svg-accent\">喻词<animate attributeName=\"opacity\" values=\"0.35;0.35;1;1;0.35;0.35\" keyTimes=\"0;0.3;0.33;0.6;0.63;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"130\" y=\"42\" font-size=\"11\" class=\"svg-accent\">喻体<animate attributeName=\"opacity\" values=\"0.35;0.35;0.35;1;1;0.35\" keyTimes=\"0;0.6;0.63;0.9;0.93;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"12\" y=\"70\" font-size=\"17\" class=\"svg-ink\">弯弯的月儿</text><text x=\"105\" y=\"70\" font-size=\"17\" class=\"svg-accent\">像<animate attributeName=\"opacity\" values=\"1;1;1;1;1;1\" keyTimes=\"0;0.3;0.33;0.6;0.63;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"130\" y=\"70\" font-size=\"17\" class=\"svg-ink\">小小的船</text><path d=\"M45,86 Q110,112 180,86\" stroke-width=\"1.5\" fill=\"none\" stroke-dasharray=\"4,3\"/ class=\"svg-muted-s\"><circle r=\"4\" class=\"svg-accent\"><animateMotion dur=\"3s\" repeatCount=\"indefinite\" path=\"M45,86 Q110,112 180,86\"/></circle><text x=\"12\" y=\"140\" font-size=\"12\" class=\"svg-muted\">月儿（本体）像（喻词）小船（喻体），金点来回穿梭</text></svg>"},{"name":"拟人","例子":["小草向我点头","风儿轻轻地抚摸着我的脸","小鸟在枝头唱歌跳舞。","风儿轻轻地抚摸着我的脸。","花儿向我们点头微笑。","小溪唱着歌流向远方。","月亮悄悄地爬上了树梢。","柳树姑娘甩着长辫子。","太阳公公露出了笑脸。","小草从土里探出头来。","星星眨着眼睛看我们。","秋风温柔地拥抱着大地。"],"口诀":"赋予情感","易错":"拟人与比喻可兼用","讲解":"把物当人写","深讲":"拟人是把物当人写：让花草、风雨、小动物像人一样动作、说话、有感情；拟人让没有生命的东西活起来，读起来亲切。","分类":[{"类":"动作拟人","说明":"让物像人一样做动作。","代表":"点头、跑、跳","例子":["小草向我点头。"]},{"类":"情感拟人","说明":"让物像人一样有感情。","代表":"笑、哭、高兴","例子":["花儿笑了。"]},{"类":"语言拟人","说明":"让物像人一样说话。","代表":"说、唱、叫","例子":["小鸟对我说：“早上好。”"]}],"怎么认":["主语是不是没有生命的东西？是的。","它做的是不是只有人才做的事（说话、点头、笑）？是的。","把主语换成人，句子还通吗？通，说明是拟人。"],"辨析":"拟人和比喻可兼用，但不一样：拟人是把物当人（小草点头），比喻是把甲比作乙（云像棉花糖）。“风儿抚摸着我的脸”是拟人，不是比喻，因为没有比作什么。","例句解析":[{"句":"小草向我点头。","析":"小草不会点头，点头是人的动作，是拟人。"},{"句":"风儿轻轻地抚摸着我的脸。","析":"抚摸是人的动作，风儿被当成人写，是拟人。"}],"练习":[{"q":"下面哪个是拟人？","options":["天上的云像棉花糖","小草向我点头","他跑得很快","白发三千丈"],"answer":1,"解析":"小草点头是人的动作，是拟人。","类":"动作拟人"},{"q":"“花儿笑了”属于？","options":["动作拟人","情感拟人","语言拟人","比喻"],"answer":1,"解析":"笑是感情，花儿被写出了感情。","类":"情感拟人"},{"q":"“小鸟对我说：早上好”属于？","options":["动作拟人","情感拟人","语言拟人","夸张"],"answer":2,"解析":"小鸟说话，是语言拟人。","类":"语言拟人"}]},{"name":"夸张","例子":["白发三千丈","教室里安静得连针掉地上都听得见","他跑得比风还快。","这间屋子大得能装下一头大象。","我饿得能吃下一头牛。","教室里静得连针掉在地上都听得见。","他高兴得一蹦三尺高。","飞流直下三千尺，疑是银河落九天。","白发三千丈，缘愁似个长。","这道题难得比登天还难。","他气得火冒三丈。","操场上的人山人海一眼望不到边。"],"口诀":"突出强调","易错":"夸张要合理，不能失真","讲解":"故意夸大或缩小","深讲":"夸张是故意夸大或缩小：把事物说得比实际更大、更小、更多、更少，用来突出强调；夸张要合理，不能失真，让人一听就知道是夸张，不是真的。","分类":[{"类":"扩大夸张","说明":"把事物说得比实际大得多。","代表":"三千丈、飞流直下","例子":["白发三千丈。"]},{"类":"缩小夸张","说明":"把事物说得比实际小得多。","代表":"巴掌大、一根针","例子":["教室只有巴掌大。"]}],"怎么认":["句子里的数目、程度是不是大得或小得不可能？是的。","去掉夸张，事物本身还成立吗？成立，只是没那么突出。","作者是不是在强调、突出？是的。"],"辨析":"夸张和说谎不一样：夸张是故意夸大、让人一听就知道是夸张（白发三千丈）；说谎是想让人当真。夸张要合理，不能失真。","例句解析":[{"句":"白发三千丈。","析":"白发不可能真有三千丈，是扩大夸张，突出愁得多。"},{"句":"教室里安静得连针掉地上都听得见。","析":"安静被夸大到针掉地上都听得见，是扩大夸张。"}],"练习":[{"q":"下面哪个是夸张？","options":["天上的云像棉花糖","白发三千丈","小草向我点头","他跑得很快"],"answer":1,"解析":"白发不可能真有三千丈，是夸张。","类":"扩大夸张"},{"q":"“教室只有巴掌大”属于？","options":["扩大夸张","缩小夸张","比喻","拟人"],"answer":1,"解析":"教室被说得比实际小得多，是缩小夸张。","类":"缩小夸张"},{"q":"夸张要？","options":["让人当真","合理，不能失真","越大越好","越小越好"],"answer":1,"解析":"夸张要合理，不能失真。","类":"扩大夸张"}]},{"name":"排比","例子":["爱心是春风，是夏雨，是秋月","春天是花朵，是绿叶，是暖阳","读书使人充实，讨论使人机智，写作使人精确。","爱心是一盏灯，照亮别人，也温暖自己；爱心是一首歌，唱出希望，也带来快乐。","春天来了，花儿开了，草儿绿了，鸟儿叫了。","他爱学习，爱劳动，爱帮助人。","我们要讲文明，讲礼貌，讲卫生。","海是蓝的，天是蓝的，人的心也应该是蓝的。","理想是灯，照亮夜行的路；理想是火，点燃熄灭的灯。","红的花，绿的草，高大的树，构成了一幅美景。","学习要专心，吃饭要专心，做事要专心。","燕子去了，有再来的时候；杨柳枯了，有再青的时候。"],"口诀":"增强气势","易错":"排比项数一般三项以上","讲解":"三个以上结构相似的句子","深讲":"排比是由三个或三个以上结构相同或相似、语气一致的短语或句子排列在一起，用来增强气势；排比项一般三项以上，少了就不成排比。","分类":[{"类":"句子排比","说明":"由三个以上结构相同的句子组成。","代表":"是……，是……，是……","例子":["爱心是春风，是夏雨，是秋月。"]},{"类":"短语排比","说明":"由三个以上结构相同的短语组成。","代表":"又高、又壮、又结实","例子":["他长得又高、又壮、又结实。"]}],"怎么认":["有没有三个以上结构相同的短语或句子？有。","它们的语气是不是一致的？是的。","读起来是不是气势越来越强？是的。"],"辨析":"排比和反复的区别：排比是结构相同、内容不同（春风、夏雨、秋月）；反复是同一内容重复（盼望着，盼望着）。看内容是不是换了。","例句解析":[{"句":"爱心是春风，是夏雨，是秋月。","析":"三个句子结构相同，语气一致，是句子排比。"},{"句":"春天是花朵，是绿叶，是暖阳。","析":"三个句子结构相同，是句子排比。"}],"练习":[{"q":"下面哪个是排比？","options":["盼望着，盼望着，春天来了","爱心是春风，是夏雨，是秋月","天上的云像棉花糖","小草向我点头"],"answer":1,"解析":"三个句子结构相同，是排比；盼望着是反复。","类":"句子排比"},{"q":"排比项数一般？","options":["一项","两项","三项以上","不限"],"answer":2,"解析":"排比项数一般三项以上。","类":"句子排比"},{"q":"“他长得又高、又壮、又结实”属于？","options":["句子排比","短语排比","反复","对偶"],"answer":1,"解析":"三个结构相同的短语排列，是短语排比。","类":"短语排比"}]},{"name":"对偶","例子":["横眉冷对千夫指，俯首甘为孺子牛","书山有路勤为径，学海无涯苦作舟","明月松间照，清泉石上流。","两个黄鹂鸣翠柳，一行白鹭上青天。","海内存知己，天涯若比邻。","感时花溅泪，恨别鸟惊心。","春种一粒粟，秋收万颗子。","大漠孤烟直，长河落日圆。","几处早莺争暖树，谁家新燕啄春泥。","白日依山尽，黄河入海流。","野火烧不尽，春风吹又生。","举头望明月，低头思故乡。"],"口诀":"整齐凝练","易错":"对偶要求平仄相对（宽对可放宽）","讲解":"字数相等、结构相同、意义相关","深讲":"对偶是字数相等、结构相同、意义相关的两个句子相对成文，用来显得整齐凝练；对偶是两句，排比是三句以上，不要混。","分类":[{"类":"正对","说明":"上下句意思相近、互补。","代表":"书山有路勤为径，学海无涯苦作舟","例子":["书山有路勤为径，学海无涯苦作舟。"]},{"类":"反对","说明":"上下句意思相反、相对。","代表":"横眉冷对千夫指，俯首甘为孺子牛","例子":["横眉冷对千夫指，俯首甘为孺子牛。"]},{"类":"流水对","说明":"上下句意思连贯、承接，像流水一样。","代表":"欲穷千里目，更上一层楼","例子":["欲穷千里目，更上一层楼。"]}],"怎么认":["是不是两个句子？是的。","字数是不是相等、结构是不是相同？是的。","上下句意思是不是相关（相近、相反或承接）？是的。"],"辨析":"对偶和排比的区别：对偶是两句，字数相等、结构相同；排比是三句以上，结构相同、语气一致。数一数有几句，再看字数是不是相等。","例句解析":[{"句":"横眉冷对千夫指，俯首甘为孺子牛。","析":"两句字数相等、结构相同，意思相反，是反对。"},{"句":"书山有路勤为径，学海无涯苦作舟。","析":"两句字数相等、结构相同，意思相近互补，是正对。"}],"练习":[{"q":"下面哪个是对偶？","options":["爱心是春风，是夏雨，是秋月","横眉冷对千夫指，俯首甘为孺子牛","盼望着，盼望着，春天来了","天上的云像棉花糖"],"answer":1,"解析":"两句字数相等、结构相同、意思相反，是对偶。","类":"反对"},{"q":"对偶是几句？","options":["一句","两句","三句以上","不限"],"answer":1,"解析":"对偶是两个句子相对成文。","类":"正对"},{"q":"“欲穷千里目，更上一层楼”属于？","options":["正对","反对","流水对","排比"],"answer":2,"解析":"上下句意思连贯承接，是流水对。","类":"流水对"}]},{"name":"反复","例子":["盼望着，盼望着，春天来了","加油，加油，我们一定能赢！","盼望着，盼望着，东风来了，春天的脚步近了。","大山无言，小草无言，土地无言。","他说好，好，好，就这么办。","沉默啊，沉默啊，不在沉默中爆发，就在沉默中灭亡。","我们是光荣的少先队员，我们是祖国的未来。","学，学，再学；练，练，再练。","风啊，你轻轻地吹吧，吹吧。","走啊走啊，终于走到了山顶。","他笑了，笑了，开心地笑了。","雨，下吧，下吧，滋润干渴的大地吧。"],"口诀":"强调加深","易错":"与排比区别：反复是重复同一内容","讲解":"重复词语/句子强调","深讲":"反复是重复词语或句子，用来强调、加深印象；反复重复的是同一内容，排比换的是内容，不要混。","分类":[{"类":"词语反复","说明":"重复同一个词语。","代表":"盼望着，盼望着","例子":["盼望着，盼望着，春天来了。"]},{"类":"句子反复","说明":"重复同一个句子。","代表":"春天来了！春天来了！","例子":["春天来了！春天来了！花儿都开了。"]}],"怎么认":["有没有同一个词语或句子重复出现？有。","重复是不是为了强调？是的。","去掉重复，意思还在吗？在，只是强调弱了。"],"辨析":"反复和排比的区别：反复是同一内容重复（盼望着，盼望着），排比是结构相同、内容不同（春风、夏雨、秋月）。看重复的是不是同一个内容。","例句解析":[{"句":"盼望着，盼望着，春天来了。","析":"盼望着重复出现，是词语反复，用来强调盼望。"},{"句":"加油，加油，我们一定能赢！","析":"加油重复出现，是词语反复，用来强调鼓励。"}],"练习":[{"q":"下面哪个是反复？","options":["爱心是春风，是夏雨，是秋月","盼望着，盼望着，春天来了","天上的云像棉花糖","小草向我点头"],"answer":1,"解析":"盼望着重复，是反复；春风夏雨秋月是排比。","类":"词语反复"},{"q":"反复和排比的区别是？","options":["反复换内容，排比重复内容","反复重复同一内容，排比换内容","没有区别","反复是两句"],"answer":1,"解析":"反复重复同一内容，排比结构相同、内容不同。","类":"词语反复"},{"q":"“春天来了！春天来了！花儿都开了”属于？","options":["词语反复","句子反复","排比","对偶"],"answer":1,"解析":"同一个句子重复出现，是句子反复。","类":"句子反复"}]},{"name":"设问","例子":["是谁创造了世界？是我们劳动群众","谁是班上跑得最快的？是小明","是谁创造了人类世界？是我们劳动群众。","什么叫自律？自律就是自我约束、自我管理。","幸福是什么？幸福是帮助别人后的快乐。","谁是最可爱的人？是我们的战士。","怎样才能学好语文？多读、多写、多思考。","什么是勇敢？勇敢不是不害怕，而是害怕也向前。","春天在哪里？春天在枝头，在花间，在人们的心里。","为什么要读书？因为书是进步的阶梯。","谁言寸草心，报得三春晖？是说子女难报父母恩。","学而不思则罔，思而不学则殆，是什么意思？是说只学不想、只想不学都不行。"],"口诀":"引起注意","易错":"设问后一定要回答","讲解":"自问自答","深讲":"设问是自问自答：先提出问题，再自己回答，用来引起注意、引出下文；设问后一定要回答，不回答就不是设问。","分类":[{"类":"句首设问","说明":"在开头提问，引起注意。","代表":"是谁……？是……","例子":["是谁创造了世界？是我们劳动群众。"]},{"类":"句中设问","说明":"在中间提问，引出下文。","代表":"……是什么？……是……","例子":["祖国是什么？祖国是我们的家。"]}],"怎么认":["是不是先问后答？是的。","问句后面有没有回答？有，才是设问。","提问是不是为了引起注意、引出下文？是的。"],"辨析":"设问和反问的区别：设问自问自答（是谁创造了世界？是我们劳动群众）；反问不回答，答案隐含在问句里（这不是很清楚吗？）。看后面有没有回答。","例句解析":[{"句":"是谁创造了世界？是我们劳动群众。","析":"先问是谁创造了世界，再回答是劳动群众，是设问。"},{"句":"谁是班上跑得最快的？是小明。","析":"先问谁最快，再回答是小明，是设问。"}],"练习":[{"q":"下面哪个是设问？","options":["这不是很清楚吗？","是谁创造了世界？是我们劳动群众","天上的云像棉花糖","小草向我点头"],"answer":1,"解析":"自问自答，是设问；这不是很清楚吗是反问。","类":"句首设问"},{"q":"设问后一定要？","options":["不回答","回答","再问一次","换话题"],"answer":1,"解析":"设问后一定要回答。","类":"句首设问"},{"q":"“祖国是什么？祖国是我们的家”属于？","options":["句首设问","句中设问","反问","排比"],"answer":1,"解析":"在中间提问引出下文，是句中设问。","类":"句中设问"}]},{"name":"反问","例子":["这不是很清楚吗？","这么简单的题，你不会做吗？","难道我们不该好好学习吗？","这么冷的天，你怎么能穿这么少？","这件事难道不是他做的吗？","浪费粮食，难道不觉得可惜吗？","这么好的机会，怎能错过？","诚信是做人之本，难道不应该坚守吗？","你自己不努力，难道还怪别人？","这么简单的题，难道你不会做？","父母为我们付出这么多，难道不值得感恩吗？","现在不努力，更待何时？"],"口诀":"加强语气","易错":"反问后不回答，答案隐含其中","讲解":"用问句表肯定/否定，加强语气","深讲":"反问是用问句表示肯定或否定，用来加强语气；反问后不回答，答案隐含在问句里，听的人一听就明白。","分类":[{"类":"肯定式反问","说明":"用否定问句表示肯定。","代表":"不是……吗？","例子":["这不是很清楚吗？"]},{"类":"否定式反问","说明":"用肯定问句表示否定。","代表":"……吗？（表否定）","例子":["这么简单的题，你不会做吗？"]}],"怎么认":["是不是问句形式，但意思不是真的在问？是的。","问句后面有没有回答？没有，答案隐含其中。","把问句换成陈述句，意思是不是更直接？是的，说明是反问。"],"辨析":"反问和设问的区别：反问不回答（这不是很清楚吗？答案就是很清楚），设问自问自答（是谁创造了世界？是我们劳动群众）。看后面有没有回答。","例句解析":[{"句":"这不是很清楚吗？","析":"用否定问句表示肯定：很清楚，是反问。"},{"句":"这么简单的题，你不会做吗？","析":"用肯定问句表示否定：你应该会做，是反问。"}],"练习":[{"q":"下面哪个是反问？","options":["是谁创造了世界？是我们劳动群众","这不是很清楚吗？","天上的云像棉花糖","小草向我点头"],"answer":1,"解析":"不回答，答案隐含其中，是反问。","类":"肯定式反问"},{"q":"“这么简单的题，你不会做吗？”的意思是？","options":["你不会做","你应该会做","题很难","不知道"],"answer":1,"解析":"用肯定问句表示否定：你应该会做。","类":"否定式反问"},{"q":"反问后要不要回答？","options":["要","不要，答案隐含其中","有时要","看情况"],"answer":1,"解析":"反问后不回答，答案隐含在问句里。","类":"肯定式反问"}]}],"name":"常见修辞格（8种）"},{"id":"bingju","items":[{"name":"语序不当","例子":["病：他把教室打扫得干干净净、整整齐齐→改：把“整整齐齐”删去或调整","病：我昨天晚上把作业认真地写完了 → 改：我昨天晚上认真地把作业写完了","病：他把教室打扫得干干净净、整整齐齐→改：删去“整整齐齐”或改为“把教室打扫得干干净净”","病：我昨天晚上把作业认真地写完了→改：我昨天晚上认真地把作业写完了","病：一位优秀的我们班的学生→改：我们班的一位优秀的学生","病：他经常回忆起过去的往事→改：删去“过去”，“往事”已含过去义","病：我们要认真克服并发现缺点→改：我们要发现并认真克服缺点","病：他把一封信寄给我妈妈的→改：他把一封信寄给了我妈妈","病：同学们把校园打扫得整整齐齐、干干净净→改：删去重复义词语，留“干干净净”","病：他先把门关上，然后轻轻地→改：他轻轻地把门关上，然后离开"],"口诀":"先找主干，再看修饰","易错":"多重定语/状语语序是重灾区","讲解":"词语或分句顺序颠倒","深讲":"语序不当是词语或分句顺序颠倒：先找主干，再看修饰；多重定语、状语是重灾区。改法是：一读句子，二找主干，三看修饰语顺序，四调换位置。","分类":[{"类":"定语语序不当","说明":"多重定语排列顺序错了。","代表":"领属＋数量＋形容词＋名词","例子":["一位优秀的我们班的学生。"]},{"类":"状语语序不当","说明":"状语放错了位置。","代表":"时间＋认真地＋把＋作业","例子":["我昨天晚上把作业认真地写完了。"]}],"怎么认":["先压缩主干，看主谓宾齐不齐？齐。","再看修饰语：定语、状语的顺序对不对？不对。","调换修饰语位置，句子是不是顺了？顺了，说明是语序不当。"],"辨析":"语序不当和结构混乱的区别：语序不当是顺序颠倒，调换位置就顺了；结构混乱是两种句式纠缠，要删掉一种句式。看调换位置能不能修好。","例句解析":[{"句":"一位优秀的我们班的学生。","析":"领属定语我们班应在最前，改为：我们班的一位优秀的学生。"},{"句":"我昨天晚上把作业认真地写完了。","析":"状语认真地应在把字前，改为：我昨天晚上认真地把作业写完了。"}],"练习":[{"q":"“一位优秀的我们班的学生”错在哪？","options":["缺主语","定语语序不当","搭配不当","表意不明"],"answer":1,"解析":"领属定语我们班应在最前。","类":"定语语序不当"},{"q":"“我昨天晚上把作业认真地写完了”怎么改？","options":["我昨天晚上把作业写完了认真地","我昨天晚上认真地把作业写完了","我把作业昨天晚上认真地写完了","我昨天晚上把认真地作业写完了"],"answer":1,"解析":"状语认真地应在把字前。","类":"状语语序不当"},{"q":"多重定语的正确顺序是？","options":["形容词＋领属＋数量＋名词","领属＋数量＋形容词＋名词","数量＋形容词＋领属＋名词","名词＋领属＋数量＋形容词"],"answer":1,"解析":"领属在最前，再是数量、形容词，最后是名词。","类":"定语语序不当"}],"类比":"语序不当就像\"穿反了衣服\"：每件都在，但位置错了。"},{"name":"搭配不当","例子":["病：他怀着崇高的心情→改：怀着激动的心情","病：同学们都很爱护 → 改：同学们都很爱护公物","病：他的普通话说得很标准→改：他的普通话说得很流利（标准与“说”不搭配）","病：我们要养成良好的学习态度→改：养成良好的学习习惯（养成与习惯搭配）","病：他对自己很有信心，学习成绩很优异→改：删去“很优异”或改为“学习成绩优异”","病：经过努力，他的错别字大大进步了→改：错别字大大减少了（进步与减少搭配）","病：我们要端正学习目的→改：端正学习态度（端正与态度搭配）","病：他的写作水平有了很大的提高→改：正确（示例：提高与水平搭配恰当）","病：同学们都认真地完成了作业→改：正确（完成与作业搭配恰当）","病：他发扬了艰苦奋斗的精神→改：正确（发扬与精神搭配恰当）"],"口诀":"主谓动宾，一一对应","易错":"“怀着……心情”不能配“崇高”","讲解":"主谓、动宾、修饰语与中心词不搭配","深讲":"搭配不当是主谓、动宾、修饰语与中心词对不上号：主谓动宾一一对应，修饰语也要配中心词。改法是：压缩主干，检查每一对搭配。","分类":[{"类":"主谓搭配不当","说明":"主语和谓语对不上号。","代表":"人口是国家","例子":["我国的人口是世界上最多的国家。"]},{"类":"动宾搭配不当","说明":"动词和宾语对不上号。","代表":"端正学习","例子":["我们要端正学习。"]},{"类":"修饰搭配不当","说明":"修饰语和中心词对不上号。","代表":"怀着崇高的心情","例子":["他怀着崇高的心情。"]}],"怎么认":["压缩主干，主谓宾齐不齐？齐。","主语配谓语、动词配宾语、修饰语配中心词，一一检查。","有一对对不上，就是搭配不当。"],"辨析":"搭配不当和成分残缺的区别：搭配不当是成分齐了但配错了（端正学习）；成分残缺是成分缺了（同学们都很爱护，缺宾语）。看成分齐不齐。","例句解析":[{"句":"他怀着崇高的心情。","析":"崇高配精神、理想，不配心情，改为：怀着激动的心情。"},{"句":"我国的人口是世界上最多的国家。","析":"人口不能是国家，改为：我国是世界上人口最多的国家。"}],"练习":[{"q":"“他怀着崇高的心情”错在哪？","options":["缺宾语","修饰搭配不当","语序不当","表意不明"],"answer":1,"解析":"崇高不配心情，应配激动的心情。","类":"修饰搭配不当"},{"q":"“我们要端正学习”怎么改？","options":["我们要端正学习态度","我们要学习端正","我们要端正地学习","我们要学习"],"answer":0,"解析":"端正配态度，不配学习。","类":"动宾搭配不当"},{"q":"“我国的人口是世界上最多的国家”错在哪？","options":["动宾搭配不当","主谓搭配不当","语序不当","结构混乱"],"answer":1,"解析":"人口不能是国家，改为：我国是世界上人口最多的国家。","类":"主谓搭配不当"}],"类比":"搭配不当就像\"左脚穿右脚的鞋\"：单个看都对，放一起别扭。"},{"name":"成分残缺或赘余","例子":["病：通过学习，使我进步（缺主语）→删“使”","病：不约而同异口同声（赘余）","病：通过努力，取得了进步 → 改：通过努力，我取得了进步","病：看了这部电影，受到了深刻的教育→改：我看了这部电影，受到了深刻的教育（缺主语）","病：通过这次活动，使我明白了道理→改：这次活动使我明白了道理（删“通过”或“使”）","病：他把今天的任务→改：他把今天的任务完成了（缺谓语）","病：我们要学习雷锋同志全心全意为人民服务的→改：我们要学习雷锋同志全心全意为人民服务的精神（缺宾语）","病：他非常非常特别的高兴→改：他非常高兴（“非常非常特别”赘余）","病：大约有三百多人参加了会议→改：有三百多人参加了会议（“大约”与“多”重复）","病：他亲眼目睹了这件事的经过→改：他目睹了这件事的经过（“亲眼”与“目睹”重复）"],"口诀":"压缩主干，残缺立现","易错":"“通过……使”句式最易缺主语","讲解":"缺主/谓/宾，或词语重复多余","深讲":"成分残缺或赘余是缺主、谓、宾，或词语重复多余：压缩主干，残缺立现；意思重复，赘余立现。改法是：缺了补上，多了删去。","分类":[{"类":"主语残缺式","说明":"缺主语，话没了头。","代表":"通过……使……","例子":["通过学习，使我进步。"]},{"类":"宾语残缺式","说明":"缺宾语，动作没着落。","代表":"爱护后空着","例子":["同学们都很爱护。"]},{"类":"成分赘余式","说明":"词语意思重复，多余。","代表":"不约而同异口同声","例子":["不约而同异口同声。"]}],"怎么认":["压缩主干，主谓宾齐不齐？不齐，就是残缺。","有没有意思重复的词？有，就是赘余。","“通过……使……”句式最易缺主语，重点查。"],"辨析":"成分残缺和搭配不当的区别：残缺是缺了成分（通过学习，使我进步，缺主语）；搭配不当是成分齐了但配错了（端正学习）。看成分齐不齐。","例句解析":[{"句":"通过学习，使我进步。","析":"通过和使同时出现，主语被吃掉，删去使。"},{"句":"不约而同异口同声。","析":"不约而同和异口同声意思重复，删去一个。"}],"练习":[{"q":"“通过学习，使我进步”错在哪？","options":["搭配不当","主语残缺","语序不当","表意不明"],"answer":1,"解析":"通过和使同时出现，主语被吃掉。","类":"主语残缺式"},{"q":"“不约而同异口同声”错在哪？","options":["缺主语","缺宾语","成分赘余","结构混乱"],"answer":2,"解析":"两个词意思重复，多余。","类":"成分赘余式"},{"q":"“通过努力，取得了进步”怎么改？","options":["通过努力，使取得了进步","通过努力，我取得了进步","努力，取得了进步","通过努力，进步取得了"],"answer":1,"解析":"补上主语我。","类":"主语残缺式"}]},{"name":"结构混乱","例子":["病：原因是由于他努力→改：原因是他努力","病：这次活动是受到了大家的欢迎造成的 → 改：这次活动受到了大家的欢迎","病：我们来到山间，听见鸟叫，看见花开，感到心旷神怡的原因是景色太美了→改：我们来到山间，听见鸟叫，看见花开，感到心旷神怡（删“的原因是…”）","病：他的写作水平有了很大的提高是勤奋的结果→改：他的写作水平有了很大提高，这是勤奋的结果","病：这部电影，我看了三遍，很受感动的原因是剧情真实→改：这部电影我看了三遍，很受感动，因为剧情真实","病：老师对我们要求很严格是希望我们成才→改：老师对我们要求很严格，是希望我们成才","病：他之所以成功，是因为努力的结果→改：他之所以成功，是因为努力（删“的结果”）","病：问题的关键在于态度是否端正上→改：问题的关键在于态度是否端正（删“上”）","病：这件事的成败，在于大家齐心协力与否是关键→改：这件事的成败，在于大家是否齐心协力","病：关于这个问题，我的看法是认为应该慎重→改：关于这个问题，我认为应该慎重（删“的看法是”）"],"口诀":"两种句式，留一去一","易错":"“原因是由于”“是由于……造成的”典型杂糅","讲解":"句式杂糅，两种结构纠缠","深讲":"结构混乱是句式杂糅：两种结构纠缠在一起。改法是：两种句式，留一去一，认清一句话只能用一种结构。","分类":[{"类":"原因是由于式","说明":"原因和由于重复用了。","代表":"原因是由于……","例子":["原因是由于他努力。"]},{"类":"是……造成的式","说明":"是和受到……造成的纠缠。","代表":"是受到了……造成的","例子":["这次活动是受到了大家的欢迎造成的。"]}],"怎么认":["一句话里有没有两种句式？有。","删掉一种，句子是不是顺了？顺了。","“原因是由于”“是由于……造成的”是典型杂糅，重点查。"],"辨析":"结构混乱和语序不当的区别：结构混乱是两种句式纠缠，要删一种；语序不当是顺序颠倒，调换位置就好。看删能不能修好。","例句解析":[{"句":"原因是由于他努力。","析":"原因和由于重复，改为：原因是他努力。"},{"句":"这次活动是受到了大家的欢迎造成的。","析":"是……造成的和受到了……纠缠，改为：这次活动受到了大家的欢迎。"}],"练习":[{"q":"“原因是由于他努力”怎么改？","options":["原因是由于他努力的","原因是他努力","由于是他努力","原因是他努力的由于"],"answer":1,"解析":"原因和由于留一个。","类":"原因是由于式"},{"q":"“这次活动是受到了大家的欢迎造成的”错在哪？","options":["语序不当","结构混乱","搭配不当","表意不明"],"answer":1,"解析":"两种句式纠缠，删一种。","类":"是……造成的式"},{"q":"句式杂糅的改法是？","options":["调换位置","留一去一","补上成分","换关联词"],"answer":1,"解析":"两种句式，留一去一。","类":"原因是由于式"}]},{"name":"表意不明","例子":["病：他背着总经理和副总喝酒（谁喝？）","病：小红的妈妈说她病了（谁病了？）","病：他背着总经理去开会→改：总经理背着他去开会（或：他陪总经理去开会），消除歧义","病：数理化学习经验→改：数理化的学习经验（加“的”消除歧义）","病：鸡不吃了→改：鸡不吃食了（或：这只鸡不吃了），说清主语","病：我想起来了→改：我想起这件事了（说清宾语）","病：开刀的是他父亲→改：给他开刀的是他父亲的同事（说清施事）","病：这辆车没有锁→改：这辆车没有上锁（说清“锁”的含义）","病：他在火车上写字→改：他在火车上写了一封信（补宾语）","病：雨天没有晴天多→改：下雨天没有晴天多（说清比较对象）"],"口诀":"代词指代要明确","易错":"多重定语易生歧义","讲解":"歧义或指代不清","深讲":"表意不明是歧义或指代不清：代词指代要明确，多重定语易生歧义。改法是：代词换成名字，歧义的句子拆开说。","分类":[{"类":"代词指代不明","说明":"代词不知道指谁。","代表":"她病了（谁？）","例子":["小红的妈妈说她病了。"]},{"类":"句子歧义","说明":"一句话有两种理解。","代表":"背着……喝酒（谁喝？）","例子":["他背着总经理和副总喝酒。"]}],"怎么认":["句子里的代词（他、她、它）指谁？说不清，就是指代不明。","一句话能不能有两种理解？能，就是歧义。","两个人以上时，少用他，直接叫名字。"],"辨析":"表意不明和不合逻辑的区别：表意不明是意思说不清（谁病了？）；不合逻辑是意思说得清但不合理（七点起床，六点半出门）。看意思清不清。","例句解析":[{"句":"他背着总经理和副总喝酒。","析":"不知道是谁喝酒，是和副总一起喝，还是背着他们喝，有歧义。"},{"句":"小红的妈妈说她病了。","析":"她不知道指小红还是妈妈，指代不明。"}],"练习":[{"q":"“小红的妈妈说她病了”错在哪？","options":["搭配不当","代词指代不明","语序不当","结构混乱"],"answer":1,"解析":"她不知道指小红还是妈妈。","类":"代词指代不明"},{"q":"“他背着总经理和副总喝酒”错在哪？","options":["缺主语","句子歧义","搭配不当","不合逻辑"],"answer":1,"解析":"不知道是谁喝酒，有两种理解。","类":"句子歧义"},{"q":"“小明和小刚说，他赢了”怎么改最清楚？","options":["小明和小刚说，他赢了","小明对小刚说：“我赢了”","他们说，他赢了","小明说，他赢了"],"answer":1,"解析":"直接叫名字、用第一人称，指代就清楚了。","类":"代词指代不明"}]},{"name":"不合逻辑","例子":["病：三月的南京是美丽的季节（主谓不合逻辑）","病：他七点起床洗漱，然后六点半出门（时间倒流了！）","病：他是众多死难者中幸免的一个→改：他是众多遇难者中幸免的一个（死难者不能幸免）","病：我断定他大概是生病了→改：我断定他是生病了（断定与大概矛盾）","病：全体同学都参加了，只有小明没来→改：除小明外，全体同学都参加了","病：他是唯一一个女同学→改：她是唯一的女同学（唯一与一个重复且搭配不当）","病：这道题我做了三遍，终于做对了一半→改：这道题我做了三遍，终于做对了","病：他的年龄大约十六七岁左右→改：他的年龄十六七岁（约数矛盾）","病：我们一定要发扬光大革命传统→改：我们一定要发扬革命传统（删“光大”或改为“把…发扬光大”）","病：这家店的商品物美价廉，服务态度好→改：正确（并列得当）"],"口诀":"概念关系要理清","易错":"“美”和“季节”不能搭配","讲解":"自相矛盾、概念并列不当等","深讲":"不合逻辑是自相矛盾、概念并列不当等：概念关系要理清，前后说法不能打架。改法是：一读前后，二查概念，三改说法。","分类":[{"类":"前后矛盾式","说明":"前后说法自己打自己。","代表":"七点起床，六点半出门","例子":["他七点起床洗漱，然后六点半出门。"]},{"类":"并列概念不当式","说明":"并列的概念有交叉或包含。","代表":"水果、苹果和香蕉","例子":["水果、苹果和香蕉都很好吃。"]},{"类":"主谓不合逻辑式","说明":"主语和谓语在逻辑上对不上。","代表":"南京是季节","例子":["三月的南京是美丽的季节。"]}],"怎么认":["前后说法打不打架？打架，就是前后矛盾。","并列的词有没有包含关系？有，就是并列不当。","主语和谓语在逻辑上配不配？不配，就是主谓不合逻辑。"],"辨析":"不合逻辑和表意不明的区别：不合逻辑是意思清楚但不合理（时间倒流）；表意不明是意思说不清（谁病了？）。看意思清不清、合理不合理。","例句解析":[{"句":"三月的南京是美丽的季节。","析":"南京是城市，不能是季节，主谓不合逻辑。"},{"句":"他七点起床洗漱，然后六点半出门。","析":"六点半比七点早，时间倒流了，前后矛盾。"}],"练习":[{"q":"“他七点起床洗漱，然后六点半出门”错在哪？","options":["语序不当","前后矛盾","搭配不当","表意不明"],"answer":1,"解析":"六点半比七点早，时间倒流了。","类":"前后矛盾式"},{"q":"“水果、苹果和香蕉都很好吃”错在哪？","options":["并列概念不当","语序不当","缺宾语","结构混乱"],"answer":0,"解析":"水果包含了苹果，不能并列。","类":"并列概念不当式"},{"q":"“三月的南京是美丽的季节”错在哪？","options":["主谓不合逻辑","缺主语","语序不当","搭配不当"],"answer":0,"解析":"南京是城市，不能是季节。","类":"主谓不合逻辑式"}]},{"name":"主语残缺","讲解":"滥用介词（通过/使/令）导致主语丢失，话没了“头”。","深讲":"主语残缺是滥用介词（通过、使、令）导致主语丢失，话没了头。改法是：通过、使、令，删一留一，把主语留下来。","分类":[{"类":"通过使式","说明":"通过和使同时出现，主语被吃掉。","代表":"通过……使……","例子":["通过这次春游，使我增长了见识。"]},{"类":"介词开头式","说明":"介词开头，主语被介词吃掉。","代表":"看了……，受到了……","例子":["看了这部电影，受到了教育。"]}],"怎么认":["句子开头是不是通过、使、令这类介词？是的。","压缩主干，有没有主语？没有，就是主语残缺。","删掉通过或使，主语是不是回来了？回来了。"],"辨析":"主语残缺和谓语残缺的区别：主语残缺是缺头（通过学习，使我进步）；谓语残缺是缺动作（他昨天）。看缺的是头还是动作。","例句解析":[{"句":"通过这次春游，使我增长了见识。","析":"通过和使同时出现，删去使：通过这次春游，我增长了见识。"},{"句":"看了这部电影，受到了教育。","析":"主语被介词吃掉，补上主语：我受到了教育。"}],"练习":[{"q":"“通过这次春游，使我增长了见识”怎么改？","options":["通过这次春游，使我增长了见识了","通过这次春游，我增长了见识","这次春游，使我增长了见识","通过春游，使我增长见识"],"answer":1,"解析":"删去使，主语我就回来了。","类":"通过使式"},{"q":"“看了这部电影，受到了教育”错在哪？","options":["缺谓语","主语残缺","缺宾语","语序不当"],"answer":1,"解析":"主语被介词吃掉了。","类":"介词开头式"},{"q":"“通过……使……”是哪个病句的重灾区？","options":["谓语残缺","主语残缺","宾语残缺","搭配不当"],"answer":1,"解析":"通过和使同时出现，最易缺主语。","类":"通过使式"}],"例子":["病：通过这次春游，使我增长了见识 → 改：删去“使”","病：看了这部电影，受到了教育 → 改：我受到了教育","病：通过这次春游，使我增长了见识→改：通过这次春游，我增长了见识（删“使”）","病：看了这部电影，受到了教育→改：我看了这部电影，受到了教育（补主语“我”）","病：由于他努力学习，因而取得了好成绩→改：由于他努力学习，他取得了好成绩（删“因而”或补主语）","病：经过老师的教育，让我明白了道理→改：经过老师的教育，我明白了道理（删“让”）","病：从这件事中，懂得了诚实的重要→改：从这件事中，我懂得了诚实的重要（补“我”）","病：在老师的帮助下，他的成绩有了提高→改：正确（“他的成绩”作主语）","病：听了这个故事，受到很大启发→改：我听了这个故事，受到很大启发","病：通过讨论，使我们的认识提高了→改：通过讨论，我们的认识提高了"],"口诀":"通过使令，删一留一","易错":"“通过……使……”是重灾区","类比":"主语残缺就像“没头的话”：说了半天，不知道谁干的。"},{"name":"谓语残缺","讲解":"只有主语没有谓语，话没说完。","深讲":"谓语残缺是只有主语没有谓语，话没说完。改法是：主语有了，动作要有，补上谓语。","分类":[{"类":"主语独存式","说明":"只有主语，谓语全缺。","代表":"他昨天","例子":["他昨天。"]},{"类":"谓语不全式","说明":"谓语说了半截，没说完。","代表":"同学都很","例子":["我们班的同学都很。"]}],"怎么认":["压缩句子后只剩主语吗？是的，就是谓语残缺。","主语后面有没有动作或状态？没有，就是缺谓语。","补上动作，句子是不是完整了？完整了。"],"辨析":"谓语残缺和主语残缺的区别：谓语残缺是缺动作（他昨天）；主语残缺是缺头（通过学习，使我进步）。看缺的是头还是动作。","例句解析":[{"句":"他昨天。","析":"只有主语和时间，缺谓语，改为：他昨天来了。"},{"句":"我们班的同学都很。","析":"都很后面缺形容词，改为：我们班的同学都很好学。"}],"练习":[{"q":"“他昨天”错在哪？","options":["主语残缺","谓语残缺","宾语残缺","语序不当"],"answer":1,"解析":"只有主语，缺谓语。","类":"主语独存式"},{"q":"“我们班的同学都很”怎么改？","options":["我们班的同学都很学","我们班的同学都很好学","我们班的同学很","我们班的同学都"],"answer":1,"解析":"补上谓语好学。","类":"谓语不全式"},{"q":"压缩句子后只剩主语，说明？","options":["主语残缺","谓语残缺","宾语残缺","搭配不当"],"answer":1,"解析":"只剩主语，就是谓语残缺。","类":"主语独存式"}],"例子":["病：他昨天 → 改：他昨天来了","病：我们班的同学都很 → 改：我们班的同学都很好学","病：他把今天的任务→改：他把今天的任务完成了（补谓语“完成”）","病：我们正在努力→改：我们正在努力学习（补宾语/谓语中心）","病：小明把门→改：小明把门关上了（补谓语“关上”）","病：他对这件事的关心→改：他对这件事很关心（补谓语“关心”）","病：妈妈把饭→改：妈妈把饭做好了（补谓语“做好”）","病：我们要学习雷锋的→改：我们要学习雷锋的精神（补宾语）","病：老师要求我们→改：老师要求我们认真读书（补谓语）","病：他把球→改：他把球踢进了球门（补谓语）"],"口诀":"主语有了，动作要有","易错":"压缩句子后只剩主语，就是谓语残缺"},{"name":"宾语残缺","讲解":"及物动词后缺宾语，动作没“着落”。","深讲":"宾语残缺是及物动词后缺宾语，动作没着落。改法是：动词之后，宾语莫丢，补上宾语。","分类":[{"类":"宾语空缺式","说明":"动词后宾语全空着。","代表":"大家都喜欢","例子":["大家都喜欢。"]},{"类":"宾语不全式","说明":"宾语说了半截，不完整。","代表":"养成的好习惯","例子":["我们要养成的好习惯。"]}],"怎么认":["动词后面有没有宾语？没有，就是宾语残缺。","“养成”“喜欢”后不能空着，重点查。","补上宾语，句子是不是完整了？完整了。"],"辨析":"宾语残缺和主语残缺的区别：宾语残缺是动作没着落（大家都喜欢）；主语残缺是话没头（通过学习，使我进步）。看缺的是头还是尾。","例句解析":[{"句":"我们要养成的好习惯。","析":"养成后缺完整的宾语，改为：养成讲卫生的好习惯。"},{"句":"大家都喜欢。","析":"喜欢后空着，改为：大家都喜欢这本书。"}],"练习":[{"q":"“大家都喜欢”错在哪？","options":["主语残缺","谓语残缺","宾语残缺","语序不当"],"answer":2,"解析":"喜欢后缺宾语。","类":"宾语空缺式"},{"q":"“我们要养成的好习惯”怎么改？","options":["我们要养成好习惯","我们要养成讲卫生的好习惯","我们要好习惯养成","我们要养成习惯"],"answer":1,"解析":"补上讲卫生，宾语就完整了。","类":"宾语不全式"},{"q":"“养成”“喜欢”后不能？","options":["加宾语","空着","加定语","加状语"],"answer":1,"解析":"及物动词后不能空着。","类":"宾语空缺式"}],"例子":["病：我们要养成的好习惯 → 改：养成讲卫生的好习惯","病：大家都喜欢 → 改：大家都喜欢这本书","病：我们要学习雷锋同志全心全意为人民服务的→改：…服务的精神（补宾语“精神”）","病：他正在看→改：他正在看书（补宾语“书”）","病：妈妈在洗→改：妈妈在洗衣服（补宾语“衣服”）","病：老师表扬了→改：老师表扬了他（补宾语“他”）","病：我喜欢→改：我喜欢画画（补宾语“画画”）","病：他把作业→改：他把作业写完了（补谓语和宾语完整）","病：我们参观了→改：我们参观了博物馆（补宾语）","病：小明正在写→改：小明正在写作文（补宾语）"],"口诀":"动词之后，宾语莫丢","易错":"“养成”“喜欢”后不能空着"},{"name":"定语语序不当","讲解":"多重定语排列顺序错误。","深讲":"定语语序不当是多重定语排列顺序错误。顺序是：领属＋数量＋动词性＋形容词性＋名词，依次排好，不能乱。","分类":[{"类":"领属错位式","说明":"领属定语没放在最前。","代表":"一位优秀的我们班的学生","例子":["一位优秀的我们班的学生。"]},{"类":"多重定语错位式","说明":"多个定语顺序全乱了。","代表":"优秀的我们班的一位学生","例子":["优秀的我们班的一位学生。"]}],"怎么认":["定语有几个？多个，就要查顺序。","按领属、数量、动词性、形容词性、名词排一排。","排好后句子是不是顺了？顺了。"],"辨析":"定语语序不当和状语语序不当的区别：定语错位是名词前的修饰语排错了（我们班的一位优秀的学生）；状语错位是动词前的修饰语放错了（认真地把作业写完了）。看修饰的是名词还是动词。","例句解析":[{"句":"一位优秀的我们班的学生。","析":"领属我们班应在最前，改为：我们班的一位优秀的学生。"},{"句":"优秀的我们班的一位学生。","析":"按领属、数量、形容词排，改为：我们班的一位优秀的学生。"}],"练习":[{"q":"“一位优秀的我们班的学生”怎么改？","options":["一位我们班的优秀的学生","我们班的一位优秀的学生","优秀的我们班的一位学生","我们班优秀的一位学生"],"answer":1,"解析":"领属我们班在最前。","类":"领属错位式"},{"q":"多重定语的正确顺序是？","options":["形容词＋领属＋数量＋名词","领属＋数量＋动词性＋形容词性＋名词","数量＋领属＋形容词性＋名词","名词＋领属＋数量＋形容词"],"answer":1,"解析":"领属、数量、动词性、形容词性、名词依次排。","类":"多重定语错位式"},{"q":"“我们班的一位优秀的学生”中，领属定语是？","options":["一位","优秀的","我们班的","学生"],"answer":2,"解析":"我们班的是领属定语，在最前。","类":"领属错位式"}],"例子":["病：一位优秀的我们班的学生 → 改：我们班的一位优秀的学生","病：一位优秀的我们班的学生→改：我们班的一位优秀的学生（领属在前）","病：红的我的书包→改：我的红书包（领属+颜色顺序）","病：三本他的新书→改：他的三本新书（领属+数量+形容）","病：美丽的祖国的花朵→改：祖国美丽的花朵（领属在前）","病：两个可爱的小明的弟弟→改：小明的两个可爱的弟弟","病：昨天的一场大雨→改：正确（时间定语在前）","病：学校的我们的老师→改：我们学校的老师","病：高兴的他的消息→改：他的好消息（或：令他高兴的消息）","病：五个班里的同学→改：班里的五个同学"],"口诀":"谁的、多少、干啥、啥样，依次排好","易错":"顺序：领属＋数量＋动词性＋形容词性＋名词"},{"name":"关联词误用","讲解":"关联词前后不搭配，张冠李戴。","深讲":"关联词误用是关联词前后不搭配，张冠李戴。改法是：因果转折，配对要准，因为配所以，虽然配但是，别串门。","分类":[{"类":"因果误配转折式","说明":"因果词配了转折词。","代表":"因为……但是……","例子":["因为他很努力，但是没考好。"]},{"类":"条件误配式","说明":"条件词配错了。","代表":"只有……就……","例子":["只有下雨，就不去。"]}],"怎么认":["前后分句是什么关系？先定关系。","关联词配不配这个关系？不配，就是误用。","因为配所以，虽然配但是，查一查配对表。"],"辨析":"关联词误用和关联词残缺的区别：误用是配错了（因为……但是……）；残缺是只说一半（一边跑步，听音乐）。看是配错还是缺一半。","例句解析":[{"句":"因为他很努力，但是没考好。","析":"因为配但是是错的，改为：虽然他很努力，但是没考好。"},{"句":"只有下雨，就不去。","析":"只有是必要条件，就不去是充分结果，配错了，改为：只要下雨，就不去。"}],"练习":[{"q":"“因为他很努力，但是没考好”怎么改？","options":["因为他很努力，所以没考好","虽然他很努力，但是没考好","因为他很努力，而且没考好","如果他很努力，但是没考好"],"answer":1,"解析":"转折关系用虽然配但是。","类":"因果误配转折式"},{"q":"“只有下雨，就不去”怎么改？","options":["只有下雨，才不去","只要下雨，就不去","如果下雨，才不去","因为下雨，就不去"],"answer":1,"解析":"只要配就，表充分条件。","类":"条件误配式"},{"q":"“因为”配？","options":["但是","所以","而且","还是"],"answer":1,"解析":"因为配所以，别串门。","类":"因果误配转折式"}],"例子":["病：因为他很努力，但是没考好 → 改：虽然他很努力，但是没考好","病：只有下雨，就不去 → 改：只要下雨，就不去","病：因为他努力，所以他虽然成功了→改：因为他努力，所以他成功了（删“虽然”）","病：即使困难再大，我们也要不但完成→改：即使困难再大，我们也要完成（删“不但”）","病：他不但学习好，但是体育不好→改：他不但学习好，而且体育也好（“不但”配“而且”）","病：虽然他病了，所以没来上课→改：因为他病了，所以没来上课（因果用“因为…所以”）","病：如果努力，就不但能成功→改：如果努力，就能成功（删“不但”）","病：不是他不努力，而是因为方法不对→改：他不是不努力，而是方法不对（“不是…而是”位置）","病：只有你来，我才不去→改：如果你来，我就不去（条件关系用“如果…就”）","病：尽管下雨，但是却照常进行→改：尽管下雨，但是照常进行（删“却”）"],"口诀":"因果转折，配对要准","易错":"“因为”配“所以”，“虽然”配“但是”，别串门","图示":"<svg viewBox=\"0 0 320 150\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">关联词误用：\"因为\"不能配\"但是\"</text><g opacity=\"1\"><animate attributeName=\"opacity\" values=\"1;1;0;0;1;1\" keyTimes=\"0;0.4;0.5;0.9;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/><text x=\"12\" y=\"64\" font-size=\"16\" class=\"svg-ink\">因为下雨，</text><text x=\"92\" y=\"64\" font-size=\"16\" class=\"svg-red\">但是</text><text x=\"124\" y=\"64\" font-size=\"16\" class=\"svg-ink\">没带伞。</text><text x=\"280\" y=\"64\" font-size=\"20\" class=\"svg-red\">✗</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;0;1;1;0;0\" keyTimes=\"0;0.4;0.5;0.9;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/><text x=\"12\" y=\"64\" font-size=\"16\" class=\"svg-ink\">因为下雨，</text><text x=\"92\" y=\"64\" font-size=\"16\" class=\"svg-accent\">所以</text><text x=\"124\" y=\"64\" font-size=\"16\" class=\"svg-ink\">没带伞。</text><text x=\"280\" y=\"64\" font-size=\"20\" class=\"svg-accent\">✓</text></g><text x=\"12\" y=\"122\" font-size=\"12\" class=\"svg-muted\">因为…所以…／虽然…但是…，前后要配套</text></svg>"},{"name":"关联词残缺","讲解":"关联词只说一半，另一半丢了。","深讲":"关联词残缺是关联词只说一半，另一半丢了。改法是：关联成双，缺一不可，把另一半补上。","分类":[{"类":"一边残缺式","说明":"一边……一边……只说了一边。","代表":"一边跑步，听音乐","例子":["他一边跑步，听音乐。"]},{"类":"虽然残缺式","说明":"虽然……但是……只说了虽然。","代表":"虽然天气冷，坚持锻炼","例子":["虽然天气冷，坚持锻炼。"]}],"怎么认":["关联词是不是成双的？只说一半，就是残缺。","一边、虽然、因为这类词，后面有没有另一半？没有，就是残缺。","补上另一半，句子是不是完整了？完整了。"],"辨析":"关联词残缺和关联词误用的区别：残缺是缺一半（一边跑步，听音乐）；误用是配错了（因为……但是……）。看是缺了还是配错了。","例句解析":[{"句":"他一边跑步，听音乐。","析":"一边只说了一半，改为：他一边跑步，一边听音乐。"},{"句":"虽然天气冷，坚持锻炼。","析":"虽然后缺但是，改为：虽然天气冷，但是坚持锻炼。"}],"练习":[{"q":"“他一边跑步，听音乐”怎么改？","options":["他一边跑步，一边听音乐","他跑步，听音乐","他一边跑步，听着音乐","他跑步一边，听音乐一边"],"answer":0,"解析":"一边要成双。","类":"一边残缺式"},{"q":"“虽然天气冷，坚持锻炼”缺什么？","options":["一边","但是","所以","而且"],"answer":1,"解析":"虽然配但是，缺了但是。","类":"虽然残缺式"},{"q":"关联词的改法是？","options":["留一去一","关联成双，缺一不可","调换位置","删去一个"],"answer":1,"解析":"关联成双，缺一不可。","类":"一边残缺式"}],"例子":["病：他一边跑步，听音乐 → 改：他一边跑步，一边听音乐","病：虽然天气冷，坚持锻炼 → 改：虽然天气冷，但是坚持锻炼","病：他努力学习，取得了好成绩→改：因为他努力学习，所以取得了好成绩（补关联词）","病：下雨，运动会取消→改：因为下雨，所以运动会取消了","病：你去，我去→改：你去，我就去（补“就”）","病：困难再大，我们克服→改：即使困难再大，我们也要克服","病：他学习好，体育好→改：他不但学习好，而且体育好","病：天黑，我们回家→改：天黑了，我们就回家","病：你不说，我怎么知道→改：如果你不说，我怎么知道","病：努力，就有收获→改：只要努力，就有收获"],"口诀":"关联成双，缺一不可","易错":"“一边…一边…”“虽然…但是…”都要说全"},{"name":"指代不明","讲解":"代词指代对象不明确，不知道说的是谁。","深讲":"指代不明是代词指代对象不明确，不知道说的是谁。改法是：两个人以上时，少用他，直接叫名字。","分类":[{"类":"人物指代不明","说明":"代词不知道指哪个人。","代表":"他赢了（谁？）","例子":["小明和小刚说，他赢了。"]},{"类":"事物指代不明","说明":"代词不知道指哪个事物。","代表":"它不见了（什么？）","例子":["他把书放在桌子上，它不见了。"]}],"怎么认":["句子里有几个人、几个物？两个以上，就要查代词。","代词（他、她、它）指谁？说不清，就是指代不明。","换成名字，句子是不是清楚了？清楚了。"],"辨析":"指代不明和句子歧义的区别：指代不明是代词不知道指谁（她病了）；句子歧义是一句话有两种理解（背着……喝酒）。看问题在代词还是整句话。","例句解析":[{"句":"小明和小刚说，他赢了。","析":"他不知道指小明还是小刚，改为：小明对小刚说：“我赢了”。"},{"句":"他把书放在桌子上，它不见了。","析":"它指代不清，改为：书不见了。"}],"练习":[{"q":"“小明和小刚说，他赢了”错在哪？","options":["语序不当","人物指代不明","搭配不当","结构混乱"],"answer":1,"解析":"他不知道指小明还是小刚。","类":"人物指代不明"},{"q":"“他把书放在桌子上，它不见了”怎么改最清楚？","options":["他把书放在桌子上，它不见了","书不见了","他把书放在桌子上，书不见了","它把书放在桌子上，不见了"],"answer":1,"解析":"直接说书不见了，指代就清楚了。","类":"事物指代不明"},{"q":"两个人以上时，代词的改法是？","options":["多用他","少用他，直接叫名字","删去代词","换成它"],"answer":1,"解析":"少用他，直接叫名字。","类":"人物指代不明"}],"例子":["病：小明和小刚说，他赢了 → 改：小明对小刚说：“我赢了”","病：他把书放在桌子上，它不见了 → 改：书不见了","病：小明对小红说，他明天要去北京→改：小明对小红说：“我明天要去北京”（说清“他”指谁）","病：老师把书给了他，他很高兴→改：老师把书给了小明，小明很高兴","病：妈妈叫姐姐，她答应了→改：妈妈叫姐姐，姐姐答应了","病：他把这件事告诉了他→改：他把这件事告诉了小刚","病：老师批评了他，他很不服气→改：老师批评了小明，小明很不服气","病：小红和小丽是好朋友，她学习很好→改：小红和小丽是好朋友，小红学习很好","病：爸爸对儿子说，你要好好学习→改：爸爸对儿子说：“你要好好学习”（加引号明确）","病：他把自行车借给了他→改：他把自行车借给了弟弟"],"口诀":"他她它，谁是谁","易错":"两个人以上时，少用“他”，直接叫名字"},{"name":"前后矛盾","讲解":"前后说法自相矛盾，自己打自己。","深讲":"前后矛盾是前后说法自相矛盾，自己打自己。改法是：断定别大概，前后别打架，语气、时间都要一致。","分类":[{"类":"语气矛盾式","说明":"断定词和大概词打架。","代表":"断定……大概……","例子":["他断定这次大概能考第一。"]},{"类":"时间矛盾式","说明":"时间前后打架。","代表":"昨天上午……下午……","例子":["昨天上午，我亲眼看见他下午在打球。"]}],"怎么认":["前后说法打不打架？打架，就是前后矛盾。","断定、肯定后有没有大概、可能？有，就是语气矛盾。","时间顺序对不对？不对，就是时间矛盾。"],"辨析":"前后矛盾和并列概念不当的区别：前后矛盾是说法打架（断定大概）；并列概念不当是词并列错了（水果、苹果）。看是说法打架还是词并列错了。","例句解析":[{"句":"他断定这次大概能考第一。","析":"断定和大概打架，改为：他估计这次能考第一。"},{"句":"昨天上午，我亲眼看见他下午在打球。","析":"上午和下午打架，时间矛盾。"}],"练习":[{"q":"“他断定这次大概能考第一”错在哪？","options":["语序不当","语气矛盾","搭配不当","表意不明"],"answer":1,"解析":"断定后不能跟大概。","类":"语气矛盾式"},{"q":"“昨天上午，我亲眼看见他下午在打球”错在哪？","options":["时间矛盾","语序不当","缺主语","搭配不当"],"answer":0,"解析":"上午和下午时间打架了。","类":"时间矛盾式"},{"q":"“断定”“肯定”后不能跟？","options":["一定","大概、可能","确实","真的"],"answer":1,"解析":"断定别大概。","类":"语气矛盾式"}],"例子":["病：他断定这次大概能考第一 → 改：他估计这次能考第一","病：昨天上午，我亲眼看见他下午在打球（时间打架了！）","病：他大约十六七岁左右→改：他十六七岁（删“大约”“左右”）","病：这道题我断定大概做对了→改：这道题我断定做对了（删“大概”）","病：全体同学都到了，只有小明没来→改：除了小明，全体同学都到了","病：他是唯一的三个获奖者之一→改：他是三个获奖者之一（删“唯一的”）","病：我亲眼目睹了他亲手做这件事→改：我目睹了他做这件事（删重复强调）","病：这个星期天，我肯定一定去→改：这个星期天，我一定去（删“肯定”）","病：他差不多把作业全部做完了→改：他把作业全部做完了（删“差不多”）","病：大约有三百多人参加→改：有三百多人参加（删“大约”）"],"口诀":"断定别大概，前后别打架","易错":"“断定”“肯定”后不能跟“大概”“可能”"},{"name":"并列概念交叉","讲解":"并列的概念有交叉或包含关系，不能放一排。","深讲":"并列概念交叉是并列的概念有交叉或包含关系，不能放一排。改法是：大概念小概念，别放一排，去掉大概念或小概念。","分类":[{"类":"包含并列式","说明":"大概念包含了小概念，还并列。","代表":"水果、苹果和香蕉","例子":["水果、苹果和香蕉都很好吃。"]},{"类":"类别交叉式","说明":"类别词和小类词并列。","代表":"球类、足球和音乐","例子":["他喜欢球类、足球和音乐。"]}],"怎么认":["并列的词有没有包含关系？有，就是并列不当。","大概念和小概念放一排了吗？放了，就是错的。","去掉大概念，句子是不是顺了？顺了。"],"辨析":"并列概念交叉和前后矛盾的区别：并列不当是词并列错了（水果、苹果）；前后矛盾是说法打架（断定大概）。看是词并列还是说法打架。","例句解析":[{"句":"水果、苹果和香蕉都很好吃。","析":"水果包含了苹果，改为：苹果和香蕉都很好吃。"},{"句":"他喜欢球类、足球和音乐。","析":"球类包含了足球，改为：他喜欢足球和音乐。"}],"练习":[{"q":"“水果、苹果和香蕉都很好吃”怎么改？","options":["水果、苹果和香蕉都好吃","苹果和香蕉都很好吃","水果和苹果都很好吃","水果、香蕉都很好吃"],"answer":1,"解析":"去掉大概念水果。","类":"包含并列式"},{"q":"“他喜欢球类、足球和音乐”错在哪？","options":["语序不当","类别交叉并列","缺宾语","结构混乱"],"answer":1,"解析":"球类包含了足球，不能并列。","类":"类别交叉式"},{"q":"“水果”包含了“苹果”，所以不能？","options":["并列","分开说","一起吃","比较"],"answer":0,"解析":"大概念小概念，别放一排。","类":"包含并列式"}],"例子":["病：水果、苹果和香蕉都很好吃 → 改：苹果和香蕉都很好吃","病：他喜欢球类、足球和音乐 → 改：他喜欢足球和音乐","病：我国的粮食、棉花、油料都增产了→改：我国的粮食作物、棉花、油料作物都增产了（并列得当）","病：他喜欢唱歌、跳舞和文艺→改：他喜欢唱歌、跳舞（删“文艺”，概念包含）","病：商店里有水果、苹果、香蕉→改：商店里有苹果、香蕉等水果（苹果香蕉属水果）","病：他爱好体育、篮球、足球→改：他爱好篮球、足球等体育项目","病：我们参观了工厂、学校和教育→改：我们参观了工厂、学校（删“教育”）","病：动物园里有老虎、狮子和动物→改：动物园里有老虎、狮子等动物","病：他买了文具、铅笔和橡皮→改：他买了铅笔、橡皮等文具","病：会上讨论了学习、纪律和思想问题→改：正确（并列得当）"],"口诀":"大概念小概念，别放一排","易错":"“水果”包含了“苹果”，不能并列"},{"name":"重复啰嗦","讲解":"词语意思重复，多余。","深讲":"重复啰嗦是词语意思重复，多余。改法是：意思重复，删去一个。","分类":[{"类":"意思重复式","说明":"两个词意思一样，重复了。","代表":"凯旋归来","例子":["他凯旋归来了。"]},{"类":"程度叠用式","说明":"程度词叠用，多余。","代表":"非常十分开心","例子":["非常十分开心。"]}],"怎么认":["有没有意思一样的词？有，就是重复。","程度词（非常、十分）叠用了吗？叠用了，就是多余。","删去一个，意思变不变？不变，就是啰嗦。"],"辨析":"重复啰嗦和成分赘余的区别：其实是一回事，重复啰嗦是成分赘余的一种；成分赘余还包括不约而同异口同声这类。看重复的是词还是成分。","例句解析":[{"句":"他凯旋归来了。","析":"旋就是归来，改为：他凯旋了。"},{"句":"非常十分开心。","析":"非常和十分叠用，改为：非常开心。"}],"练习":[{"q":"“他凯旋归来了”怎么改？","options":["他凯旋归来","他凯旋了","他归来了","他凯旋归来了啊"],"answer":1,"解析":"旋就是归来，删去归来。","类":"意思重复式"},{"q":"“非常十分开心”怎么改？","options":["十分开心","非常开心","非常十分地开心","开心"],"answer":1,"解析":"程度词留一个就够。","类":"程度叠用式"},{"q":"“凯旋”本身就含什么意？","options":["胜利","归来","开心","回来"],"answer":1,"解析":"旋就是归来。","类":"意思重复式"}],"例子":["病：他凯旋归来了 → 改：他凯旋了（“旋”就是归来）","病：非常十分开心 → 改：非常开心","病：他亲眼目睹了这件事→改：他目睹了这件事（亲眼与目睹重复）","病：这件事的经过大概→改：这件事的经过（删“大概”或保留一处）","病：他非常非常高兴→改：他非常高兴（删重复）","病：大约三百多人左右→改：三百多人（删“大约”“左右”）","病：他回到了他的家乡→改：他回到了家乡（删“他的”）","病：这是一个非常极好的消息→改：这是一个极好的消息（删“非常”）","病：他首先第一个发言→改：他第一个发言（首先与第一重复）","病：我们共同一起努力→改：我们共同努力（删“一起”）"],"口诀":"意思重复，删去一个","易错":"“凯旋”本身就含“归来”意"},{"name":"约数矛盾","讲解":"约数词叠用，自相矛盾。","深讲":"约数矛盾是约数词叠用，自相矛盾。改法是：大约、左右、上下、多都是约数，别叠用，留一个就够。","分类":[{"类":"大约左右式","说明":"大约和左右叠用。","代表":"大约有30人左右","例子":["大约有30人左右。"]},{"类":"最少多个式","说明":"最少和多个叠用。","代表":"最少也有10多个","例子":["最少也有10多个。"]}],"怎么认":["约数词有几个？两个以上，就是叠用。","大约、左右、上下、多，数一数。","留一个，句子是不是顺了？顺了。"],"辨析":"约数矛盾和重复啰嗦的区别：约数矛盾是约数词叠用（大约左右）；重复啰嗦是意思重复（凯旋归来）。看叠用的是不是约数词。","例句解析":[{"句":"大约有30人左右。","析":"大约和左右都是约数，改为：大约有30人。"},{"句":"最少也有10多个。","析":"最少和多个叠用，改为：有10多个。"}],"练习":[{"q":"“大约有30人左右”怎么改？","options":["大约有30人左右啊","大约有30人","有30人左右","大约左右有30人"],"answer":1,"解析":"约数留一个就够。","类":"大约左右式"},{"q":"“最少也有10多个”怎么改？","options":["最少有10多个","有10多个","最少也有10个多","最少10多个"],"answer":1,"解析":"删去最少也有，留多个。","类":"最少多个式"},{"q":"下面哪个是约数词？","options":["一定","大约","确实","真的"],"answer":1,"解析":"大约是约数词。","类":"大约左右式"}],"例子":["病：大约有30人左右 → 改：大约有30人","病：最少也有10多个 → 改：有10多个","病：大约有三百多人参加→改：有三百多人参加","病：他的年龄十六七岁左右→改：他的年龄十六七岁","病：这条路大约长约五公里→改：这条路长约五公里","病：大约一百多名同学→改：一百多名同学","病：他走了大约半个多小时→改：他走了半个多小时","病：这个水池大约深两米左右→改：这个水池深约两米","病：大约有五六十人上下→改：有五六十人","病：他大概八九岁上下→改：他八九岁"],"口诀":"大约左右，留一个就够","易错":"“大约”“左右”“上下”“多”都是约数，别叠用"},{"name":"否定失当","讲解":"多重否定算错了账，表意正好相反。","深讲":"否定失当是多重否定算错了账，表意正好相反。改法是：否定加否定，意思要算清；避免、切忌、防止后不再加不。","分类":[{"类":"避免否定式","说明":"避免后又加不，意思反了。","代表":"避免不再犯错","例子":["为了避免不再犯错，我们要认真。"]},{"类":"切忌否定式","说明":"切忌后又加不，意思反了。","代表":"切忌不要骄傲","例子":["切忌不要骄傲。"]}],"怎么认":["否定词有几个？数一数。","避免、切忌、防止后有没有不？有，就是多余否定。","算一算否定，意思是不是反了？反了，就是否定失当。"],"辨析":"否定失当和前后矛盾的区别：否定失当是否定算错了账（避免不再犯错）；前后矛盾是说法打架（断定大概）。看问题在否定还是说法。","例句解析":[{"句":"为了避免不再犯错，我们要认真。","析":"避免后不再加不，改为：为了避免犯错。"},{"句":"切忌不要骄傲。","析":"切忌后不再加不，改为：切忌骄傲。"}],"练习":[{"q":"“为了避免不再犯错，我们要认真”怎么改？","options":["为了避免不再犯错","为了避免犯错","为了不再犯错","为了避免不犯错"],"answer":1,"解析":"避免后不再加不。","类":"避免否定式"},{"q":"“切忌不要骄傲”怎么改？","options":["切忌要骄傲","切忌骄傲","不要切忌骄傲","切忌不要不骄傲"],"answer":1,"解析":"切忌后不再加不。","类":"切忌否定式"},{"q":"“避免”“切忌”“防止”后不再加？","options":["不","要","会","能"],"answer":0,"解析":"避免、切忌、防止后不再加不。","类":"避免否定式"}],"例子":["病：为了避免不再犯错，我们要认真 → 改：为了避免犯错","病：切忌不要骄傲 → 改：切忌骄傲","病：我们要防止不再犯错→改：我们要防止犯错（删“不”）","病：他无时无刻不忘学习→改：正确（双重否定表肯定）","病：没有人不说他不好→改：没有人不说他好（删多余否定）","病：难道他不想不去吗→改：难道他不想去吗（删多余否定）","病：我们切忌不要骄傲→改：我们切忌骄傲（删“不要”）","病：他不禁忍不住笑了→改：他忍不住笑了（删“不禁”）","病：避免不发生事故→改：避免发生事故","病：我不会不帮你→改：正确（双重否定表一定帮）"],"口诀":"否定加否定，意思要算清","易错":"“避免”“切忌”“防止”后不再加“不”"},{"name":"主谓搭配不当","讲解":"主语和谓语搭配不起来，对不上号。","深讲":"主谓搭配不当是主语和谓语搭配不起来，对不上号。改法是：谁是什么，对号入座，人口不能是国家。","分类":[{"类":"主语谓语错位式","说明":"主语和谓语在概念上错位。","代表":"人口是国家","例子":["我国的人口是世界上最多的国家。"]},{"类":"概念错配式","说明":"主语概念和谓语概念不配。","代表":"南京是季节","例子":["三月的南京是美丽的季节。"]}],"怎么认":["压缩主干，主语是谁？谓语是什么？","主语和谓语配不配？不配，就是主谓搭配不当。","人口不能是国家，城市不能是季节，查概念。"],"辨析":"主谓搭配不当和动宾搭配不当的区别：主谓不当是主语配谓语错了（人口是国家）；动宾不当是动词配宾语错了（端正学习）。看错的是主谓还是动宾。","例句解析":[{"句":"我国的人口是世界上最多的国家。","析":"人口不能是国家，改为：我国是世界上人口最多的国家。"},{"句":"三月的南京是美丽的季节。","析":"南京不能是季节，主谓不合逻辑，也是主谓搭配不当。"}],"练习":[{"q":"“我国的人口是世界上最多的国家”怎么改？","options":["我国的人口是世界上最多的","我国是世界上人口最多的国家","我国的人口是最多的国家","我国是人口最多的国家"],"answer":1,"解析":"主语换成我国，人口作定语。","类":"主语谓语错位式"},{"q":"“三月的南京是美丽的季节”错在哪？","options":["缺宾语","主谓搭配不当","语序不当","结构混乱"],"answer":1,"解析":"南京不能是季节。","类":"概念错配式"},{"q":"主谓搭配的口诀是？","options":["动词宾语，手拉手配对","谁是什么，对号入座","通过使令，删一留一","关联成双，缺一不可"],"answer":1,"解析":"谁是什么，对号入座。","类":"主语谓语错位式"}],"例子":["病：我国的人口是世界上最多的国家 → 改：我国是世界上人口最多的国家","病：他的写作水平有了很大提高→改：正确（水平与提高搭配）","病：他的普通话说得很标准→改：他的普通话说得很流利","病：同学们都认真地完成了作业→改：正确（完成与作业搭配）","病：他的学习成绩很优异→改：他的学习成绩优异（删“很”）","病：我们要发扬光大革命传统→改：我们要发扬革命传统","病：他的声音很宏亮→改：正确（声音与宏亮搭配）","病：这场雨下得很及时→改：正确（雨与及时搭配）","病：他的态度很端正→改：正确（态度与端正搭配）","病：我们要养成良好的学习态度→改：我们要养成良好的学习习惯"],"口诀":"谁是什么，对号入座","易错":"“人口”不能是“国家”，主语谓语要门当户对"},{"name":"动宾搭配不当","讲解":"动词和宾语不搭配。","深讲":"动宾搭配不当是动词和宾语不搭配。改法是：动词宾语，手拉手配对，端正配态度，提高配水平，别拉错手。","分类":[{"类":"端正配态度式","说明":"端正要配态度，不配学习。","代表":"端正学习","例子":["我们要端正学习。"]},{"类":"提高配水平式","说明":"提高要配水平、球技，不配发扬。","代表":"发扬了球技","例子":["他发扬了球技。"]}],"怎么认":["动词后面跟的是什么宾语？","动词和宾语配不配？不配，就是动宾搭配不当。","端正配态度，提高配水平，查一查固定搭配。"],"辨析":"动宾搭配不当和主谓搭配不当的区别：动宾不当是动词配宾语错了（端正学习）；主谓不当是主语配谓语错了（人口是国家）。看错的是动宾还是主谓。","例句解析":[{"句":"我们要端正学习。","析":"端正配态度，改为：端正学习态度。"},{"句":"他发扬了球技。","析":"发扬配精神，球技配提高，改为：他提高了球技。"}],"练习":[{"q":"“我们要端正学习”怎么改？","options":["我们要端正学习态度","我们要学习端正","我们要端正地学习","我们要学习"],"answer":0,"解析":"端正配态度。","类":"端正配态度式"},{"q":"“他发扬了球技”怎么改？","options":["他发扬了球技水平","他提高了球技","他发扬球技","他提高发扬球技"],"answer":1,"解析":"球技配提高，不配发扬。","类":"提高配水平式"},{"q":"“提高”配？","options":["态度","水平","精神","学习"],"answer":1,"解析":"提高配水平。","类":"提高配水平式"}],"例子":["病：我们要端正学习 → 改：端正学习态度","病：他发扬了球技 → 改：他提高了球技","病：我们要端正学习目的→改：我们要端正学习态度","病：他打碎了信心→改：他失去了信心（打碎与信心不搭配）","病：同学们完成了任务→改：正确（完成与任务搭配）","病：我们要提高学习→改：我们要提高学习成绩（补宾语中心）","病：他改正了缺点→改：正确（改正与缺点搭配）","病：老师提出了希望→改：正确（提出与希望搭配）","病：我们要爱护时间→改：我们要珍惜时间（爱护与时间不搭配）","病：他发挥了水平→改：正确（发挥与水平搭配）"],"口诀":"动词宾语，手拉手配对","易错":"“端正”配“态度”，“提高”配“水平”，别拉错手"}],"name":"常见病句类型（20种）"},{"id":"gaoji","name":"高级句式（7种）","items":[{"name":"把字句","类比":"把字句就像\"抓娃娃机\"：先\"把\"娃娃抓住（提起宾语），再决定怎么处置它。","图示":"<svg viewBox=\"0 0 320 150\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">把字句：动作的对象提前了</text><text x=\"12\" y=\"44\" font-size=\"13\" class=\"svg-muted\">普通句：我 吃了 苹果</text><text x=\"12\" y=\"84\" font-size=\"18\" class=\"svg-ink\">我</text><text x=\"48\" y=\"84\" font-size=\"18\" class=\"svg-accent\" opacity=\"0\">把<animate attributeName=\"opacity\" values=\"0;0;1;1;1;0\" keyTimes=\"0;0.2;0.4;0.8;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"140\" y=\"84\" font-size=\"18\" class=\"svg-ink\">吃了</text><text x=\"92\" y=\"84\" font-size=\"18\" class=\"svg-accent\">苹果<animate attributeName=\"x\" values=\"196;196;92;92;196;196\" keyTimes=\"0;0.2;0.4;0.8;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><path d=\"M214,66 Q160,44 112,66\" stroke-width=\"1.5\" fill=\"none\" stroke-dasharray=\"4,3\" opacity=\"0\" class=\"svg-accent-s\"><animate attributeName=\"opacity\" values=\"0;0;0.9;0.9;0.9;0\" keyTimes=\"0;0.2;0.4;0.8;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></path><polygon points=\"112,66 122,62 120,72\" class=\"svg-accent\" opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;0;0.9;0.9;0.9;0\" keyTimes=\"0;0.2;0.4;0.8;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></polygon><text x=\"12\" y=\"122\" font-size=\"12\" class=\"svg-muted\">苹果从\"吃了\"后面搬到\"把\"后面，动作对象被提前</text></svg>","动画":{"steps":[{"tokens":["我","吃","了","苹果"],"note":"正常语序：我吃了苹果"},{"tokens":["我","把","苹果","吃","了"],"note":"\"把\"提起宾语，放到动词前"},{"tokens":["我","把","苹果","吃","完","了"],"note":"动词后要有\"着落\"（完/掉/干净），不能光秃秃"}]},"讲解":"把宾语提前到动词前，强调对宾语的处置。公式：主语＋把＋宾语＋动词＋补语/了。","深讲":"把字句是把宾语提前到动词前，强调对宾语的处置。公式：主语＋把＋宾语＋动词＋补语/了；动词不能光秃秃，后面要有补语或了表结果；心理动词（喜欢、觉得）不能用把字句。","分类":[{"类":"动词＋了式","说明":"动词后加了，表结果完成。","代表":"把＋宾语＋动词＋了","例子":["我把作业写完了。"]},{"类":"动词＋补语式","说明":"动词后加补语，表处置结果。","代表":"把＋宾语＋动词＋补语","例子":["妈妈把房间收拾干净了。"]}],"怎么认":["句子里有没有把？有。","把后面是不是宾语，动词在宾语后面？是的。","动词后面有没有补语或了？有，才是规范的把字句。"],"辨析":"把字句和被字句的区别：把字句强调处置（我把作业写完了：我处置了作业）；被字句强调承受（杯子被打碎了：杯子承受了打碎）。看主语是处置者还是承受者。","例句解析":[{"句":"我把作业写完了。","析":"把提前了宾语作业，动词写后有了了，是把字句。"},{"句":"他把杯子打碎了。","析":"把提前了宾语杯子，动词打后有了碎了，是把字句。"}],"练习":[{"q":"下面哪个把字句正确？","options":["我把饭吃","我把饭吃完了","我把饭吃着"],"answer":1,"解析":"动词后要有补语或了表结果。","类":"动词＋了式"},{"q":"“妈妈把房间收拾干净了”属于？","options":["动词＋了式","动词＋补语式","被字句","存现句"],"answer":1,"解析":"动词收拾后有补语干净。","类":"动词＋补语式"},{"q":"“他喜欢音乐”能改把字句吗？","options":["他把音乐喜欢了","不能改","他把音乐喜欢着"],"answer":1,"解析":"喜欢是心理动词，无处置义，不能用把。","类":"动词＋了式"}],"口诀":"把字提起宾，动词要有根（补语）","例子":["我把作业写完了","他把杯子打碎了","妈妈把房间收拾干净了","我把作业写完了。","他把杯子打碎了。","妈妈把房间收拾干净了。","小明把垃圾扔进了垃圾桶。","老师把试卷发下来了。","我把这本书看完了。","爸爸把车修好了。","她把花插进了花瓶。","我们把教室打扫得干干净净。","奶奶把毛衣织好了。"],"易错":"✗ 我把书看（动词光秃秃） ✓ 我把书看完了；心理动词（喜欢/觉得）不能用把字句","小测":[{"q":"哪句把字句正确？","options":["我把饭吃","我把饭吃完了","我把饭吃着"],"answer":1,"解析":"动词后要有补语或\"了\"表结果。"},{"q":"\"他喜欢音乐\"能改把字句吗？","options":["他把音乐喜欢了","不能改","他把音乐喜欢着"],"answer":1,"解析":"\"喜欢\"无处置义，不能用把。"}]},{"name":"被字句","类比":"被字句就像\"领奖台\"：动作的承受者站上主语位，强调它\"遭了什么\"。","动画":{"steps":[{"tokens":["小狗","咬","了","小明"],"note":"主动句：小狗是施事"},{"tokens":["小明","被","小狗","咬","了"],"note":"小明变主语，强调他的遭遇"},{"tokens":["小明","被","咬","伤","了"],"note":"\"被\"后施事可省，结果\"伤\"不能省"}]},"讲解":"主语是动作的承受者。公式：受事＋被/叫/让＋施事＋动词＋补语。","深讲":"被字句是主语是动作的承受者。公式：受事＋被/叫/让＋施事＋动词＋补语；被后多为不如意事；被后可以没有施事，直接跟动词。","分类":[{"类":"被＋施事式","说明":"被后有施事，说明谁做的。","代表":"受事＋被＋施事＋动词","例子":["小明被小狗咬了。"]},{"类":"被无施事式","说明":"被后没有施事，只说承受了什么。","代表":"受事＋被＋动词","例子":["杯子被打碎了。"]},{"类":"叫让式","说明":"用叫、让代替被，意思一样。","代表":"受事＋叫/让＋施事＋动词","例子":["他叫雨淋湿了。"]}],"怎么认":["主语是不是承受者？是的。","句子里有没有被、叫、让？有。","被后是施事还是直接动词？施事就是被＋施事式，直接动词就是被无施事式。"],"辨析":"被字句和把字句的区别：被字句主语是承受者（杯子被打碎了）；把字句主语是处置者（我把杯子打碎了）。同一件事，角度不同，句式就不同。","例句解析":[{"句":"小明被小狗咬了。","析":"小明是承受者，被后有施事小狗，是被＋施事式。"},{"句":"我的气球被风吹走了。","析":"气球是承受者，被后有施事风，是被＋施事式。"}],"练习":[{"q":"被字句强调？","options":["谁做的","主语遭受了什么","动作多快"],"answer":1,"解析":"主语是受事，强调遭遇。","类":"被＋施事式"},{"q":"“杯子被打碎了”属于？","options":["被＋施事式","被无施事式","叫让式","把字句"],"answer":1,"解析":"被后没有施事，直接跟动词打碎。","类":"被无施事式"},{"q":"“他被吃了饭”对吗？","options":["对","不对","有时对","看情况"],"answer":1,"解析":"被后多为不如意事，吃了饭不是遭遇，不能这样说。","类":"被＋施事式"}],"口诀":"被字一出，受害现身","例子":["小明被小狗咬了","杯子被打碎了","我的气球被风吹走了","作业被我写完了。","杯子被他打碎了。","房间被妈妈收拾干净了。","小偷被警察抓住了。","窗户被风吹开了。","我的书包被雨淋湿了。","庄稼被洪水淹没了。","他被老师表扬了。","球被小明踢进了球门。","衣服被太阳晒干了。"],"易错":"✗ 他被吃了饭 ✓ 他被批评了；\"被\"后多为不如意事","小测":[{"q":"被字句强调？","options":["谁做的","主语遭受了什么","动作多快"],"answer":1,"解析":"主语是受事，强调遭遇。"}],"图示":"<svg viewBox=\"0 0 320 150\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">被字句：被咬的坐上了主语位</text><text x=\"12\" y=\"44\" font-size=\"13\" class=\"svg-muted\">主动句：小狗 咬了 小明</text><text x=\"60\" y=\"84\" font-size=\"18\" class=\"svg-accent\" opacity=\"0\">被<animate attributeName=\"opacity\" values=\"0;0;1;1;1;0\" keyTimes=\"0;0.2;0.4;0.8;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"168\" y=\"84\" font-size=\"18\" class=\"svg-ink\">咬了</text><text x=\"12\" y=\"84\" font-size=\"18\" class=\"svg-accent\">小明<animate attributeName=\"x\" values=\"240;240;12;12;240;240\" keyTimes=\"0;0.2;0.4;0.8;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"96\" y=\"84\" font-size=\"18\" class=\"svg-ink\">小狗<animate attributeName=\"x\" values=\"12;12;96;96;12;12\" keyTimes=\"0;0.2;0.4;0.8;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"12\" y=\"122\" font-size=\"12\" class=\"svg-muted\">小明、小狗位置互换：谁被咬，一目了然</text></svg>"},{"name":"存现句","类比":"存现句就像\"监控画面\"：某地（出现了/消失了）某物，讲的是\"有无\"，不是\"谁干了什么\"。","讲解":"表示某处存在、出现、消失某人/物。公式：处所＋动词＋人/物。如\"门口站着一个人\"。","深讲":"存现句表示某处存在、出现、消失某人或物。公式：处所＋动词＋人/物；主语是处所不是人；动词多为有、站、坐、来、去、走出、掉下。","分类":[{"类":"存在式","说明":"某处存在某人或物。","代表":"处所＋站/坐/写着＋人/物","例子":["门口站着一个人。"]},{"类":"出现式","说明":"某处出现某人或物。","代表":"处所＋走出/掉下＋人/物","例子":["屋里走出一位老人。"]},{"类":"消失式","说明":"某处消失某人或物。","代表":"处所＋少/不见＋人/物","例子":["屋里少了一个人。"]}],"怎么认":["主语是不是处所（门口、屋里、天上）？是的。","动词后面是不是人或物？是的。","整句是不是在说哪里有啥、哪里来了啥、哪里少了啥？是的。"],"辨析":"存现句和一般主谓句的区别：存现句主语是处所（门口站着一个人）；一般主谓句主语是人或物（一个人站在门口）。看主语是处所还是人。","例句解析":[{"句":"门口站着一个人。","析":"主语门口是处所，站着表存在，是存现句。"},{"句":"黑板上写着几个大字。","析":"主语黑板上是处所，写着表存在，是存现句。"}],"练习":[{"q":"哪句是存现句？","options":["我看见一个人","门口站着一个人","一个人站在门口"],"answer":1,"解析":"主语是处所门口，表存在。","类":"存在式"},{"q":"“屋里走出一位老人”属于？","options":["存在式","出现式","消失式","被字句"],"answer":1,"解析":"走出表出现。","类":"出现式"},{"q":"存现句的主语是？","options":["人","物","处所","动词"],"answer":2,"解析":"存现句的主语是处所不是人。","类":"存在式"}],"口诀":"哪里有啥，存现回答","例子":["天上掉下个馅饼","屋里走出一位老人","黑板上写着几个大字","天上有一轮明月。","桌子上放着一本书。","门口站着一位老师。","山上开满了野花。","水里游着一群小鱼。","墙上挂着一幅画。","教室里坐着许多学生。","天空中飞过一群大雁。","院子里种着几棵果树。","远处跑来一只小狗。"],"易错":"存现句的动词多为\"有/站/坐/来/去\"，主语是处所不是人","小测":[{"q":"哪句是存现句？","options":["我看见一个人","门口站着一个人","一个人站在门口"],"answer":1,"解析":"主语是处所\"门口\"，表存在。"}],"图示":"<svg viewBox=\"0 0 420 110\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"20\" y=\"20\" width=\"100\" height=\"60\" rx=\"8\" fill=\"#e0f2f1\" stroke=\"#00897b\" stroke-width=\"2\"/><text x=\"35\" y=\"55\" font-size=\"14\">门口</text><text x=\"140\" y=\"55\" font-size=\"16\">站着</text><circle cx=\"280\" cy=\"50\" r=\"22\" fill=\"#fff3e0\" stroke=\"#ff9800\" stroke-width=\"2\"/><text x=\"268\" y=\"57\" font-size=\"16\">人</text><text x=\"30\" y=\"100\" font-size=\"12\" fill=\"#888\">处所 ＋ 动词 ＋ 人/物（讲\"有无\"）</text></svg>"},{"name":"是…的句","类比":"是…的就像\"聚光灯\"：把\"是\"和\"的\"框住的部分照亮，强调\"就是它\"。","动画":{"steps":[{"tokens":["他","是","昨天","来","的"],"note":"强调时间：是\"昨天\"来的"},{"tokens":["他","是","坐飞机","来","的"],"note":"框住\"坐飞机\"：强调方式"},{"tokens":["他","是","北京","人"],"note":"注意：判断句\"他是北京人\"不用\"的\""}]},"讲解":"强调已发生情况的时间/方式/处所。框住被强调成分。","深讲":"是……的句强调已发生情况的时间、方式、处所：是和的框住被强调的成分；只用于已发生的事，没发生的事不能用。","分类":[{"类":"强调时间式","说明":"是和的框住时间。","代表":"是＋昨天＋来的","例子":["我是昨天来的。"]},{"类":"强调方式式","说明":"是和的框住方式。","代表":"是＋坐火车＋走的","例子":["他是坐火车走的。"]},{"类":"强调处所式","说明":"是和的框住处所。","代表":"是＋在北京＋出生的","例子":["他是在北京出生的。"]}],"怎么认":["句子里有没有是……的框住一个成分？有。","这件事是不是已经发生了？是的。","框住的是时间、方式还是处所？对应就是哪种强调。"],"辨析":"是……的句和判断句的区别：是……的句强调已发生情况的状语（我是昨天来的：强调时间）；判断句是说谁是什么（我是学生）。看是后是不是时间、方式、处所。","例句解析":[{"句":"我是昨天来的。","析":"是和的框住昨天，强调时间。"},{"句":"他是坐火车走的。","析":"是和的框住坐火车，强调方式。"}],"练习":[{"q":"“我是昨天来的”强调？","options":["方式","时间","处所","原因"],"answer":1,"解析":"是和的框住昨天，强调时间。","类":"强调时间式"},{"q":"“他是坐火车走的”强调？","options":["时间","方式","处所","原因"],"answer":1,"解析":"是和的框住坐火车，强调方式。","类":"强调方式式"},{"q":"是……的句只用于？","options":["没发生的事","已发生的事","将来的事","假设的事"],"answer":1,"解析":"只用于已发生的事。","类":"强调时间式"}],"口诀":"是的框住，强调突出","例子":["我是昨天来的","他是坐火车走的","这本书是我昨天买的","他是昨天来的。","我是在图书馆看的这本书。","这件事是他告诉我的。","我们是坐火车去的北京。","这幅画是我画的。","她是去年毕业的。","这个消息是妈妈告诉我的。","我是用毛笔写的字。","他们是步行上山的。","这件毛衣是奶奶织的。"],"易错":"只用于已发生的事；\"是…的\"中间是被强调的状语","图示":"<svg viewBox=\"0 0 420 100\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"30\" y=\"50\" font-size=\"17\">他 是 <tspan fill=\"#8e24aa\" font-weight=\"bold\">昨天</tspan> 来 的</text><rect x=\"95\" y=\"25\" width=\"60\" height=\"35\" rx=\"6\" fill=\"none\" stroke=\"#8e24aa\" stroke-width=\"2\" stroke-dasharray=\"5,3\"/><text x=\"30\" y=\"85\" font-size=\"12\" fill=\"#888\">虚线框＝聚光灯，强调框住的成分</text></svg>"},{"name":"比较句","类比":"比较句就像\"天平\"：左边放一个，右边放一个，看哪边重。","图示":"<svg viewBox=\"0 0 420 120\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"200\" y1=\"20\" x2=\"200\" y2=\"100\" stroke=\"#999\" stroke-width=\"3\"/><line x1=\"60\" y1=\"60\" x2=\"340\" y2=\"60\" stroke=\"#999\" stroke-width=\"3\"/><rect x=\"80\" y=\"60\" width=\"50\" height=\"25\" fill=\"#90caf9\"/><text x=\"88\" y=\"78\" font-size=\"13\">我</text><rect x=\"270\" y=\"35\" width=\"50\" height=\"50\" fill=\"#ef9a9a\"/><text x=\"278\" y=\"65\" font-size=\"13\">他</text><text x=\"150\" y=\"45\" font-size=\"15\">比</text><text x=\"150\" y=\"100\" font-size=\"12\" fill=\"#888\">天平：比后是参照物</text></svg>","讲解":"A 比 B ＋形容词：A 超过 B。否定用\"没有\"（我没有他高≠我比他矮）。","深讲":"比较句是 A 比 B ＋形容词：A 超过 B；否定用没有（我没有他高≠我比他矮）；更表递进（更好）。","分类":[{"类":"比字句","说明":"用比表示超过。","代表":"A 比 B ＋形容词","例子":["我比他高。"]},{"类":"没有字句","说明":"用没有表示否定比较。","代表":"A 没有 B ＋形容词","例子":["今天没有昨天冷。"]},{"类":"更字句","说明":"用更表示递进。","代表":"A 比 B 更＋形容词","例子":["他比以前更好了。"]}],"怎么认":["句子里有没有比、没有、更？有。","比后面是不是参照对象？是的。","句末是不是形容词？是的。"],"辨析":"没有字句和比字句的区别：没有只否定比（我没有他高：我不如他高，不等于我比他矮）；比是肯定超过（我比他高）。看有没有没有。","例句解析":[{"句":"我比他高。","析":"比后是参照他，句末形容词高，是比字句。"},{"句":"今天没有昨天冷。","析":"没有表示否定比较，是没有字句。"}],"练习":[{"q":"“我没有他高”意思是？","options":["我比他矮","我不如他高","他比我矮"],"answer":1,"解析":"没有只否定比他高，不等于反向。","类":"没有字句"},{"q":"“弟弟比我高半头”属于？","options":["比字句","没有字句","更字句","把字句"],"answer":0,"解析":"比后是参照我，句末高半头。","类":"比字句"},{"q":"“更”表？","options":["否定","递进","比较","假设"],"answer":1,"解析":"更表递进（更好）。","类":"更字句"}],"口诀":"比后参照，形容收尾","例子":["我比他高","今天没有昨天冷","弟弟比我高半头","他比我高。","这本书比那本书有趣。","今天比昨天冷。","小明跑得比小红快。","西瓜比苹果甜。","他的成绩比我好得多。","这座山比那座山高。","夏天比冬天热。","我更喜欢红色。","弟弟不如哥哥高。"],"易错":"\"没有\"表否定比较，不表反向；\"更\"表递进（更好）","小测":[{"q":"\"我没有他高\"意思是？","options":["我比他矮","我不如他高","他比我矮"],"answer":1,"解析":"\"没有\"只否定\"比他高\"，不等于反向。"}]},{"name":"双重否定","类比":"双重否定就像\"负负得正\"：两个\"不\"撞在一起，变成强烈的肯定。","讲解":"不得不＝必须；不能不＝一定要。语气比单用\"必须\"更强烈、更无奈。","深讲":"双重否定是两个否定词连用，意思变成肯定：不得不＝必须，不能不＝一定要；语气比单用必须更强烈、更无奈。","分类":[{"类":"不得不式","说明":"不得不等于必须。","代表":"不得不＋动词","例子":["我不得不去。"]},{"类":"不能不式","说明":"不能不等于一定要。","代表":"不能不＋动词","例子":["他不能不承认。"]},{"类":"不会不式","说明":"不会不等于一定会。","代表":"不会不＋动词","例子":["他不会不来。"]}],"怎么认":["句子里有没有两个否定词（不、没、无、非）？有。","两个否定算一算，是不是变成肯定？是的。","语气是不是比单说必须更强烈？是的。"],"辨析":"双重否定和单否定不要搞混：不得不去＝必须去（肯定），不是不去；不能不承认＝一定要承认。算清否定，意思就对了。","例句解析":[{"句":"我不得不去。","析":"不得不等于必须，是双重否定。"},{"句":"我不得不承认他是对的。","析":"不得不等于必须承认，是双重否定。"}],"练习":[{"q":"“我不得不去”意思是？","options":["我不去","我必须去","我不想去","我没去"],"answer":1,"解析":"不得不等于必须。","类":"不得不式"},{"q":"“他不能不承认”意思是？","options":["他不承认","他一定要承认","他不想承认","他没承认"],"answer":1,"解析":"不能不等于一定要。","类":"不能不式"},{"q":"“他不会不来”意思是？","options":["他不来","他一定来","他可能不来","他不想来"],"answer":1,"解析":"不会不等于一定会。","类":"不会不式"}],"口诀":"双否变肯，语气加倍","例子":["我不得不去","他不能不承认","我不得不承认他是对的","他不得不承认错误。（=他必须承认错误）","这件事非他莫属。（=这件事一定是他）","没有人不喜欢和平。（=人都喜欢和平）","我不会不去的。（=我一定去）","这不是不重要。（=这很重要）","他无时无刻不在想念家乡。（=他一直想念家乡）","没有谁不渴望成功。（=都渴望成功）","这个道理不讲不明。（=讲了就明）","我不能不帮他。（=我一定要帮他）","没有付出就没有收获。（双重否定表强调）"],"易错":"\"不会不\"（他不会不来＝他一定来）别和\"不\"搞混","图示":"<svg viewBox=\"0 0 320 150\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">双重否定：两个\"不\"互相抵消</text><text x=\"12\" y=\"44\" font-size=\"13\" class=\"svg-muted\">我不得不去 ＝ ?</text><text x=\"20\" y=\"84\" font-size=\"22\" class=\"svg-ink\">我</text><text x=\"92\" y=\"84\" font-size=\"22\" class=\"svg-accent\" opacity=\"1\">得<animate attributeName=\"opacity\" values=\"1;1;0;0;0;1\" keyTimes=\"0;0.3;0.45;0.9;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"164\" y=\"84\" font-size=\"22\" class=\"svg-ink\">去</text><text x=\"56\" y=\"84\" font-size=\"22\" class=\"svg-red\">不<animate attributeName=\"x\" values=\"56;56;104;104;104;56\" keyTimes=\"0;0.3;0.45;0.9;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/><animate attributeName=\"opacity\" values=\"1;1;1;0;0;1\" keyTimes=\"0;0.3;0.45;0.55;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"128\" y=\"84\" font-size=\"22\" class=\"svg-red\">不<animate attributeName=\"x\" values=\"128;128;104;104;104;128\" keyTimes=\"0;0.3;0.45;0.9;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/><animate attributeName=\"opacity\" values=\"1;1;1;0;0;1\" keyTimes=\"0;0.3;0.45;0.55;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"56\" y=\"84\" font-size=\"22\" class=\"svg-accent\" opacity=\"0\">一定要<animate attributeName=\"opacity\" values=\"0;0;0;1;1;0\" keyTimes=\"0;0.5;0.6;0.9;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"12\" y=\"122\" font-size=\"12\" class=\"svg-muted\">两个\"不\"飞到一起抵消 → 我一定要去（肯定）</text></svg>"},{"name":"歧义句","类比":"歧义句就像\"魔术贴\"：一句话能贴出两种意思，病句题最爱考。","动画":{"steps":[{"tokens":["咬","死","了","猎人","的","狗"],"note":"切分A：(咬死了猎人)的狗——狗咬死了猎人"},{"tokens":["咬","死","了","猎人","的","狗"],"note":"切分B：咬死了(猎人的狗)——猎人的狗被咬死了"}]},"讲解":"一句话有两种理解。消歧方法：换切分、加标点、改语序。","深讲":"歧义句是一句话有两种理解。消歧方法：换切分、加标点、改语序；病句表意不明多为歧义，改法是明确主语或加标点。","分类":[{"类":"切分歧义","说明":"断句不同，意思不同。","代表":"鸡不吃了","例子":["鸡不吃了。"]},{"类":"语义歧义","说明":"一个词、一个说法有两种意思。","代表":"走了一个小时","例子":["他走了一个小时。"]},{"类":"指代歧义","说明":"代词不知道指谁。","代表":"他说他不去了","例子":["他说他不去了。"]}],"怎么认":["一句话能不能有两种理解？能，就是歧义。","换个切分，意思变不变？变，就是切分歧义。","代词指谁说不清？就是指代歧义。"],"辨析":"歧义句和病句表意不明的关系：歧义句是现象（一句话两种理解），表意不明是毛病（要改掉）；消歧的方法是换切分、加标点、改语序、明确主语。","例句解析":[{"句":"鸡不吃了。","析":"切分不同：鸡不吃／人不吃鸡，是切分歧义。"},{"句":"他走了一个小时。","析":"走可以是离开，也可以是步行，是语义歧义。"}],"练习":[{"q":"“咬死了猎人的狗”有几种理解？","options":["1种","2种","3种"],"answer":1,"解析":"两种切分，两种意思。","类":"切分歧义"},{"q":"“他走了一个小时”属于？","options":["切分歧义","语义歧义","指代歧义","把字句"],"answer":1,"解析":"走有离开和步行两种意思。","类":"语义歧义"},{"q":"“他说他不去了”属于？","options":["切分歧义","语义歧义","指代歧义","存现句"],"answer":2,"解析":"不知道是谁不去，是指代歧义。","类":"指代歧义"}],"口诀":"两切两意，歧义现形","例子":["鸡不吃了（鸡不吃/人不吃鸡）","他走了一个小时（离开/步行）","他说他不去了（到底谁不去？）","咬死了猎人的狗。（谁咬死谁？有歧义）","他背着总经理去开会。（他背？还是总经理背？）","数理化学习经验。（数理化学/习经验？）","我想起来了。（想起/起来？）","开刀的是他父亲。（他动手术？他是医生？）","这辆车没有锁。（没锁车/车没锁？）","鸡不吃了。（鸡不吃/人不吃鸡？）","他说不好。（说得不好/说不行？）","校长请老师吃饭。（谁请谁？）","雨天没有晴天多。（比较对象不明）"],"易错":"病句\"表意不明\"多为歧义；改法：明确主语或加标点","小测":[{"q":"\"咬死了猎人的狗\"有几种理解？","options":["1种","2种","3种"],"answer":1,"解析":"两种切分，两种意思。"}],"图示":"<svg viewBox=\"0 0 420 120\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"30\" y=\"35\" font-size=\"16\">咬死了猎人的狗</text><rect x=\"25\" y=\"45\" width=\"150\" height=\"28\" rx=\"6\" fill=\"#e8f5e9\" stroke=\"#4caf50\"/><text x=\"32\" y=\"64\" font-size=\"13\">咬死了猎人｜的狗</text><rect x=\"25\" y=\"80\" width=\"150\" height=\"28\" rx=\"6\" fill=\"#fff3e0\" stroke=\"#ff9800\"/><text x=\"32\" y=\"99\" font-size=\"13\">咬死了｜猎人的狗</text><text x=\"200\" y=\"70\" font-size=\"12\" fill=\"#888\">两种切法，两种意思</text></svg>"}]},{"id":"xuci","name":"虚词精讲（15组）","items":[{"name":"了/着/过","类比":"\"了\"像拍照\"咔嚓\"（事成了/情况变了），\"着\"像视频\"录制中\"（持续），\"过\"像相册\"曾经\"（有过经历）。","图示":"<svg viewBox=\"0 0 320 170\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">了 / 着 / 过：一个管\"完\"，一个管\"在\"，一个管\"过\"</text><text x=\"12\" y=\"40\" font-size=\"18\" class=\"svg-accent\">着<animate attributeName=\"opacity\" values=\"1;1;0.35;0.35;1\" keyTimes=\"0;0.3;0.33;0.97;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"36\" y=\"40\" font-size=\"15\" class=\"svg-ink\">我吃着饭</text><text x=\"190\" y=\"40\" font-size=\"12\" class=\"svg-accent\">正在进行<animate attributeName=\"opacity\" values=\"1;1;0.35;0.35;1\" keyTimes=\"0;0.3;0.33;0.97;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><rect x=\"12\" y=\"48\" width=\"0\" height=\"4\" rx=\"2\" opacity=\"0.55\" class=\"svg-accent\"><animate attributeName=\"width\" values=\"0;140;140;0;0\" keyTimes=\"0;0.28;0.3;0.33;1\" dur=\"9s\" repeatCount=\"indefinite\"/></rect><text x=\"12\" y=\"76\" font-size=\"18\" class=\"svg-accent\">了<animate attributeName=\"opacity\" values=\"0.35;0.35;1;1;0.35;0.35\" keyTimes=\"0;0.3;0.33;0.6;0.63;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"36\" y=\"76\" font-size=\"15\" class=\"svg-ink\">我吃了饭</text><text x=\"190\" y=\"76\" font-size=\"12\" class=\"svg-accent\">已经完成<animate attributeName=\"opacity\" values=\"0.35;0.35;1;1;0.35;0.35\" keyTimes=\"0;0.3;0.33;0.6;0.63;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><rect x=\"12\" y=\"84\" width=\"0\" height=\"4\" rx=\"2\" opacity=\"0.55\" class=\"svg-accent\"><animate attributeName=\"width\" values=\"0;0;140;140;0;0\" keyTimes=\"0;0.31;0.33;0.58;0.63;1\" dur=\"9s\" repeatCount=\"indefinite\"/></rect><text x=\"12\" y=\"112\" font-size=\"18\" class=\"svg-accent\">过<animate attributeName=\"opacity\" values=\"0.35;0.35;0.35;1;1;0.35\" keyTimes=\"0;0.6;0.63;0.9;0.93;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"36\" y=\"112\" font-size=\"15\" class=\"svg-ink\">我吃过饭</text><text x=\"190\" y=\"112\" font-size=\"12\" class=\"svg-accent\">以前有过<animate attributeName=\"opacity\" values=\"0.35;0.35;0.35;1;1;0.35\" keyTimes=\"0;0.6;0.63;0.9;0.93;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><rect x=\"12\" y=\"120\" width=\"0\" height=\"4\" rx=\"2\" opacity=\"0.55\" class=\"svg-accent\"><animate attributeName=\"width\" values=\"0;0;140;140;0;0\" keyTimes=\"0;0.61;0.63;0.88;0.93;1\" dur=\"9s\" repeatCount=\"indefinite\"/></rect><text x=\"12\" y=\"158\" font-size=\"12\" class=\"svg-muted\">着＝正在、了＝完了、过＝有过经历</text></svg>","动画":{"steps":[{"tokens":["我","吃","了","饭"],"note":"了₁跟动词：吃完了"},{"tokens":["下","雨","了"],"note":"了₂在句末：新情况，天开始下雨"},{"tokens":["他","正","看","着","书"],"note":"着：动作持续进行中"},{"tokens":["我","去","过","北京"],"note":"过：曾经有过去北京的经历"}]},"讲解":"了₁表完成（动词后），了₂表变化（句末）；着表持续；过表经历。","深讲":"了有两种：了₁在动词后表完成，了₂在句末表变化；着表持续；过表经历。注意了₁和了₂不叠用，不能说我昨天去了北京了。","分类":[{"类":"了₁完成式","说明":"动词后的了，表动作完成。","代表":"动词＋了","例子":["我吃了饭。"]},{"类":"了₂变化式","说明":"句末的了，表出现新情况。","代表":"句末＋了","例子":["太好了。"]},{"类":"着持续式","说明":"动词后的着，表动作持续。","代表":"动词＋着","例子":["他看着书。"]},{"类":"过经历式","说明":"动词后的过，表曾经的经历。","代表":"动词＋过","例子":["我去过长城。"]}],"怎么认":["了在动词后还是句末？动词后是了₁，句末是了₂。","动作是不是在持续？持续用着。","是不是在说曾经？曾经用过。"],"辨析":"了₁和了₂的区别：了₁在动词后表完成（我吃了饭）；了₂在句末表变化（太好了）。我吃饭了的了是了₂，表新情况，不是了₁。","例句解析":[{"句":"我吃了饭。","析":"吃了后的了在动词后，表完成，是了₁。"},{"句":"妹妹正哭着找妈妈。","析":"哭着的着表动作持续，是着持续式。"}],"练习":[{"q":"“我吃饭了”的了是？","options":["了₁完成","了₂变化","都是"],"answer":1,"解析":"句末表新情况，是了₂。","类":"了₂变化式"},{"q":"表“曾经”用？","options":["了","着","过"],"answer":2,"解析":"去过＝有过去的经历。","类":"过经历式"},{"q":"“他看着书”的着表？","options":["完成","持续","经历"],"answer":1,"解析":"看着表动作持续。","类":"着持续式"}],"口诀":"了表完成着表持续，过表曾经经历","例子":["我吃了饭/太好了","他看着书/我去过长城","我昨天去过动物园","妹妹正哭着找妈妈","我吃了饭。（了：完成）","他正看着书。（着：进行）","我去过北京。（过：经历）","天黑了。（了：变化）","门开着。（着：状态持续）","他读过这本书。（过：曾经）","下雨了，快回家吧。（了）","他笑着说话。（着）"],"易错":"✗ 我昨天去了北京了（了₁了₂不叠用）","小测":[{"q":"\"我吃饭了\" 的\"了\"是？","options":["了₁完成","了₂变化","都是"],"answer":1,"解析":"句末表新情况（开始吃饭/吃完），是了₂。"},{"q":"表\"曾经\"用？","options":["了","着","过"],"answer":2,"解析":"\"去过\"＝有过去的经历。"}]},{"name":"的/地/得","类比":"的像\"标签\"（贴名词），地像\"滤镜\"（修饰动作），得像\"成绩单\"（动作后打分）。","图示":"<svg viewBox=\"0 0 320 160\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">的 / 地 / 得：看它后面跟什么</text><text x=\"12\" y=\"40\" font-size=\"16\" class=\"svg-ink\">美丽</text><text x=\"48\" y=\"40\" font-size=\"16\" class=\"svg-accent\">的<animate attributeName=\"opacity\" values=\"1;1;0.35;0.35;1\" keyTimes=\"0;0.3;0.33;0.97;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"68\" y=\"40\" font-size=\"16\" class=\"svg-ink\">花</text><text x=\"200\" y=\"40\" font-size=\"12\" class=\"svg-accent\">的＋名词<animate attributeName=\"opacity\" values=\"1;1;0.35;0.35;1\" keyTimes=\"0;0.3;0.33;0.97;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"12\" y=\"78\" font-size=\"16\" class=\"svg-ink\">飞快</text><text x=\"48\" y=\"78\" font-size=\"16\" class=\"svg-accent\">地<animate attributeName=\"opacity\" values=\"0.35;0.35;1;1;0.35;0.35\" keyTimes=\"0;0.3;0.33;0.6;0.63;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"68\" y=\"78\" font-size=\"16\" class=\"svg-ink\">跑</text><text x=\"200\" y=\"78\" font-size=\"12\" class=\"svg-accent\">地＋动词<animate attributeName=\"opacity\" values=\"0.35;0.35;1;1;0.35;0.35\" keyTimes=\"0;0.3;0.33;0.6;0.63;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"12\" y=\"116\" font-size=\"16\" class=\"svg-ink\">跑</text><text x=\"48\" y=\"116\" font-size=\"16\" class=\"svg-accent\">得<animate attributeName=\"opacity\" values=\"0.35;0.35;0.35;1;1;0.35\" keyTimes=\"0;0.6;0.63;0.9;0.93;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"68\" y=\"116\" font-size=\"16\" class=\"svg-ink\">快</text><text x=\"200\" y=\"116\" font-size=\"12\" class=\"svg-accent\">动词＋得＋形容词<animate attributeName=\"opacity\" values=\"0.35;0.35;0.35;1;1;0.35\" keyTimes=\"0;0.6;0.63;0.9;0.93;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"12\" y=\"146\" font-size=\"12\" class=\"svg-muted\">的跟名词、地跟动词、得跟在动词后面</text></svg>","讲解":"的＋名词（定语），地＋动词（状语），得＋补语。口诀：的地得，不一样；名前的（白勺）的，动前的（土也）地，动后的得。","深讲":"的地得不一样：的＋名词（定语），地＋动词（状语），得＋补语。口诀：白勺的贴名，土也地跟动，得后补结果。","分类":[{"类":"的定语式","说明":"的后面是名词，修饰名词。","代表":"的＋名词","例子":["美丽的花。"]},{"类":"地状语式","说明":"地后面是动词，修饰动词。","代表":"地＋动词","例子":["认真地听。"]},{"类":"得补语式","说明":"得后面是补语，补充动词结果。","代表":"动词＋得＋补语","例子":["跑得快。"]}],"怎么认":["后面是不是名词？名词前的用白勺的。","后面是不是动词？动词前的用土也地。","是不是在动词后补结果？补结果的用得。"],"辨析":"的地得不要混：的贴名（美丽的花），地跟动（认真地听），得后补结果（跑得快）。看后面的词是名词、动词还是补语。","例句解析":[{"句":"美丽的花。","析":"的后面是名词花，是定语，用白勺的。"},{"句":"他高兴地笑了。","析":"地后面是动词笑，是状语，用土也地。"}],"练习":[{"q":"“认真_听讲”填？","options":["的","地","得"],"answer":1,"解析":"修饰动词听，用地。","类":"地状语式"},{"q":"“跑_很快”填？","options":["的","地","得"],"answer":2,"解析":"动词后补结果，用得。","类":"得补语式"},{"q":"“美丽_花”填？","options":["的","地","得"],"answer":0,"解析":"后面是名词花，用白勺的。","类":"的定语式"}],"口诀":"白勺的贴名，土也地跟动，得后补结果","例子":["美丽的花","认真地听","跑得快","他高兴地笑了","这道题做得真好","美丽的花。（的+名词）","认真地听讲。（地+动词）","跑得快。（得+补语）","可爱的孩子。（的）","高兴地说。（地）","写得好。（得）","红红的苹果。（的）"],"易错":"的地得是小学高频错；记住\"的地得\"顺口溜","小测":[{"q":"\"认真_听讲\"填？","options":["的","地","得"],"answer":1,"解析":"修饰动词\"听\"，用\"地\"。"},{"q":"\"跑_很快\"填？","options":["的","地","得"],"answer":2,"解析":"动词后补结果，用\"得\"。"}]},{"name":"在/再","讲解":"“在”表处所、存在，“再”表重复、又一次。读音一样（zài），看意思选字。","深讲":"在和再读音一样（zài），意思不同：在表处所、存在，再表重复、又一次。看意思选字，不能只听读音。","分类":[{"类":"在处所式","说明":"在表处所、存在。","代表":"在＋处所","例子":["我在教室里读书。"]},{"类":"再重复式","说明":"再表又一次、重复。","代表":"再＋动词","例子":["妈妈说明天再去公园。"]}],"怎么认":["是不是在说哪里？哪里用在。","是不是在说又一次？又一次用再。","换成处所或又一次，意思通吗？通的就是对的。"],"辨析":"在和再的区别：在是处所（我在教室里），再是重复（再说一遍）。请在说一遍是错的，应为请再说一遍。","例句解析":[{"句":"我在教室里读书。","析":"在表处所教室里，是在处所式。"},{"句":"妈妈说明天再去公园。","析":"再表又一次去，是再重复式。"}],"练习":[{"q":"“请_说一遍”填？","options":["在","再"],"answer":1,"解析":"又一次说，用再。","类":"再重复式"},{"q":"“我_教室里读书”填？","options":["在","再"],"answer":0,"解析":"表处所，用在。","类":"在处所式"},{"q":"“我_吃一次”填？","options":["在","再"],"answer":1,"解析":"又一次吃，用再。","类":"再重复式"}],"例子":["我在教室里读书（处所）","妈妈说明天再去公园（又一次）","✗ 我在吃一次 → ✓ 我再吃一次","我在学校上课。（在：处所）","我们再见面吧。（再：又一次）","他在家里看书。（在）","请再说一遍。（再）","小鸟在天上飞。（在）","明天再来吧。（再）","他在操场上跑步。（在）","吃完饭再出去玩。（再）","鱼在水里游。（在）"],"口诀":"处所在，再又来","易错":"✗ 请在说一遍 → ✓ 请再说一遍","类比":"“在”像图钉📌，钉住地点；“再”像回放键🔁，事情重来一遍。"},{"name":"做/作","讲解":"“做”多指具体动手干，“作”多指抽象创作。口语多用“做”，书面语“作”更多。","深讲":"做多指具体动手干，作多指抽象创作。口语多用做，书面语作更多。口诀：动手做，动笔作。","分类":[{"类":"做动手式","说明":"做表具体动手干。","代表":"做作业、做饭、做游戏","例子":["做作业。"]},{"类":"作抽象式","说明":"作表抽象创作、书面。","代表":"作文、作品、作为","例子":["作文。"]}],"怎么认":["是不是动手干的活？动手用做。","是不是写文章、创作？创作、书面用做。","作是多音字（zuō/zuò），作息读zuō，重点记。"],"辨析":"做和作的区别：做是动手（做饭、做游戏），作是动笔、抽象（作文、作品）。做文是错的，应为作文。","例句解析":[{"句":"做作业、做饭、做游戏。","析":"都是动手干的活，用做。"},{"句":"作文、作品、作为。","析":"都是抽象创作、书面词，用作。"}],"练习":[{"q":"“_文”填？","options":["做","作"],"answer":1,"解析":"作文是抽象创作，用作。","类":"作抽象式"},{"q":"“_饭”填？","options":["做","作"],"answer":0,"解析":"做饭是动手干，用做。","类":"做动手式"},{"q":"“作息”读？","options":["zuò xī","zuō xī","zhuō xī"],"answer":1,"解析":"作息的作读zuō。","类":"作抽象式"}],"例子":["做作业、做饭、做游戏（动手）","作文、作品、作为（书面/抽象）","✗ 做文 → ✓ 作文","做作业。（做：从事）","作报告。（作：写作/担任）","做饭。（做）","作文。（作：写文章）","做人要诚实。（做）","作为班长，他很负责。（作）","做梦。（做）","作曲。（作）","做生意。（做）"],"口诀":"动手做，动笔作","易错":"“作”是多音字（zuō/zuò），“作息”读 zuō"},{"name":"和/与","讲解":"“和”可做连词也可做介词，“与”是书面说法。做连词时前后能互换，做介词时不能。","深讲":"和可做连词也可做介词，与是书面说法。做连词时前后能互换，做介词时不能互换，否则意思变了。","分类":[{"类":"和连词式","说明":"和做连词，前后能互换。","代表":"我和妈妈","例子":["我和妈妈去公园。"]},{"类":"和介词式","说明":"和做介词，前后不能互换。","代表":"和老师谈话","例子":["他和老师谈话。"]},{"类":"与书面式","说明":"与是和的书面说法。","代表":"我与妈妈","例子":["我与妈妈去公园。"]}],"怎么认":["前后换个位置，意思变不变？不变，就是连词。","换了位置意思变了，就是介词。","是不是书面语？书面语多用与。"],"辨析":"和连词和和介词的区别：连词能互换（我和妈妈＝妈妈和我）；介词不能互换（他和老师谈话≠老师和他谈话，意思变了）。","例句解析":[{"句":"我和妈妈去公园。","析":"前后能互换：妈妈和我去公园，是连词。"},{"句":"他和老师谈话。","析":"前后不能互换，是介词。"}],"练习":[{"q":"“我和妈妈去公园”中的和是？","options":["连词","介词","动词"],"answer":0,"解析":"前后能互换，是连词。","类":"和连词式"},{"q":"“他和老师谈话”中的和是？","options":["连词","介词","动词"],"answer":1,"解析":"前后不能互换，是介词。","类":"和介词式"},{"q":"“我与妈妈”中的与是？","options":["口语","书面说法","错别字"],"answer":1,"解析":"与是和的书面说法。","类":"与书面式"}],"例子":["我和妈妈去公园（连词，可换：妈妈和我）","我与妈妈（书面）","他和老师谈话（介词，不可换）","我和他是好朋友。（和：连词）","他与我同岁。（与：连词）","我把书和笔放在桌上。（和）","老师与同学一起劳动。（与）","苹果和香蕉都很甜。（和）","他与大家分享快乐。（与）","爸爸和妈妈去上班了。（和）","我们与时间赛跑。（与）","小猫和小狗在玩耍。（和）"],"口诀":"能互换是连词","易错":"作介词时前后不能换，否则意思变了"},{"name":"把/被","讲解":"“把”字句强调处置（对宾语做了什么），“被”字句强调遭遇（主语受了什么）。","深讲":"把字句强调处置（对宾语做了什么），被字句强调遭遇（主语受了什么）。口诀：把字处置，被字受害；被后多为不如意事。","分类":[{"类":"把处置式","说明":"把字句，主语处置宾语。","代表":"把＋宾语＋动词","例子":["我把教室打扫干净了。"]},{"类":"被遭遇式","说明":"被字句，主语受到动作。","代表":"受事＋被＋动词","例子":["小明被老师表扬了。"]}],"怎么认":["主语是不是在处置宾语？是的，用把。","主语是不是受到了什么？是的，用被。","被后多为不如意事，说好事用被要小心。"],"辨析":"把和被的区别：把是处置（我把教室打扫干净了：我处置了教室）；被是遭遇（小明被老师表扬了：小明受到表扬）。看主语是处置者还是承受者。","例句解析":[{"句":"我把教室打扫干净了。","析":"我处置了教室，是把处置式。"},{"句":"小明被老师表扬了。","析":"小明受到表扬，是被遭遇式。"}],"练习":[{"q":"“我把教室打扫干净了”强调？","options":["处置","遭遇","处所","时间"],"answer":0,"解析":"把字句强调处置。","类":"把处置式"},{"q":"“小明被老师表扬了”强调？","options":["处置","遭遇","处所","时间"],"answer":1,"解析":"被字句强调遭遇。","类":"被遭遇式"},{"q":"“我喜欢音乐”能改把字句吗？","options":["我把音乐喜欢了","不能改","我把音乐喜欢着"],"answer":1,"解析":"喜欢无处置义，不能用把。","类":"把处置式"}],"例子":["我把教室打扫干净了（我处置了教室）","小明被老师表扬了（小明受到表扬）","我喜欢音乐 → 不能改成“把”字句","我把作业写完了。（把：处置）","杯子被打碎了。（被：被动）","妈妈把衣服洗干净了。（把）","他被老师表扬了。（被）","他把门关上了。（把）","小偷被警察抓住了。（被）","我把这本书看完了。（把）","庄稼被水淹了。（被）","她把花插进花瓶。（把）"],"口诀":"把字处置，被字受害","易错":"“被”后多为不如意事，说好事用“被”很别扭"},{"name":"吗/呢/吧","讲解":"“吗”问是非，“呢”问补充或反问，“吧”表商量、祈使。","深讲":"吗问是非，呢问补充或反问，吧表商量、祈使。口诀：吗问是非，呢问补充，吧来商量；陈述句末不能加吗。","分类":[{"类":"吗是非问式","说明":"吗问是不是。","代表":"……吗？","例子":["你去吗？"]},{"类":"呢补充问式","说明":"呢问补充，也可反问。","代表":"……呢？","例子":["你呢？"]},{"类":"吧商量式","说明":"吧表商量、祈使、催促。","代表":"……吧！","例子":["我们走吧！"]}],"怎么认":["是不是在问是非？是非问用吗。","是不是在追问补充？你呢用呢。","是不是在商量、催促？商量、催促用吧。"],"辨析":"吗、呢、吧的区别：吗问是非（你去吗？），呢问补充（你呢？），吧表商量（我们走吧！）。陈述句末不能加吗：我去吗学校是错的。","例句解析":[{"句":"你去吗？","析":"问是非，用吗。"},{"句":"我们走吧！","析":"表商量，用吧。"}],"练习":[{"q":"“你去_？”填？","options":["吗","呢","吧"],"answer":0,"解析":"问是非，用吗。","类":"吗是非问式"},{"q":"“你_？”（追问补充）填？","options":["吗","呢","吧"],"answer":1,"解析":"追问补充，用呢。","类":"呢补充问式"},{"q":"“我们走_！”（商量）填？","options":["吗","呢","吧"],"answer":2,"解析":"表商量，用吧。","类":"吧商量式"}],"例子":["你去吗？（是非问）","你呢？（补充问）","我们走吧！（商量）","快点吧！（催促）","你去过北京吗？（吗：疑问）","他去哪儿了呢？（呢：疑问）","我们一起去吧。（吧：建议）","你吃饭了吗？（吗）","这本书好看呢。（呢：强调）","快点吧，要迟到了。（吧：催促）","你是谁呀？（呢/呀语气）","让我想想吧。（吧：商量）"],"口诀":"吗问是非，呢问补充，吧来商量","易错":"陈述句末不能加“吗”：✗ 我去吗学校"},{"name":"才/就","讲解":"“才”表晚、少、难（比想的晚/少），“就”表早、多、易（比想的早/多）。","深讲":"才表晚、少、难（比想的晚、少、难），就表早、多、易（比想的早、多、易）。口诀：才嫌晚少难，就嫌早多易；时间＋才/就，意思正好相反，别用反。","分类":[{"类":"才晚少难式","说明":"才表比想的晚、少、难。","代表":"九点才起床","例子":["他九点才起床。"]},{"类":"就早多易式","说明":"就表比想的早、多、易。","代表":"六点就起床","例子":["他六点就起床了。"]}],"怎么认":["是不是比想的晚、少、难？是的，用才。","是不是比想的早、多、易？是的，用就。","换成另一个，意思是不是正好相反？是的，说明才和就不能用反。"],"辨析":"才和就的区别：才是晚、少、难（九点才起床：晚），就是早、多、易（六点就起床了：早）。这么难的题，他才用了五分钟：才是少。","例句解析":[{"句":"他九点才起床。","析":"九点比想的晚，用才。"},{"句":"他六点就起床了。","析":"六点比想的早，用就。"}],"练习":[{"q":"“他九点_起床”（比想的晚）填？","options":["才","就"],"answer":0,"解析":"晚用才。","类":"才晚少难式"},{"q":"“他六点_起床了”（比想的早）填？","options":["才","就"],"answer":1,"解析":"早用就。","类":"就早多易式"},{"q":"“这么难的题，他_用了五分钟”填？","options":["才","就"],"answer":0,"解析":"五分钟是少，用才。","类":"才晚少难式"}],"例子":["他九点才起床（比想的晚）","他六点就起床了（比想的早）","这么难的题，他才用了五分钟（少）","他才十岁，就会背诗了。（才：小/就：顺承）","我等了半天，他才来。（才：晚）","他一看就会了。（就：快）","这么难的题，他才不怕呢。（才：强调）","一下课，同学们就跑出去了。（就）","他才走了三分钟。（才：少）","有志者事竟成，他就是例子。（就：确定）","妈妈才回来，就开始做饭。（才…就…）","这本书才五块钱。（才：便宜）"],"口诀":"才嫌晚少难，就嫌早多易","易错":"时间+才/就，意思正好相反，别用反"},{"name":"都/也","讲解":"“都”表全部、总括，“也”表同样、类推。","深讲":"都表全部、总括，也表同样、类推。口诀：都管全部，也管同样；都和全部意思重复，不能叠用。","分类":[{"类":"都全部式","说明":"都表全部。","代表":"同学们都来了","例子":["同学们都来了。"]},{"类":"也同样式","说明":"也表同样。","代表":"我也想去","例子":["我也想去。"]}],"怎么认":["是不是在说全部？全部用都。","是不是在说同样？同样用也。","都和全部叠用了吗？叠用了就是重复。"],"辨析":"都和也的区别：都是全部（同学们都来了），也是同样（我也想去）。全班都全部来了是错的，都和全部重复了。","例句解析":[{"句":"同学们都来了。","析":"都表全部，是都全部式。"},{"句":"他跑得快，我也跑得快。","析":"也表同样，是也同样式。"}],"练习":[{"q":"“同学们_来了”（全部）填？","options":["都","也"],"answer":0,"解析":"全部用都。","类":"都全部式"},{"q":"“我_想去”（同样）填？","options":["都","也"],"answer":1,"解析":"同样用也。","类":"也同样式"},{"q":"“全班都全部来了”对吗？","options":["对","不对","有时对","看情况"],"answer":1,"解析":"都和全部重复了。","类":"都全部式"}],"例子":["同学们都来了（全部）","我也想去（同样）","他跑得快，我也跑得快","我们都爱祖国。（都：全部）","他也会唱歌。（也：同样）","同学们都到齐了。（都）","我也想去。（也）","大家都笑了。（都）","她也不知道。（也）","花草树木都绿了。（都）","你也来啦。（也）","这些题我都会。（都）"],"口诀":"都管全部，也管同样","易错":"✗ 全班都全部来了（“都”和“全部”重复）"},{"name":"以/已","讲解":"“以”表凭借、按照（yǐ），“已”表已经（yǐ）。同音不同义，看意思选。","深讲":"以和已同音（yǐ），意思不同：以表凭借、按照，已表已经。看意思选字，看偏旁区分。","分类":[{"类":"以凭借式","说明":"以表凭借、按照。","代表":"以第一名的成绩","例子":["他以第一名的成绩获奖。"]},{"类":"已已经式","说明":"已表已经。","代表":"已经写完","例子":["我已经写完作业了。"]}],"怎么认":["是不是在说凭借、按照？凭借用以。","是不是在说已经？已经用已。","以经吃饭是错的，应为已经吃饭。"],"辨析":"以和已的区别：以是凭借（以第一名的成绩），已是已经（已经写完作业）。同音不同义，看意思选。","例句解析":[{"句":"他以第一名的成绩获奖。","析":"以表凭借，是以凭借式。"},{"句":"我已经写完作业了。","析":"已表已经，是已已经式。"}],"练习":[{"q":"“他_第一名的成绩获奖”填？","options":["以","已"],"answer":0,"解析":"凭借用以。","类":"以凭借式"},{"q":"“我_经写完作业了”填？","options":["以","已"],"answer":1,"解析":"已经用已。","类":"已已经式"},{"q":"“以经吃饭”对吗？","options":["对","不对","有时对","看情况"],"answer":1,"解析":"应为已经吃饭。","类":"已已经式"}],"例子":["他以第一名的成绩获奖（凭借）","我已经写完作业了（已经）","✗ 以经吃饭 → ✓ 已经吃饭","他已经走了。（已：已经）","我们要以诚待人。（以：用）","会议已结束。（已）","他以优异的成绩毕业。（以）","我早已听说过他。（已）","以理服人。（以）","天色已晚。（已）","他以跑步为乐。（以）","事情已经办妥。（已）"],"口诀":"以表凭借，已表已经","易错":"同音字，看偏旁区分"},{"name":"像/象","讲解":"“像”表相似、好像，“象”指大象或形状、现象。","深讲":"像表相似、好像，象指大象或形状、现象。口诀：相似用单人像，大象气象用象；好像不能写成好象。","分类":[{"类":"像相似式","说明":"像表相似、好像。","代表":"像爸爸一样高","例子":["他像爸爸一样高。"]},{"类":"象动物式","说明":"象指大象。","代表":"大象","例子":["大象的鼻子很长。"]},{"类":"象现象式","说明":"象指形状、现象。","代表":"气象","例子":["气象。"]}],"怎么认":["是不是在说相似、好像？相似用单人像。","是不是在说大象？大象用象。","是不是在说气象、现象？现象用象。"],"辨析":"像和象的区别：像是相似（像爸爸一样高），象是大象或现象（大象、气象）。气像是错的，应为气象。","例句解析":[{"句":"他像爸爸一样高。","析":"表相似，用单人像。"},{"句":"大象的鼻子很长。","析":"指大象，用象。"}],"练习":[{"q":"“他_爸爸一样高”填？","options":["像","象"],"answer":0,"解析":"相似用单人像。","类":"像相似式"},{"q":"“大_的鼻子很长”填？","options":["像","象"],"answer":1,"解析":"大象用象。","类":"象动物式"},{"q":"“气_”填？","options":["像","象"],"answer":1,"解析":"气象是现象，用象。","类":"象现象式"}],"例子":["他像爸爸一样高（相似）","大象的鼻子很长","✗ 气像 → ✓ 气象","他像爸爸一样高。（像：好像）","大象的鼻子很长。（象：动物）","天上的云像棉花。（像）","这只小象很可爱。（象）","她的笑容像春风。（像）","画像挂在墙上。（象：形状/画像）","他长得像妈妈。（像）","气象万千。（象：景象）","好像要下雨了。（像）"],"口诀":"相似用单人像，大象气象用象","易错":"“好像”不能写成“好象”"},{"name":"必须/必需","讲解":"“必须”是副词，表一定要（后跟动词）；“必需”是动词，表一定需要（后跟名词）。","深讲":"必须和必需意思不同：必须是副词，表一定要，后跟动词；必需是动词，表一定需要，后跟名词。口诀：必须跟动作，必需跟东西。","分类":[{"类":"必须动作式","说明":"必须后跟动词，表一定要。","代表":"必须按时到校","例子":["我们必须按时到校。"]},{"类":"必需东西式","说明":"必需后跟名词，表一定需要。","代表":"必需品、日用品","例子":["水是生命必需的。"]}],"怎么认":["后面是不是动词？动词前用必须。","后面是不是名词、东西？东西前用必需。","必需品、日用品用必需，重点记。"],"辨析":"必须和必需的区别：必须跟动作（必须按时到校），必需跟东西（必需品）。必须品是错的，应为必需品。","例句解析":[{"句":"我们必须按时到校。","析":"必须后跟动词到校，是必须动作式。"},{"句":"水是生命必需的。","析":"必需后跟名词，是必需东西式。"}],"练习":[{"q":"“我们_按时到校”填？","options":["必须","必需"],"answer":0,"解析":"后跟动词，用必须。","类":"必须动作式"},{"q":"“_品、日用品”填？","options":["必须","必需"],"answer":1,"解析":"必需品用必需。","类":"必需东西式"},{"q":"“水是生命_的”填？","options":["必须","必需"],"answer":1,"解析":"后跟名词，用必需。","类":"必需东西式"}],"例子":["我们必须按时到校（后跟动词）","水是生命必需的（后跟名词）","✗ 必须品 → ✓ 必需品","我们必须遵守纪律。（必须：一定要）","水是生命必需的。（必需：需要）","你必须按时到校。（必须）","这是生活必需品。（必需）","做人必须诚实。（必须）","阳光是植物生长必需的。（必需）","他必须完成任务。（必须）","粮食是必需品。（必需）","我们必须努力学习。（必须）"],"口诀":"必须跟动作，必需跟东西","易错":"“必需品、日用品”用“必需”"},{"name":"哪/那","讲解":"“哪”表疑问（哪里、哪个），“那”表指示（那里、那个）。","深讲":"哪表疑问（哪里、哪个），那表指示（那里、那个）。口诀：哪是问，那是指；问句用哪，回答用那。","分类":[{"类":"哪疑问式","说明":"哪表疑问。","代表":"哪里、哪个","例子":["你去哪里？"]},{"类":"那指示式","说明":"那表指示。","代表":"那里、那个","例子":["我在那里等你。"]}],"怎么认":["是不是在问？问用哪。","是不是在指？指用那。","问句用哪，回答用那，对号入座。"],"辨析":"哪和那的区别：哪是问（你去哪里？），那是指（我在那里等你）。那里有几个人是错的，应为哪里有几个人。","例句解析":[{"句":"你去哪里？","析":"问地点，用哪。"},{"句":"我在那里等你。","析":"指地点，用那。"}],"练习":[{"q":"“你去_里？”填？","options":["哪","那"],"answer":0,"解析":"问地点，用哪。","类":"哪疑问式"},{"q":"“我在_里等你”填？","options":["哪","那"],"answer":1,"解析":"指地点，用那。","类":"那指示式"},{"q":"“_里有几个人？”（问句）填？","options":["哪","那"],"answer":0,"解析":"问句用哪。","类":"哪疑问式"}],"例子":["你去哪里？（疑问）","我在那里等你（指示）","✗ 那里有几个人？→ ✓ 哪里有几个人？","你去哪儿？（哪：疑问）","那是我的书包。（那：指示）","哪个是你的？（哪）","那座山很高。（那）","你喜欢哪一个？（哪）","那边有很多人。（那）","哪里有困难，哪里就有我们。（哪）","那天我们很开心。（那）","你要去哪里？（哪）"],"口诀":"哪是问，那是指","易错":"问句用“哪”，回答用“那”"},{"name":"不/没","讲解":"“不”表主观不愿、经常性否定；“没”表客观没有、过去没发生。","深讲":"不表主观不愿、经常性否定，没表客观没有、过去没发生。口诀：不表意愿，没表有无；没常和过搭配表过去。","分类":[{"类":"不意愿式","说明":"不表不想、经常。","代表":"不去、不喜欢","例子":["我不去。"]},{"类":"没客观式","说明":"没表客观没有、没去成。","代表":"没去","例子":["我没去。"]},{"类":"没过去式","说明":"没＋过表过去没发生。","代表":"没来过","例子":["他没来过北京。"]}],"怎么认":["是不是不想去？不想用不。","是不是没去成？没去成用没。","是不是在说过去？过去用没＋过。"],"辨析":"不和没的区别：不去是不想去（主观），没去是没去成（客观）；不喜欢是经常， 没来过是过去。看是意愿还是有无、过去。","例句解析":[{"句":"我不去。","析":"不想去，是不意愿式。"},{"句":"我没去。","析":"没去成，是没客观式。"}],"练习":[{"q":"“我_去”（不想去）填？","options":["不","没"],"answer":0,"解析":"不想去用不。","类":"不意愿式"},{"q":"“我_去”（没去成）填？","options":["不","没"],"answer":1,"解析":"没去成用没。","类":"没客观式"},{"q":"“他_来过北京”（过去）填？","options":["不","没"],"answer":1,"解析":"过去用没＋过。","类":"没过去式"}],"例子":["我不去（不想去）","我没去（没去成）","他没来过北京（过去）","我不喜欢吃辣（经常）","我不喜欢吃辣。（不：意愿/性质否定）","我没吃过。（没：未曾）","他不去。（不）","我没带伞。（没）","今天不冷。（不）","他没来上课。（没）","我不怕困难。（不）","作业还没写完。（没）"],"口诀":"不表意愿，没表有无","易错":"“没”常和“过”搭配表过去：我没看过"},{"name":"还是/或者","讲解":"“还是”用于选择问句，“或者”用于陈述句表选择。","深讲":"还是用于选择问句，或者用于陈述句表选择。口诀：问句还是，陈述或者；问句里用还是，陈述句里用或者，别用反。","分类":[{"类":"还是问句式","说明":"还是用于选择问句。","代表":"还是喝牛奶？","例子":["你喝水还是喝牛奶？"]},{"类":"或者陈述式","说明":"或者用于陈述句。","代表":"或者去公园，或者去图书馆","例子":["周末或者去公园，或者去图书馆。"]}],"怎么认":["是不是在问？问用还是。","是不是在陈述选择？陈述用或者。","你去或者不去是错的，应为你去还是不去。"],"辨析":"还是和或者的区别：还是问（你喝水还是喝牛奶？），或者陈述（周末或者去公园，或者去图书馆）。看是不是问句。","例句解析":[{"句":"你喝水还是喝牛奶？","析":"选择问句，用还是。"},{"句":"周末或者去公园，或者去图书馆。","析":"陈述句表选择，用或者。"}],"练习":[{"q":"“你喝水_喝牛奶？”填？","options":["还是","或者"],"answer":0,"解析":"问句用还是。","类":"还是问句式"},{"q":"“周末_去公园，_去图书馆”（陈述）填？","options":["还是，还是","或者，或者","还是，或者"],"answer":1,"解析":"陈述句用或者。","类":"或者陈述式"},{"q":"“你去_不去？”填？","options":["还是","或者"],"answer":0,"解析":"问句用还是。","类":"还是问句式"}],"例子":["你喝水还是喝牛奶？（问句）","周末或者去公园，或者去图书馆（陈述）","✗ 你去或者不去？→ ✓ 你去还是不去？","你喝茶还是喝咖啡？（还是：选择问）","他或者去北京，或者去上海。（或者：陈述选择）","你喜欢红色还是蓝色？（还是）","周末或者去爬山，或者去看电影。（或者）","是你去，还是我去？（还是）","他或者跑步，或者游泳。（或者）","你要苹果还是香蕉？（还是）","我们或者今天走，或者明天走。（或者）","你是学生还是老师？（还是）"],"口诀":"问句还是，陈述或者","易错":"问句里用“还是”，陈述句里用“或者”"}]}],"module":"语法知识库","标准":"《义务教育语文课程标准》附录三·语法修辞知识要点","说明":"覆盖词类、短语、单句成分、复句、修辞、病句六大块，为中考语文基础知识与作文语言服务"},"logic":{"categories":[{"id":"gainian","name":"形式逻辑基础","items":[{"name":"概念：定义与划分","类比":"概念就像抽屉标签：定义是写清标签上是什么，划分是把大抽屉分成小格。","讲解":"定义揭示内涵（是什么），划分揭示外延（有哪些）。定义=种差+属概念。","口诀":"定义讲内涵，划分列外延","例子":["白马不是马：白马（种）≠马（属），混淆层次","定义不能循环","好定义：\"人是能制造工具的动物\"（种差\"能制造工具\"+属\"动物\"）","坏定义：\"人是两条腿的动物\"（鸡也是，种差不唯一）","好划分：\"学生\"按年级分为一年级/二年级/三年级（标准统一）","坏划分：\"水果\"按颜色分红的、按大小分大的（标准不一）","比喻不是定义：\"老师是辛勤的园丁\"很美，但不是定义","好定义：\"椅子是供人坐的家具\"（属\"家具\"＋种差\"供人坐\"，一听就知道是什么）","坏定义：\"西瓜是夏天吃的东西\"（只讲了季节，没讲出西瓜本身的样子和特点）","坏划分：\"把同学分成男生和戴眼镜的\"（标准交叉：戴眼镜的男生两边都算，子项不互斥）"],"深讲":"定义回答“这是什么”，要抓住这个东西跟同类不一样的地方（种差），再说出它属于哪个大类（属）。划分回答“有哪些”，要按一个标准一次分完，分出来的小类不能重叠、不能漏掉。定义和划分是一对搭档：先定义清楚，才能分得干净。","怎么认":["先找属：这个东西属于哪个大类？","再找种差：它跟同类比，特别在哪里？","检查划分：是不是一个标准分到底？小类有没有重叠或漏掉？"],"辨析":"定义和划分别混：定义是给一个概念“画像”（内涵），划分是给一个大类“分家”（外延）。“人是能制造工具的动物”是定义；“动物分为哺乳动物、鸟类、鱼类……”是划分。","例句解析":[{"句":"白马不是马：白马（种）≠马（属），混淆层次","析":"“白马”是“马”下面的一个小类，把小类和大类画等号，就像说“苹果不是水果”一样，层次搞混了。"},{"句":"好划分：\"学生\"按年级分为一年级/二年级/三年级（标准统一）","析":"一个标准（年级）一次分完，每个学生只属于一个年级，不重叠、不遗漏，这就是合格的划分。"}],"易错":"划分标准要统一，不能一会儿按颜色一会儿按大小","练习":[{"q":"给“钢笔”下定义，哪个最好？","options":["钢笔是笔","钢笔是用来写字的笔","钢笔是学生用的东西"],"answer":1,"解析":"属（笔）＋种差（用来写字）。A只有属没种差，C种差不唯一（学生用的东西太多了）。"},{"q":"“把水果按颜色分为红的、大的”错在哪里？","options":["标准不统一","颜色分错了","水果不能分"],"answer":0,"解析":"一会儿按颜色一会儿按大小，两个标准混在一起，小类会重叠。"},{"q":"下面哪个是划分？","options":["椅子是供人坐的家具","动物分为哺乳动物和鸟类","西瓜是夏天吃的东西"],"answer":1,"解析":"“分为……”是把大类分小类；另外两个都是在给单个概念下定义（一个好一个坏）。"}],"动画":{"steps":[{"tokens":["属概念","＋","种差","＝","定义"],"note":"定义公式：先找大类（属），再说出区别（种差）"},{"tokens":["人","是","会制造工具的","动物"],"note":"动物（属）＋会制造工具（种差）＝人"},{"tokens":["✗","人","是","人类的一员"],"note":"错：循环定义，用\"人类\"解释\"人\"等于没说"}]},"小测":[{"q":"给\"学生\"下定义，哪个对？","options":["学生是上学的人","学生是在学校学习的人","学生是学生"],"answer":1,"解析":"属（人）＋种差（在学校学习）。A太宽，C循环。"}]},{"name":"三段论","类比":"三段论就像接力赛：大前提交棒给小前提，推出结论。","图示":"<svg viewBox=\"0 0 400 110\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"30\" y=\"30\" font-size=\"14\">大前提：知识分子都应受尊重</text><text x=\"30\" y=\"55\" font-size=\"14\">小前提：人民教师是知识分子</text><line x1=\"30\" y1=\"65\" x2=\"370\" y2=\"65\" stroke=\"#333\"/><text x=\"30\" y=\"90\" font-size=\"14\" font-weight=\"bold\">结论：人民教师应受尊重</text></svg>","讲解":"大前提（一般）+小前提（个别）→结论。","口诀":"大套小，推出结论跑不了","例子":["凡人皆有死，苏格拉底是人，所以苏格拉底有死","大前提：所有金属都导电；小前提：铜是金属；结论：铜导电","大前提：鲸是哺乳动物；小前提：哺乳动物用肺呼吸；结论：鲸用肺呼吸","错例：鸟会飞，企鹅是鸟，所以企鹅会飞（大前提\"鸟会飞\"不真）","错例：人是动物，狗是动物，所以人是狗（中项\"动物\"不周延）","有效式：下雨地就湿；下雨了→所以地湿了（肯定前件）","大前提：鸟类都用肺呼吸；小前提：鸽子是鸟类；结论：鸽子用肺呼吸","大前提：植物都需要阳光；小前提：阳台上的绿萝是植物；结论：绿萝需要阳光","错例：下雨地就湿；地湿了→所以下雨了（错：洒水车洒水也会湿，肯定后件推不出前件）","大前提：所有偶数都能被2整除；小前提：14是偶数；结论：14能被2整除"],"深讲":"三段论是大前提、小前提、结论三句话的接力：大前提讲一般道理，小前提把个别情况套进去，结论自然跑出来。关键是中间那个词（中项）要在两句话里真正搭上桥，而且前提本身要是真的。","怎么认":["先找结论：它要证明什么？","再找大前提（一般道理）和小前提（个别情况）。","检查两点：前提是不是真的？中间词有没有真正搭上桥？"],"辨析":"三段论和“因为……所以……”不完全一样：日常的因为所以常常只说一个理由；三段论必须有两个前提，一个讲一般、一个讲个别，结论是被“推”出来的，不是直接喊出来的。","例句解析":[{"句":"大前提：所有金属都导电；小前提：铜是金属；结论：铜导电","析":"“金属”是中项，在大前提里讲所有金属，在小前提里把铜放进金属，桥搭上了，结论站得住。"},{"句":"错例：人是动物，狗是动物，所以人是狗（中项\"动物\"不周延）","析":"“动物”这个词两头都没说全——人只是动物中的一小部分，狗也是另一小部分，两小部分不能因为同属动物就画等号。"}],"易错":"两个坑最常见：一是前提本身不真（“鸟都会飞”），结论就不可靠；二是中项两头都不周延（“人是动物，狗是动物”），两个小类不能硬凑成一对。","练习":[{"q":"“所有鸟都会飞，企鹅是鸟，所以企鹅会飞”问题出在哪？","options":["小前提错了","大前提不全真","结论推错了"],"answer":1,"解析":"企鹅、鸵鸟都不会飞，“所有鸟都会飞”这个大前提本身不真，结论就靠不住。"},{"q":"补全三段论：大前提：植物都需要水；小前提：仙人掌是植物；结论是？","options":["仙人掌不需要水","仙人掌需要水","所有植物都是仙人掌"],"answer":1,"解析":"把小前提套进大前提：仙人掌属于植物，所以也需要水。"},{"q":"“下雨地就湿；地湿了，所以下雨了”错在哪里？","options":["前提错了","肯定了后件，推不出前件","结论太长"],"answer":1,"解析":"地湿的原因很多（洒水、拖地），从“地湿”不能倒推出“下雨”，这是肯定后件的毛病。"}],"动画":{"steps":[{"tokens":["所有","人","都会","死"],"note":"大前提：一般道理"},{"tokens":["苏格拉底","是","人"],"note":"小前提：个别情况"},{"tokens":["所以","苏格拉底","会","死"],"note":"结论：水到渠成"}]},"小测":[{"q":"三段论哪项错了？大前提：鸟会飞。小前提：企鹅是鸟。结论：企鹅会飞","options":["大前提错了","小前提错了","推理错了"],"answer":0,"解析":"大前提\"鸟会飞\"不全真（鸵鸟企鹅不会），前提错结论就不可靠。"}]},{"name":"四大逻辑规律","类比":"四律就像思维交通规则：违反就撞车（自相矛盾）。","图示":"<svg viewBox=\"0 0 400 160\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"15\" y=\"10\" width=\"180\" height=\"65\" rx=\"8\" fill=\"#e8f5e9\"/><text x=\"25\" y=\"35\" font-size=\"14\" font-weight=\"bold\">同一律</text><text x=\"25\" y=\"58\" font-size=\"12\">咖啡不能一会儿变茶</text><rect x=\"205\" y=\"10\" width=\"180\" height=\"65\" rx=\"8\" fill=\"#ffebee\"/><text x=\"215\" y=\"35\" font-size=\"14\" font-weight=\"bold\">矛盾律</text><text x=\"215\" y=\"58\" font-size=\"12\">不能又下雨又没下雨</text><rect x=\"15\" y=\"85\" width=\"180\" height=\"65\" rx=\"8\" fill=\"#e3f2fd\"/><text x=\"25\" y=\"110\" font-size=\"14\" font-weight=\"bold\">排中律</text><text x=\"25\" y=\"133\" font-size=\"12\">灯只能开或关</text><rect x=\"205\" y=\"85\" width=\"180\" height=\"65\" rx=\"8\" fill=\"#fff3e0\"/><text x=\"215\" y=\"110\" font-size=\"14\" font-weight=\"bold\">充足理由律</text><text x=\"215\" y=\"133\" font-size=\"12\">说猫聪明要举例</text></svg>","讲解":"同一律（概念确定）、矛盾律（不自相矛盾）、排中律（非此即彼）、充足理由律（言之有据）。","口诀":"同一矛盾排中足，思维守法不糊涂","动画":{"steps":[{"tokens":["这杯","咖啡","不能","一会儿变茶"],"note":"同一律：概念要确定，前后一致"},{"tokens":["今天","下雨了","＋","没下雨","＝","✗"],"note":"矛盾律：不能自相矛盾"},{"tokens":["灯","开","或","关"],"note":"排中律：非此即彼，不许骑墙"},{"tokens":["猫聪明","因为","会开门"],"note":"充足理由律：说观点要给理由"}]},"例子":["同一律：讨论\"成功\"时，前后必须指同一个意思，不能一会儿说成绩一会儿说快乐","矛盾律：不能同时说\"这本书我看过\"又说\"这本书我没看过\"（同一意义上）","排中律：\"小明及格了\"和\"小明没及格\"，必有一真（非此即彼）","充足理由律：说\"他作弊了\"要有证据，不能空口断言","违反排中律：\"这次考试要么第一要么倒数第一\"（还有中间名次）","违反同一律：辩论时把\"自由\"一会儿讲成\"为所欲为\"，一会儿讲成\"自律\"","同一律：写作文说\"我的妈妈\"，全文都要指同一个人，不能写着写着变成奶奶","充足理由律：说\"我们班最干净\"，要拿出证据：地面没纸屑、桌椅排整齐","违反充足理由律：\"他肯定偷懒了\"——没有证据，只是\"我觉得\"，这就是缺理由","排中律：\"今天是星期一\"和\"今天不是星期一\"，必有一真"],"深讲":"四条规律是思维的四条底线：同一律——说话前后同一个词指同一个意思；矛盾律——同一个意义上不能又肯定又否定；排中律——非此即彼的两边必有一真；充足理由律——下判断要拿出理由。四条一起守，话才讲得清楚、站得住。","怎么认":["先问：同一个词前后意思变了吗？（同一律）","再问：有没有自己打自己？（矛盾律）","是“非此即彼”吗？中间还有没有第三种？（排中律）","最后问：理由拿出来了吗？（充足理由律）"],"辨析":"矛盾律和排中律最容易混：矛盾律是“不能两个都真”（不能又下雨又没下雨）；排中律是“不能两个都假”（“及格”和“没及格”必有一真）。一个管“不能都真”，一个管“不能都假”。","例句解析":[{"句":"违反排中律：\"这次考试要么第一要么倒数第一\"（还有中间名次）","析":"第一和倒数第一不是“非此即彼”，中间还有第二名、第三名……硬说“要么这个要么那个”，就是排中律用错了地方。"},{"句":"充足理由律：说\"他作弊了\"要有证据，不能空口断言","析":"“作弊”是严重的判断，没有证据就说出口，等于没理由下结论——充足理由律要求每个判断都有根据。"}],"易错":"排中律只管“非此即彼”的两种情况：中间还有别的情况时不能硬套（“第一还是倒数第一”中间还有很多名次）；矛盾律管的是同一个意义上的自相矛盾，换了意思就不算（“我喜欢吃苹果”和“我不喜欢吃青苹果”不矛盾）。","练习":[{"q":"“讨论'勇敢'时，一会儿说敢举手，一会儿说敢打架”违反了哪条规律？","options":["矛盾律","同一律","排中律"],"answer":1,"解析":"同一个词“勇敢”前后意思偷偷换了，违反同一律。"},{"q":"“这盏灯既开着又没开着”违反了哪条规律？","options":["充足理由律","矛盾律","排中律"],"answer":1,"解析":"同一个意义上又肯定又否定，自己打自己，违反矛盾律。"},{"q":"“我觉得他跑得最快”作为判断缺什么？","options":["缺同一律","缺充足理由","缺排中律"],"answer":1,"解析":"“我觉得”不是理由，要拿出计时成绩或比赛名次，才算有充足理由。"}]},{"name":"推理三兄弟：演绎/归纳/类比","类比":"演绎像\"漏斗\"（从大到小），归纳像\"堆塔\"（从小堆到大），类比如\"照镜子\"（看A像B）。","图示":"<svg viewBox=\"0 0 400 120\" xmlns=\"http://www.w3.org/2000/svg\"><polygon points=\"30,20 130,20 80,100\" fill=\"#e3f2fd\" stroke=\"#1976d2\"/><text x=\"45\" y=\"60\" font-size=\"12\">演绎↓</text><polygon points=\"160,100 260,100 210,20\" fill=\"#fff3e0\" stroke=\"#ef6c00\"/><text x=\"175\" y=\"60\" font-size=\"12\">归纳↑</text><rect x=\"290\" y=\"30\" width=\"80\" height=\"60\" rx=\"8\" fill=\"#f3e5f5\" stroke=\"#8e24aa\"/><text x=\"300\" y=\"65\" font-size=\"12\">类比⇄</text></svg>","讲解":"演绎：一般→个别（三段论）；归纳：个别→一般（看多了总结）；类比：A像B，B有某性→A也有。","口诀":"演绎漏斗归纳塔，类比照镜子","例子":["演绎：人会死→苏格拉底会死","归纳：乌鸦都是黑的（看了一万只）","类比：地球有水有生命→火星有水→可能有生命","演绎：三角形内角和180°→这个三角形内角和也是180°（数学证明）","归纳：尝了十个苹果都甜→这箱苹果大概是甜的（或然，非必然）","类比错例：蝙蝠会飞，鸟会飞→蝙蝠是鸟（表面像，本质不同）","演绎：直角三角形的两条直角边是3和4，斜边就是5（勾股定理套用）","归纳：班里十个同学都喜欢踢足球，大概全班很多同学喜欢踢足球（只是大概，不是必然）","类比：水管堵了水流不畅，血管堵了血液不畅→血管也要“疏通”（医生打比方）","归纳错例：昨天吃冰淇淋拉肚子，就说所有冰淇淋都不好（一次个例推全体，样本太小）"],"深讲":"三兄弟方向不同：演绎从一般道理出发，结论是必然的（前提真，结论一定真）；归纳从很多个别例子出发，结论只是“大概”，例子越多越可信；类比从相似出发，结论也是“可能”，关键看像的是本质还是表面。","怎么认":["看方向：一般→个别是演绎，个别→一般是归纳。","看关系：A像B所以A可能像B那样，是类比。","看把握：说“一定”的是演绎，说“大概、可能”的是归纳或类比。"],"辨析":"归纳和类比都只能得“可能”，但路子不同：归纳是“见得多了，总结规律”（看了一万只乌鸦）；类比是“这个像那个，借来推一推”（地球像火星）。演绎最保险，但前提必须真。","例句解析":[{"句":"归纳：尝了十个苹果都甜→这箱苹果大概是甜的（或然，非必然）","析":"十个苹果只是这箱的一部分，结论只能说“大概”，不能说“一定”——归纳的结论永远留有余地。"},{"句":"类比错例：蝙蝠会飞，鸟会飞→蝙蝠是鸟（表面像，本质不同）","析":"会飞只是表面相似，蝙蝠是胎生哺乳动物，鸟是卵生——类比只看表面就会推错。"}],"易错":"归纳的\"枚举\"不完全会翻车（黑天鹅）；类比要本质像，不能表面像","练习":[{"q":"“所有矩形的对角线相等，这个图形是矩形，所以它的对角线相等”是什么推理？","options":["归纳","类比","演绎"],"answer":2,"解析":"从一般定理套到个别图形，是演绎（前提真结论必然真）。"},{"q":"“连续三天都下雨，明天大概也会下雨”是什么推理？","options":["演绎","归纳","类比"],"answer":1,"解析":"从几天的个别情况推明天的一般情况，是归纳，结论只是“大概”。"},{"q":"“自行车胎破了跑不快，人的血管堵了也跑不快”这是在？","options":["演绎","归纳","类比"],"answer":2,"解析":"拿自行车和人作比较、借来推一推，是类比；要小心只看表面相似。"}],"小测":[{"q":"\"看到10只白天鹅，得出天鹅都是白的\"是什么推理？","options":["演绎","归纳","类比"],"answer":1,"解析":"从个别到一般，是归纳（不完全归纳，有风险）。"}]}]},{"id":"luojibing","name":"病句里的逻辑错误","items":[{"name":"自相矛盾","讲解":"前后说法打架：他是众多死难者中幸免的一个（都死了还幸免？）。","口诀":"前后打架自己吵，改掉一个就好了","例子":["错：他是众多死难者中幸免的一个","对：他是众多遇难者中幸免的一个","错：大约三十多人（\"大约\"和\"多\"自相矛盾）","对：三十多人","错：这场球赛胜负未分，结果双方打成平局","对：这场球赛胜负未分，双方最终握手言和","错：这道题我不会做，但我已经做出来了","对：这道题我一开始不会做，后来做出来了","错：操场上一个人也没有，只有小明在跑步","对：操场上只有小明在跑步"],"深讲":"自相矛盾是句子自己打自己：前半句说一个意思，后半句又说相反的意思，两句话不能同时是真的。找它的方法是把前后分句拆开，问一句“这两句能同时成立吗”——不能，就是自相矛盾。","怎么认":["把句子拆成前后两半。","每半各是什么意思？写下来比一比。","两半能不能同时是真的？不能，就是自相矛盾。"],"辨析":"自相矛盾和“前后不一致”不一样：前后不一致可能是话题跑偏了；自相矛盾是同一个点上自己否定自己，比如“都死了”又“幸免”，同一个“死”字两边打架。","例句解析":[{"句":"错：他是众多死难者中幸免的一个","析":"“死难者”就是已经死了的人，“幸免”是没死——同一个人既死了又没死，自己打自己。把“死难”改成“遇难”（遇到灾难的人，可死可活）就通了。"},{"句":"错：大约三十多人（\"大约\"和\"多\"自相矛盾）","析":"“大约”表示不确定，“多”表示超过三十——一个说“大概”，一个说“肯定超过”，两个意思撞车，留一个就行：“三十多人”。"}],"易错":"检查前后分句能否同时为真","练习":[{"q":"“大约五十多个同学参加了比赛”错在哪里？","options":["数字不对","大约和多自相矛盾","同学写错了"],"answer":1,"解析":"“大约”和“多”都表示不确定/超过，两个意思打架，删掉一个：“五十多个同学”。"},{"q":"下面哪句自相矛盾？","options":["他是遇难者中幸免的一个","他是死难者中幸免的一个","他是幸存者中的一个"],"answer":1,"解析":"“死难者”已经死了，不可能“幸免”；“遇难者”只是遇到灾难，可死可活，才能幸免。"},{"q":"“这场球赛胜负未分，结果双方打成平局”为什么错？","options":["平局写错了","胜负未分和打成平局意思打架","球赛写错了"],"answer":1,"解析":"“胜负未分”是还没分出胜负，“打成平局”是已经比完了——前半句说没比完，后半句说比完了，前后打架。"}],"动画":{"steps":[{"tokens":["众多","死难者","中"],"note":"死难者＝已经死了"},{"tokens":["幸免","的","一个"],"note":"幸免＝没死"},{"tokens":["✗","死了","＋","没死"],"note":"撞车！改\"死难\"为\"遇难\""}]}},{"name":"主客倒置","讲解":"谁对谁说反了：京剧对她很熟悉→她对京剧很熟悉。","口诀":"谁感受谁在前，东西不能当主角","例子":["错：爱迪生这个名字对我们不陌生","对：我们对爱迪生这个名字不陌生","错：这部电影对观众很感动","对：观众对这部电影很感动","错：他的事迹对我们很感动","对：我们对他的事迹很感动","错：这个问题对他很清楚","对：他对这个问题很清楚","错：这首古诗对我们很熟悉","对：我们对这首古诗很熟悉"],"深讲":"有些感受词（熟悉、陌生、清楚、感动、了解）的主人只能是人：是“人对东西熟悉”，不是“东西对人熟悉”。东西不会“熟悉”谁、“感动”谁，把东西放在主语位置，就是主客倒置。改法是把人和东西的位置对调。","怎么认":["找感受词：熟悉、陌生、清楚、感动、了解。","问：谁在感受？感受的一方应该是人。","如果主语是东西（电影、名字、事迹），就是倒置，对调人和东西的位置。"],"辨析":"主客倒置和“被动句”不一样：“我被老师表扬了”主语是我，动作是我接受的，没错；主客倒置是感受的主人错了——“电影对观众很感动”里，真正感动的是观众，不是电影。","例句解析":[{"句":"错：爱迪生这个名字对我们不陌生","析":"“不陌生”的感受主人是我们——是我们对名字不陌生。名字不会“对我们陌生”，把“我们”和“名字”对调就对了。"},{"句":"错：这部电影对观众很感动","析":"感动的是观众，电影是让人感动的东西。主语应该是“观众”，电影不能“感动”观众作主语——对调：“观众对这部电影很感动”。"}],"易错":"不是所有“对……”的句子都倒置：“老师对我们很亲切”没错（亲切的是老师，老师是人）；只有感受词（熟悉、陌生、清楚、感动、了解）的主人必须是人，东西作主语才算倒置。","练习":[{"q":"“这首诗对我们很熟悉”错在哪里？","options":["诗不能作主语","熟悉的主人应该是我们，不是诗","我们写错了"],"answer":1,"解析":"“熟悉”是人的感受，应该是“我们对这首诗很熟悉”，诗不会熟悉我们。"},{"q":"下面哪句是对的？","options":["故宫对游客不陌生","游客对故宫不陌生","故宫很熟悉游客"],"answer":1,"解析":"熟悉的主人是游客：游客对故宫不陌生。A和C都把故宫当成了感受的主人。"},{"q":"“老师对我们很亲切”有没有主客倒置？","options":["有","没有","说不清"],"answer":1,"解析":"亲切的是老师，老师是人，主语没错——不是所有“对”字句都是倒置，只有感受词的主人错了才算。"}]},{"name":"强加因果","讲解":"无因果硬说因果：因为他来自北方，思想还是旧的一套。","口诀":"没有因果别硬凑，先问一句推得出","易错":"问一句：前者真能推出后者吗","例子":["错：因为他是北方人，所以思想守旧（地域推不出思想）","错：早上没吃鸡蛋，所以没考好（毫无关联）","错：他穿了红衣服，所以比赛赢了（迷信式因果）","对：昨晚熬夜刷题，今天上课精神不振（真实因果）","检验法：问一句\"前者真能推出后者吗\"，推不出就是强加因果","错：因为他个子高，所以数学一定好（身高推不出数学）","错：因为今天是星期三，所以要下雨（星期推不出天气）","错：因为教室里坐满了人，所以这节课一定讲得好（人数推不出质量）","对：多喝水、早睡觉，感冒好得快（身体恢复需要休息和水分）","对：每天练字半小时，字越写越好看（练习带来进步）"],"深讲":"强加因果是把两件碰巧一起出现的事，硬说成“因为……所以……”。检验办法就一句：前者真能推出后者吗？推不出，就是强加。比如“穿红衣服”和“比赛赢了”只是碰巧，红衣服不会让人跑得更快。","怎么认":["找出“因为”后面的原因和“所以”后面的结果。","问：原因真能推出结果吗？换个情况还成立吗？","推不出，或者只是碰巧一起出现，就是强加因果。"],"辨析":"强加因果和“真实因果”的区别在“必然”：熬夜→上课没精神，是身体规律，换谁都一样；穿红衣服→比赛赢，换件衣服也可能赢——经不起“换一换”检验的，就是强加。","例句解析":[{"句":"错：因为他是北方人，所以思想守旧（地域推不出思想）","析":"“北方人”是出生地，“思想守旧”是个人想法，出生地推不出想法——两件事没有因果链，硬凑就是强加。"},{"句":"对：昨晚熬夜刷题，今天上课精神不振（真实因果）","析":"熬夜少睡→白天没精神，是身体的真实规律，换谁熬夜都一样，这才叫因果。"}],"练习":[{"q":"“他早上吃了鸡蛋，所以考试考好了”错在哪里？","options":["鸡蛋不能吃","吃鸡蛋和考好没有因果","考试写错了"],"answer":1,"解析":"吃鸡蛋不会让人变聪明，两件事只是碰巧同一天发生，硬说因果就是强加。"},{"q":"下面哪个是真实因果？","options":["穿新鞋所以跑得快","下雨所以地面湿了","戴眼镜所以成绩好"],"answer":1,"解析":"雨水落到地上，地面自然会湿，这是真实规律；新鞋、眼镜和跑得快、成绩好没有因果。"},{"q":"检验因果最好的办法是？","options":["看两件事是不是同一天发生","问一句“前者真能推出后者吗”","看句子有没有“因为”"],"answer":1,"解析":"同一天发生不等于有因果；有没有“因为”也不作数——关键看前者能不能推出后者。"}]},{"name":"以偏概全","类比":"以偏概全就像\"盲人摸象\"：摸到腿说象是柱子，摸到鼻子说象是管子。","讲解":"拿部分当全部。看到几个就下结论全体，犯了\"简单枚举\"的错。","口诀":"部分推全体，十有八九错","例子":["错：我班三个同学近视，所以全班都近视","错：他北方人，北方人都豪爽","错：我去过一次北京很堵，所以北京天天堵","错：两个学霸都熬夜，所以熬夜才能当学霸","对：调查显示我班80%同学近视，需注意用眼（有数据支撑≠以偏概全）","写作提醒：举例后必须\"扣题分析\"，摆个例子就下大结论必翻车","错：我家猫怕水，所以所有猫都怕水","错：他一次考试没考好，就说他不是学习的料","错：只看到操场上有几个纸团，就说我们学校卫生最差","对：问了全班同学才说“我们班大多数同学喜欢踢球”（调查全体再下结论）"],"深讲":"以偏概全是拿一小部分当全部：看到几个人、几件事，就敢说“都”“天天”“所有”。想下“全部”的结论，要么调查全体，要么有足够大的抽样和数据；只凭几个例子就下大结论，一定翻车。","怎么认":["找结论里的大词：都、天天、所有、肯定。","问：结论是凭几个例子下的？还是调查了全体/有数据？","只凭几个例子就下大结论，就是以偏概全。"],"辨析":"以偏概全和“举例论证”不一样：举例论证是拿例子当证据，结论留有余地（“可见……很重要”）；以偏概全是拿例子当全部，结论说死（“所以全班都……”）。例子后面有没有“扣题分析”、结论有没有留余地，是分水岭。","例句解析":[{"句":"错：我班三个同学近视，所以全班都近视","析":"三个同学只是全班的一小部分，从三个人推到全班，样本太小——要下“全班”的结论，得调查全班。"},{"句":"对：调查显示我班80%同学近视，需注意用眼（有数据支撑≠以偏概全）","析":"这个结论有调查数据支撑，“80%”也不是“全部”——有数据、留余地，就不是以偏概全。"}],"易错":"议论文举例后一定要\"扣题分析\"，不能例子一摆就下大结论","练习":[{"q":"“我去过一次北京很堵，所以北京天天堵”错在哪里？","options":["北京不堵","一次经历推不出天天","去字写错了"],"answer":1,"解析":"一次堵车只是某一天的情况，推不到“天天”——以偏概全。"},{"q":"下面哪个不是以偏概全？","options":["两个学霸熬夜，所以熬夜才能当学霸","调查了全班才说大多数同学喜欢踢球","我家猫怕水，所以所有猫都怕水"],"answer":1,"解析":"调查了全班再下结论，有全体数据支撑；另外两个都是拿个别推全体。"},{"q":"写议论文时，举例后最应该做什么？","options":["再举一个例子","扣题分析，把例子和观点连起来","直接下大结论"],"answer":1,"解析":"摆个例子就下大结论是以偏概全；要分析例子为什么能证明观点，结论才站得住。"}]}]},{"id":"lunzheng","name":"议论文论证逻辑","items":[{"name":"举例论证","类比":"举例就像证人出庭：光有观点不行，得叫证人作证。","讲解":"公式：分论点+事例简述+扣题分析+小结回扣。事例是载体，分析才是灵魂。","口诀":"观点事例加分析，回扣分论才扎实","例子":["樊锦诗守敦煌：事例+坚守的分析+回扣","论\"勤奋\"：匡衡凿壁偷光+分析\"条件再差也不放弃\"+回扣\"勤奋成就人生\"","论\"诚信\"：曾子杀猪+分析\"对孩子也守信\"+回扣","论\"创新\"：鲁班观草叶造锯+分析\"观察+思考\"+回扣","反例：只摆事例不分析=\"例子堆砌\"，分析才是得分点","公式：分论点→事例简述（100字内）→扣题分析→小结回扣","论\"坚持\"：同桌每天练字一页，一学期后字大变样+分析\"每天一小步\"+回扣","论\"诚信\"：小明答应还书按时还+分析\"小事守信才靠得住\"+回扣","论\"勤奋\"：班长每天早读半小时，英语越读越顺+分析\"天天练才有语感\"+回扣","论\"分享\"：小红把新书借给同学，全班都爱上了阅读+分析\"分享让快乐翻倍\"+回扣"],"深讲":"举例论证不是“讲个故事就完事”：故事只是证据，真正说服人的是后面的分析——这个例子为什么能证明我的观点。没有分析的例子，再感人也只是“堆材料”。记住公式：分论点→事例简述（越短越好，100字内）→扣题分析→小结回扣。","怎么认":["先找分论点：这段要证明什么？","再看事例：故事讲的是不是这回事？","最后看分析：有没有讲清“这个例子为什么能证明观点”？没有，就是例子堆砌。"],"辨析":"举例论证和“讲故事”的区别在“扣题”：讲故事讲完就完了；举例论证讲完必须回扣——“这说明……”“可见……”。没有回扣的例子，读者不知道你想证明什么。","例句解析":[{"句":"论\"勤奋\"：匡衡凿壁偷光+分析\"条件再差也不放弃\"+回扣\"勤奋成就人生\"","析":"事例只讲了“凿壁偷光”的意思，重点在分析“条件再差也不放弃”——分析把事例和“勤奋”连起来，回扣点明观点，结构才完整。"},{"句":"反例：只摆事例不分析=\"例子堆砌\"，分析才是得分点","析":"光摆事例，读者只能看到故事，看不到观点。分析是桥梁：没有桥，事例到不了观点那边。"}],"易错":"两个坑：一是事例写太长（超过100字），挤占分析空间；二是事例讲完不分析不回扣，变成例子堆砌。记住：分析才是得分点。","练习":[{"q":"举例论证最关键的一步是？","options":["事例讲得长","扣题分析","事例讲得感人"],"answer":1,"解析":"事例只是证据，分析把事例和观点连起来——没有分析就是例子堆砌。"},{"q":"“论勤奋：匡衡凿壁偷光。”这样写缺什么？","options":["缺事例","缺分析和回扣","缺分论点"],"answer":1,"解析":"只有事例没有分析，读者不知道这个故事怎么证明勤奋——要补“条件再差也不放弃”的分析和回扣。"},{"q":"事例简述应该多长？","options":["越长越好","100字内，越短越好","不用写事例"],"answer":1,"解析":"事例是载体不是主角，100字内讲清即可，篇幅要留给分析和回扣。"}]},{"name":"道理论证","类比":"道理论证就像\"请权威背书\"：名人名言、定理公理往那一摆，分量立马不同。","讲解":"公式：分论点+名言/定理+阐释（为什么这句能证明观点）+回扣。","口诀":"名言开道，阐释跟上","例子":["论\"坚持\"：荀子\"锲而不舍，金石可镂\"+解释+回扣","论\"学习方法\"：朱熹\"读书有三到，心到眼到口到\"+阐释+回扣","论\"谦虚\"：\"满招损，谦受益\"+阐释为什么适用+回扣","论\"团结\"：\"人心齐，泰山移\"+阐释+回扣","忌：名言堆三四句却不阐释=白费，阐释才是得分点","公式：分论点→名言/定理→阐释（为什么能证明）→回扣","论\"学习态度\"：《论语》\"学而不思则罔，思而不学则殆\"+阐释+回扣","论\"诚信\"：《论语》\"人而无信，不知其可也\"+阐释+回扣","论\"谦虚\"：《论语》\"三人行，必有我师焉\"+阐释+回扣","提醒：名言要和分论点贴得紧，贴不上的名言再有名也是白摆"],"深讲":"道理论证是“请权威来背书”：名人名言、定理、公理自带分量。但名言自己不会说话——必须阐释：这句名言为什么能证明我的观点？不阐释的名言堆得再多，也只是“贴标签”，不是论证。","怎么认":["找名言：引的是谁的话、哪条定理？","找阐释：有没有讲这句为什么能证明观点？","找回扣：最后有没有回到分论点？"],"辨析":"道理论证和举例论证的区别：举例是拿“事”证明（匡衡的故事），道理论证是拿“理”证明（荀子的话、定理）。一个讲事实，一个讲道理；写议论文时两者常常配合用。","例句解析":[{"句":"论\"坚持\"：荀子\"锲而不舍，金石可镂\"+解释+回扣","析":"荀子的话讲“不停地刻，连金石都能刻穿”——阐释要把“刻”对应到“坚持”，再回扣“坚持才能成事”，名言才算用上了。"},{"句":"忌：名言堆三四句却不阐释=白费，阐释才是得分点","析":"三四句名言排队站岗，看起来有气势，其实都没和观点连上线——阐释才是把名言变成论证的那一步。"}],"易错":"名言不能堆砌，阐释（为什么适用）才是得分点","练习":[{"q":"道理论证里最不能少的是？","options":["名言的数量","阐释（为什么能证明观点）","名言的作者名气"],"answer":1,"解析":"名言再有名，不阐释就和观点连不上线——阐释才是得分点。"},{"q":"论“谦虚”引用“满招损，谦受益”，接下来最应该写什么？","options":["再引一句名言","阐释为什么骄傲招损、谦虚受益","直接结尾"],"answer":1,"解析":"要讲清这句为什么能证明谦虚——骄傲让人看不见缺点，谦虚让人不断进步。"},{"q":"下面哪种是道理论证？","options":["讲匡衡凿壁偷光的故事","引用荀子“锲而不舍，金石可镂”并阐释","正反两个例子对照"],"answer":1,"解析":"引用名言讲道理是道理论证；讲故事是举例论证；正反对照是对比论证。"}]},{"name":"对比论证","类比":"对比就像\"照妖镜\"：正反一放，好坏立现。","讲解":"正面例子+反面例子+对比分析，得出结论。是非分明，说服力强。","口诀":"正反对照，是非自现","例子":["论\"勤奋\"：方仲永荒废 vs 匡衡凿壁","论\"诚信\"：曾子杀猪守信 vs 周幽王烽火戏诸侯失信","论\"节俭\"：朱元璋节俭 vs 石崇斗富奢靡","论\"谦虚\"：孔子不耻下问 vs 项羽刚愎自用","结构：正面事例+反面事例+对比分析→结论","提醒：对比点要扣住分论点，不能为对比而对比","论\"认真\"：小明检查三遍全对 vs 小刚交卷就跑错一半","论\"坚持\"：每天练跑步的同学越跑越轻松 vs 三天打鱼两天晒网的同学一直喘","论\"合作\"：小组分工的同学做得又快又好 vs 单打独斗的同学手忙脚乱","论\"阅读\"：爱读书的同学写作文有话说 vs 从不读书的同学对着作文纸发呆"],"深讲":"对比论证是“正反一放，好坏立现”：正面例子和反面例子放在一起，对比的点必须扣住分论点。对比不是为了热闹——比完要分析：为什么一个成、一个败？分析出原因，结论才有说服力。","怎么认":["找正面和反面两个例子。","看对比点：是不是扣住分论点？（论勤奋就比勤奋不勤奋，别比别的）","看对比分析：比完有没有讲清原因、得出结论？"],"辨析":"对比论证和“举两个例子”不一样：举两个正面例子是举例论证；一正一反、比出高下才是对比论证。没有反面，就没有对比。","例句解析":[{"句":"论\"勤奋\"：方仲永荒废 vs 匡衡凿壁","析":"一个天赋好却荒废，一个条件差却勤奋——天赋和条件都不是决定因素，对比点正好扣住“勤奋”，结论“勤奋成就人生”就立住了。"},{"句":"提醒：对比点要扣住分论点，不能为对比而对比","析":"论勤奋却对比“谁长得高”，比得再热闹也没用——对比点跑偏，论证就跑偏。"}],"易错":"两个坑：一是对比点跑偏（论勤奋比长相）；二是比完不分析，只把两个例子并排放，读者看不出你想说什么。比完一定要分析原因、得出结论。","练习":[{"q":"对比论证必须有什么？","options":["两个正面例子","一正一反两个例子","三个例子"],"answer":1,"解析":"一正一反、比出高下才是对比；两个正面例子只是举例论证。"},{"q":"论“坚持”，下面哪组对比最合适？","options":["小明高 vs 小刚矮","每天练跑步越跑越轻松 vs 三天打鱼一直喘","小红爱笑 vs 小军爱哭"],"answer":1,"解析":"对比点必须扣住“坚持”：天天练和三天打鱼，正好是坚持和不坚持。"},{"q":"对比完两个例子，最应该做什么？","options":["再比一组","分析原因、得出结论","直接换话题"],"answer":1,"解析":"比完要分析为什么一个成一个败，结论才有说服力；只并排放例子等于没论证。"}]},{"name":"常见谬误","类比":"谬误就像逻辑陷阱：看起来有道理，一脚踩空。","讲解":"偷换概念（白马非马式）、滑坡谬误（可能性变必然性）、人身攻击（不驳观点驳人）、稻草人（曲解对方再打）。","口诀":"偷滑人稻，谬误四套","例子":["滑坡：今天不上补习班，明天就考不上大学","人身攻击：他学习不好，他的话不可信","偷换概念：辩论\"作业该不该多\"时把\"作业\"偷换成\"学习\"（概念变了）","稻草人：你说\"该减少作业\"，他反驳\"你就是不想学习\"（曲解后再打）","滑坡：这次考砸→考不上高中→找不到工作→人生完蛋（可能变必然）","诉诸权威：\"专家都说对，所以一定对\"（不看论证看头衔）","循环论证：\"这本书好，因为它就是好书\"（用结论证明结论）","诉诸感情：\"你忍心看我不及格吗？所以这道题应该算我对\"（用同情代替论证）","非黑即白：\"不喜欢数学，就是讨厌学习\"（中间还有很多情况）","因果倒置：\"因为他成绩好，所以老师喜欢他\"（也可能是老师喜欢才成绩好，因果说反了）"],"深讲":"谬误是“看起来有道理，其实站不住”的话。常见四套：偷换概念（中途换了词的意思）、滑坡谬误（把可能说成必然）、人身攻击（不驳观点驳人）、稻草人（先曲解对方再打）。另外还有循环论证（用结论证明结论）、诉诸权威（只看头衔不看论证）、非黑即白（中间还有别的情况却说只有两种）。","怎么认":["问：词的意思中途换了吗？（偷换概念）","问：每一步因果都必然吗？（滑坡）","问：反驳的是观点还是人？（人身攻击）","问：打的是对方原话，还是曲解后的靶子？（稻草人）"],"辨析":"滑坡谬误和“合理推测”不一样：“不好好复习可能考不好”是合理推测（说“可能”）；“这次考砸→找不到工作→人生完蛋”是滑坡（把可能说成必然，还一环套一环）。","例句解析":[{"句":"滑坡：这次考砸→考不上高中→找不到工作→人生完蛋（可能变必然）","析":"每一步都只是“可能”，连起来却说成了“必然”——考砸不一定考不上高中，考不上高中也不一定找不到工作，链条每环都要打问号。"},{"句":"稻草人：你说\"该减少作业\"，他反驳\"你就是不想学习\"（曲解后再打）","析":"对方原话是“减少作业”，被曲解成“不想学习”再打倒——打的是自己立的稻草靶子，不是对方真正的观点。"}],"易错":"认谬误时别乱扣帽子：先确认对方原话到底是什么（防稻草人误判），再确认每步因果是不是必然（防滑坡误判）。扣错帽子，自己就成了诡辩的一方。","练习":[{"q":"“他普通话不标准，他讲的道理肯定不对”犯了什么谬误？","options":["滑坡谬误","人身攻击","偷换概念"],"answer":1,"解析":"普通话标不标准和道理对不对没关系，攻击人而不反驳观点，是人身攻击。"},{"q":"“这本书好，因为它就是好书”犯了什么谬误？","options":["循环论证","滑坡谬误","稻草人"],"answer":0,"解析":"用结论“就是好书”来证明结论“这本书好”，原地打转，是循环论证。"},{"q":"“不喜欢数学，就是讨厌学习”犯了什么谬误？","options":["诉诸权威","非黑即白","人身攻击"],"answer":1,"解析":"不喜欢数学和讨厌学习之间还有很多情况（喜欢语文、喜欢画画），硬说成只有两种，是非黑即白。"}],"动画":{"steps":[{"tokens":["滑坡：","不上补习班","→","考不上大学"],"note":"可能性被说成必然性：每环因果经得起问吗？"},{"tokens":["人身攻击：","他成绩差","→","话不可信"],"note":"不驳观点驳人：成绩差≠观点错"},{"tokens":["稻草人：","曲解对方","→","打倒假想敌"],"note":"先歪曲再反驳：打的是自己立的靶子"}]},"小测":[{"q":"\"你这么胖，还好意思谈健康饮食？\"犯了什么谬误？","options":["滑坡谬误","人身攻击","偷换概念"],"answer":1,"解析":"攻击人而不反驳观点，是人身攻击。"}]}]},{"id":"tuili","name":"日常语言推理","items":[{"name":"言外之意","类比":"言外之意就像冰山：说出口的只是水面上的尖，意思藏在水下。","讲解":"合作原则：说话默认 truthful、相关、清楚。违反处即有言外之意。","口诀":"话里有话藏水下，违反常规是信号","例子":["问：蛋糕好吃吗？答：盘子很漂亮。（=不好吃）","妈妈：\"你房间真'整洁'啊！\"（=乱得不行，反话）","问：这道题难吗？答：全班最高分60。（=很难）","\"你先走吧，我还有点事\"（=不想跟你一起走）","\"改天请你吃饭\"（=客套话，不必当真）","识别：违反\"相关/清楚\"的地方，就有言外之意","问：电影好看吗？答：还行。（=一般，没直说不好看）","爸爸：\"你的袜子在阳台上晒太阳呢！\"（=袜子晒好了，快去收）","问：这件衣服贵吗？答：也就我一个月零花钱吧。（=很贵）","\"我等了你一个世纪！\"（=等了很久，别迟到了）"],"深讲":"说话有个默认规矩：说真话、说相关的、说清楚。话里一旦违反了规矩——答非所问、故意反着说、说得含糊——听话的人就知道：字面意思不是真意思，真意思藏在水下。找言外之意，就是找“哪里违反了规矩”。","怎么认":["先听字面：他原话是什么意思？","再找违规：答非所问？反话？含糊其辞？客套话？","最后推真意：结合场合，他真正想说的是什么？"],"辨析":"言外之意和“说谎”不一样：说谎是想让你相信假话；言外之意是说话人默认你能听懂——“盘子很漂亮”不是骗你蛋糕好吃，是委婉告诉你“不好吃”。一个是骗，一个是暗示。","例句解析":[{"句":"问：蛋糕好吃吗？答：盘子很漂亮。（=不好吃）","析":"问蛋糕，答盘子——违反了“相关”规矩。故意不提蛋糕，就是在委婉说“蛋糕不好吃，不好意思直说”。"},{"句":"妈妈：\"你房间真'整洁'啊！\"（=乱得不行，反话）","析":"房间明明很乱，妈妈却说“整洁”——故意违反“说真话”规矩。反着说，就是要你听出“乱得不行，快收拾”。"}],"易错":"别把所有话都听出言外之意：“改天请你吃饭”是客套，但“明天请你吃饭”就是真约——场合和说法决定有没有言外之意；直说的话，别硬找弦外之音。","练习":[{"q":"问：电影好看吗？答：还行。这句话的言外之意最可能是？","options":["电影很好看","电影一般，没直说不好看","电影还没上映"],"answer":1,"解析":"“还行”含糊其辞，没直说“好看”——违反“说清楚”规矩，真意是“一般”。"},{"q":"“你的袜子在阳台上晒太阳呢！”爸爸真正想说的是？","options":["袜子喜欢晒太阳","快去把袜子收回来","阳台阳光很好"],"answer":1,"解析":"这不是讲袜子，是提醒：袜子晒好了，快去收——暗示藏在陈述句里。"},{"q":"下面哪句是反话（言外之意和字面相反）？","options":["你房间真整洁啊（房间很乱时）","明天请你吃饭","我作业写完了"],"answer":0,"解析":"房间乱却说“整洁”，字面和真意相反，是反话；另外两句是直说。"}]},{"name":"因果链","类比":"因果链就像多米诺：失了一颗铁钉，亡了一个帝国。","讲解":"找因果要一环扣一环，每环都经得起问为什么（5个为什么）。","口诀":"找因一环一环问，断了链条不算数","例子":["铁钉→马掌→战马→将军→战争→帝国","熬夜→上课犯困→听不懂→成绩下滑→考不上高中（每环都经得起问为什么）","多读书→词汇量大→作文好→语文高分（链条完整）","断链反例：早上没吃早饭→考试失利（中间缺环节，链条不牢）","方法：对每环连问5个\"为什么\"，问到底就是根因","写作：议论文\"因果论证\"就是摆出一条完整因果链","多运动→身体壮→不容易生病→少请假→功课不掉队（链条完整）","上课走神→笔记没记全→复习没材料→考试丢分（每环都问为什么）","断链反例：多喝水→成绩变好（中间缺环节：喝水和成绩没有链条）","五问法：字写不好→为什么？练得少→为什么练得少？没安排时间→为什么没安排？玩手机占了时间→根因：时间管理"],"深讲":"因果链是把“因为……所以……”接成长串：A→B→C→D，每一环都要经得起问“为什么”。有一环问不下去，链条就断了，结论就站不住。“5个为什么”就是检查工具：对每一环连问5次为什么，问到底就找到根因。","怎么认":["把事情写成一串：A→B→C→D。","对每一环问“为什么”：B真的是A造成的吗？","有一环答不上来，就是断链——结论不可靠。"],"辨析":"因果链和“单因果”不一样：单因果只讲一对（熬夜→困）；因果链讲一串（熬夜→困→听不懂→成绩下滑）。链越长，越要一环一环查——长链最容易在中间断掉。","例句解析":[{"句":"熬夜→上课犯困→听不懂→成绩下滑→考不上高中（每环都经得起问为什么）","析":"每环都能问“为什么”：为什么犯困？因为熬夜。为什么听不懂？因为犯困。一环扣一环，链条才牢。"},{"句":"断链反例：早上没吃早饭→考试失利（中间缺环节，链条不牢）","析":"没吃早饭和考试失利之间缺了好几环（饿→没精神→没发挥好），直接跳过去就是断链——不能这么推。"}],"易错":"长链条最容易犯两个错：一是中间跳环（熬夜直接跳到考不上大学）；二是把“相关”当“因果”（公鸡打鸣和天亮一起出现，不是谁造成谁）。每环都要问一句“为什么”。","练习":[{"q":"“多喝水→成绩变好”错在哪里？","options":["水喝得不够多","中间缺环节，链条不牢","成绩不能变好"],"answer":1,"解析":"喝水和成绩之间没有链条——缺了环节直接跳，就是断链。"},{"q":"“成绩下滑”用5个为什么找根因，第一步问什么？","options":["为什么成绩下滑","为什么要考试","为什么有学校"],"answer":0,"解析":"从结果往回问：为什么下滑？→没听懂→为什么没听懂？→上课困……一环一环问到底。"},{"q":"下面哪条是完整的因果链？","options":["早上没吃早饭→考试失利","多读书→词汇量大→作文好→语文高分","公鸡打鸣→天亮"],"answer":1,"解析":"读书→词汇→作文→高分，每环都经得起问为什么；A跳环，C是相关不是因果。"}]},{"name":"因果链：多米诺","类比":"因果就像多米诺骨牌：失了一颗铁钉，丢了一只马掌，亡了一个帝国。","图示":"<svg viewBox=\"0 0 400 90\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"30\" width=\"14\" height=\"40\" fill=\"#8e24aa\" transform=\"rotate(15 27 50)\"/><rect x=\"70\" y=\"30\" width=\"14\" height=\"40\" fill=\"#8e24aa\" transform=\"rotate(25 77 50)\"/><rect x=\"120\" y=\"35\" width=\"14\" height=\"40\" fill=\"#8e24aa\" transform=\"rotate(35 127 50)\"/><text x=\"180\" y=\"55\" font-size=\"14\">铁钉→马掌→战马→将军→帝国</text><text x=\"180\" y=\"75\" font-size=\"12\" fill=\"#888\">每环问一句\"为什么\"，5个为什么</text></svg>","练习":[{"q":"“忘带红领巾→被扣分→班级丢了流动红旗”这是？","options":["普通因果","多米诺（小因大果）","没有因果"],"answer":1,"解析":"起点只是忘带红领巾，终点却是全班丢红旗——小起因放大成大结果，是多米诺。"},{"q":"“每天读10分钟→一学期读完六本→作文有话写了”说明了什么？","options":["读书没用","小习惯顺着链条会放大","作文不用练"],"answer":1,"解析":"每天10分钟很小，顺着链条传下去，变成了一学期六本、作文有话写——好习惯的多米诺。"},{"q":"“我今天多吃了一块糖，所以长胖了”错在哪里？","options":["糖不能吃","一小因推不出大果，链条没连上","长胖写错了"],"answer":1,"解析":"一块糖和长胖之间没有连上的链条——硬放大就是错的，不是多米诺。"}],"动画":{"steps":[{"tokens":["少了","一颗铁钉"],"note":"起点：小得不起眼"},{"tokens":["丢了","一只马掌"],"note":"连锁：铁钉→马掌"},{"tokens":["亡了","一个帝国"],"note":"终点：蝴蝶效应"}]},"讲解":"找因果要一环扣一环，每环都问\"为什么\"，连续问5次到根因。","口诀":"因果链条环环扣，五个为什么问到底","小测":[{"q":"\"因为他是北方人，所以思想守旧\"错在哪环？","options":["籍贯推不出思想","北方人确实守旧","没错"],"answer":0,"解析":"籍贯→思想这环因果不成立，是强加因果。"}],"例子":["完整链：少一颗铁钉→掉一只马掌→折一匹战马→伤一位将军→败一场战争→亡一个帝国","五问法：成绩下滑→为什么没听懂→为什么上课困→为什么熬夜→为什么玩手机→根因：缺自律","反例：公鸡打鸣→天亮（把\"相关\"当\"因果\"，还颠倒了）","反例：熬夜→考不上大学（跳了三环，链条不牢）","口诀应用：环环相扣+五个为什么问到底","小原因大后果：忘带红领巾→被扣分→班级丢了流动红旗→全班一周的努力白费","小习惯大变化：每天读10分钟→一个月读完一本书→一学期读完六本→作文有话写了","推倒第一块：早上赖床10分钟→赶不上校车→迟到→错过早读→一天都心慌","反例：只推倒一块牌，别的牌没动——\"我今天多吃了一块糖，所以长胖了\"（一小因推不出大果，链条没连上）","好习惯多米诺：整理书包→第二天不慌→上课专注→作业写得快→有空多读一本书"],"深讲":"多米诺讲的是“小原因、大后果”：第一块牌很小，倒下去却能推倒一整排。生活里也是这样：一个小习惯（每天读10分钟）、一个小疏忽（忘带红领巾），顺着链条传下去，会变成很大的结果。所以别小看第一块牌——推倒它之前，先想想后面会倒什么。","怎么认":["找第一块牌：最小的那个起因是什么？","顺着看：它推倒了什么？那一块又推倒了什么？","看到终点：小起因是不是变成了大结果？是，就是多米诺。"],"辨析":"多米诺和普通因果链的区别在“放大”：普通因果链只要求环环相扣；多米诺还要求越传越大——小起因、大终点。如果起因和结果差不多大（多喝水→多上厕所），那只是因果链，不是多米诺。","例句解析":[{"句":"完整链：少一颗铁钉→掉一只马掌→折一匹战马→伤一位将军→败一场战争→亡一个帝国","析":"起点只是一颗铁钉，终点却是一个帝国——每一环都比前一环大，这就是多米诺的“放大”。"},{"句":"反例：公鸡打鸣→天亮（把\"相关\"当\"因果\"，还颠倒了）","析":"公鸡打鸣和天亮只是同时出现，不是因果；真要说，也是天亮在前、打鸣在后——相关≠因果，因果还说反了。"}],"易错":"多米诺最容易犯的错是“硬放大”：一小因推不出大果时，链条其实没连上（“多吃一块糖所以长胖了”）。放大必须每环都真，不能为了效果硬推。"}]}]},"reading":{"categories":[{"id":"tongyong","items":[{"name":"三遍阅读法","例子":["第一遍泛读：抓体裁、抓主旨","第二遍精读：析结构、圈关键句","第三遍跳读：带着题目找答案区","泛读只看标题+首尾段，1分钟定体裁","精读圈出过渡句、抒情议论句（主旨常藏这里）","跳读：题干关键词→原文定位→前后三句找答案"],"口诀":"泛读抓主旨，精读析结构，跳读找答案","易错":"切忌没读完文章就匆忙答题","讲解":"中考阅读的标准流程，先整体后局部"},{"name":"找中心句","例子":["开头总起句、结尾总结句","段落首句尾句","议论文开头：\"勤奋是成功之母\"（开门见山亮观点）","记叙文结尾：\"这就是我的母亲\"（点题+抒情）","抒情议论句多是中心句，叙事句一般不是","独立成段的句子，常是中心句或过渡句"],"口诀":"开头结尾重点看，首尾常把中心担","易错":"中心句多是议论抒情句，不是叙事句","讲解":"中心句常出现在开头结尾、段落首尾，多为概括性语句"},{"name":"语境意识","例子":["词语含义到上下文中找","答案组织紧扣文章中心","\"他'火'了\"：语境是演出→走红，不是着火","\"这个人很'冷'\"：语境是待人→冷漠，不是温度","答题引用原文，别自己编","开放题也要先扣文本再引申"],"口诀":"词不离句，句不离段，段不离篇","易错":"脱离文本的过度推断是丢分主因","讲解":"一切答案以文本为依据，联系上下文"},{"name":"关键句定位","例子":["体现作者立场的句子","过渡句、抒情议论句、比喻句","\"总之\"\"因此\"后面的句子常是总结句","独立成段的一句话：强调/过渡/主旨","反问句：\"难道这不是爱吗？\"（=这就是爱，立场句）","开头设问自答处，常是全文纲领"],"口诀":"立场过渡抒情议论，比喻连问要留神","易错":"独立成段的句子常有特殊作用","讲解":"开头句、结尾句、过渡句、抒情议论句常藏着主旨"}],"name":"通用阅读方法"},{"id":"tixing","items":[{"name":"概括内容","例子":["模式：什么人＋在什么情况下＋做什么事＋什么结果","如：本文记叙了小明在雨天坚持上学的故事","要素法：时间+地点+人物+起因+经过+结果（记叙文）","合并段意：每段小标题→连成一句话","摘录法：找中心句，稍加改造","忌：只写\"本文写了一件事\"（缺要素=白答）"],"口诀":"人物事件加结果，要素齐全才算数","易错":"必须包括“人物+事情”两要素","讲解":"要素归纳法/合并段意法/摘录中心句"},{"name":"标题赏析","例子":["问：为什么以“灯”为题？","答：①本义（文章写灯）②深层（灯象征希望）③线索/主旨作用","《背影》：本义父亲的背影+深层父爱+线索（以背影串全文）","《春》：本义春天+深层对未来的希望+开篇点题","标题是人名的：多以人物为线索/赞美人物","答题：本义+深层（象征/双关）+结构作用（线索/点题）"],"口诀":"本义深层两层皮，线索主旨不能离","讲解":"标题是文眼：概括情节、作线索、点明中心、象征义"},{"name":"词句赏析","例子":["问：赏析“小草偷偷地钻出来”","答：①拟人手法②写出小草的生机与春天的气息③表达作者对春天的喜爱","\"月光如水\"：比喻+写月光皎洁+烘托宁静","\"他攥紧了拳头\"：动作描写+写紧张愤怒+为下文爆发铺垫","万能三步：手法→内容→情感/主旨","忌：只说\"用了比喻\"不分析（=没答）"],"口诀":"手法内容加主旨，三步走完是满分","易错":"只答手法不分析内容，或只谈内容不扣主旨","讲解":"万能三步：手法判定→内容解析→情感/主旨升华"},{"name":"结构作用","例子":["问：中间段落的作用？","答：承上启下；内容上深化主题/塑造形象","开头：开篇点题/设置悬念/埋伏笔/奠定感情基调","结尾：总结全文/升华主旨/首尾呼应/戛然而止留余味","中间：承上启下/插叙补背景/为下文铺垫","公式：结构（承上启下）+内容（写了什么）+主旨（对中心的作用）"],"口诀":"结构内容两分说","易错":"开头段还可能是设置悬念、埋伏笔","讲解":"开头：开篇点题/设置悬念；中间：承上启下；结尾：总结/升华/首尾呼应"},{"name":"推断题","例子":["三步：定位依据→适度推理→验证选项","依据必须在原文，不能靠常识脑补","排除\"原文原话\"项（那不是推断）","排除\"过度推断\"项（原文没给这么多）","排除\"逻辑矛盾\"项（与原文冲突）"],"口诀":"回到原文找依据，适度推理不臆断","易错":"排除“原文直接出现”（不是推断）、“过度推断”、“逻辑矛盾”项","讲解":"基于原文信息的适度推理，不夸大不缩小"},{"name":"开放探究","例子":["问：你认同作者的观点吗？为什么？","答：观点明确（我认为……）+文本支撑（引用原文）+联系实际","先亮观点，别绕弯子","理由必须引原文，不能空表态","联系实际举一例（生活/名人事例）","言之成理即可，角度自选但要自圆其说"],"口诀":"观点明确，文本支撑，联系实际","易错":"只表态不给理由，或理由脱离文本","讲解":"立场+论据（原文）+引申，言之成理即可"}],"name":"常考题型与答题公式"},{"id":"wenti","items":[{"name":"记叙文","例子":["六要素：时间地点人物，起因经过结果","线索：人物/事件/情感/物品","人称：第一人称亲切，第二人称抒情，第三人称客观","顺序：顺叙/倒叙（设悬念）/插叙（补背景）","详略：详写主旨相关，略写次要","结尾常抒情议论点题"],"口诀":"六要素加线索，记叙文不迷路","易错":"","讲解":"以叙事写人为核心，抓线索理思路"},{"name":"议论文","例子":["论点（中心论点/分论点）","论据（事实/道理）","论证（举例/道理/对比/比喻）","中心论点常在标题/开头/结尾，标志词\"总之\"\"由此可见\"","事实论据要概括叙述，别抄原文长段","论证方法判断：看是讲事例/讲道理/正反比/打比方"],"口诀":"论点论据论证，三要素要分清","易错":"中心论点常在标题或开头结尾","讲解":"观点+材料+证明方法"},{"name":"说明文","例子":["说明对象+说明方法（举例子/列数字/打比方/作比较）","说明顺序：时间/空间/逻辑","语言：准确平实，\"大约\"\"可能\"表估计（删了就不准确）","下定义 vs 作诠释：前者严谨（\"……是……\"），后者通俗","列数字最直观，打比方最生动","逻辑顺序：总分/主次/现象到本质"],"口诀":"对象方法加顺序","易错":"说明方法判断是高频考点","讲解":"介绍事物事理，语言准确平实"},{"name":"散文","例子":["形散神聚：线索串材料","借景抒情、托物言志","线索：情感/游踪/物品（《背影》以背影为线索）","语言优美，善用修辞和意象","主旨含蓄：读出言外之意，别只看表面","托物言志：《爱莲说》以莲喻君子"],"口诀":"线索串珠，情感是魂","易错":"散文主旨常含蓄，要读出言外之意","讲解":"抒情性强，意境优美"}],"name":"文体辨识与策略"}],"module":"阅读理解方法技巧库","标准":"综合中考语文阅读题型与课标阅读要求整理","说明":"覆盖通用阅读方法、六大常考题型答题公式、四大文体策略，与语法库的修辞/句式知识联动"},"writing":{"categories":[{"id":"shenti","items":[{"name":"抓题眼","例子":["《那盏灯》：“灯”是题眼，引申为希望/指引","《温暖》：“温暖”是情感核心","《第一次》：\"第一次\"是题眼，写人生初体验","《风景》：可实写自然风景，可虚写\"心灵风景\"","《礼物》：\"礼物\"可实物可抽象（教诲也是礼物）","方法：圈出题目中最能决定立意的词"],"口诀":"瞻前顾后一字不漏，题眼就是开门钥匙","易错":"跑题多因没审清题眼","讲解":"精细审题第一步：圈关键词，找准题目核心词（题眼）"},{"name":"辨题型","例子":["命题作文：按题目写；材料作文：抓关键句立意","半命题：先补题再写","命题作文：题目即要求，一个字别改","半命题：《___，我的最爱》先补题（补具体事物）","材料作文：读懂材料倾向，别断章取义","话题作文：话题≠题目，自拟标题更出彩"],"口诀":"文题类型先分清，含义文体都要明","易错":"材料作文最忌断章取义、只抓局部","讲解":"注意文题类型、含义、文体类别、选材指向、立意信息"},{"name":"审题六审","例子":["一审文题类型，二审文题含义，三审题眼，四审文体，五审选材指向，六审立意信息","审文体：让写记叙文就别写成议论文","审选材指向：\"校园生活\"就别写家庭琐事","审立意信息：题目情感倾向（\"珍惜\"→正面）","六审漏一审，跑题风险翻倍"],"口诀":"类型含义题眼，文体选材立意","易错":"","讲解":"中考作文复习指导总结的审题六个要点"}],"name":"审题"},{"id":"liyi","items":[{"name":"立意三标准","例子":["正确（价值观端正）","集中（一个中心）","深刻（有思考）","正确：不能宣扬作弊、报复等负能量","集中：一篇只讲一个道理，贪多嚼不烂","深刻：从\"妈妈很辛苦\"挖到\"理解与感恩\""],"口诀":"中心是灵魂，正确集中深","易错":"立意贪多求全是大忌","讲解":"确立文章中心思想，犹如文章灵魂"},{"name":"立意八类","例子":["生命意义：生活感悟的滋味","自然景物：对周遭世界的感悟","情感体验：珍藏的人和事","享受幸福：温暖与智慧的情节","成功成长：花季酸甜苦辣","道德修养：诚信/勇敢/善良","哲理品悟：生活细节提炼规律","告别往昔：值得珍藏的片段"],"口诀":"生命自然情感，幸福成长道德，哲理告别","易错":"8类有交叉，按题目选最贴切的一类","讲解":"中高考作文立意范畴基本不出这8类，备考时每类准备一个典型题材"},{"name":"审题立意方法（材料作文）","例子":["抓关键句法、主旨倾向法、由果溯因法、求同分析法、辩证分析法","抓关键句：材料中的议论句多是\"题眼\"","由果溯因：从结果倒推原因找立意","求同存异：多则材料找共同点","辩证分析：看到\"失去\"也想到\"得到\""],"口诀":"全面分析抓关键，辩证因果多角度","易错":"过多纠缠局部细节会偏题","讲解":"高考常用：先整体把握材料，再抓关键词句作突破口，用辩证/因果/对比等思维多角度审视"}],"name":"立意"},{"id":"xuancai","items":[{"name":"选材三原则","例子":["熟悉（亲身经历）","动情（真体验真感受）","独特（与众不同）","熟悉：写亲身经历，细节才真实","动情：自己没感动，读者不会感动","独特：大家都写\"雨中送伞\"，你写\"雨后初晴\"就跳出来"],"口诀":"熟悉动情加独特，第一人称最稳妥","易错":"考场瞎编乱造易出纰漏","讲解":"选自己最熟悉、最动情的生活来写，用第一人称写亲身经历"},{"name":"素材积累","例子":["8个立意范畴各备1个典型题材","平时记录：春花秋月、校园草木、家庭琐事","每类备1个\"万能素材\"（如\"外婆的灶台\"可套亲情/成长/乡愁）","建素材本：按\"人物/事件/金句\"分类记","从课文找：朱自清《背影》可化用父爱题材","从时事找：神舟发射可套\"奋斗/家国\"立意"],"口诀":"8类题材常备，观察生活常记","易错":"","讲解":"把8个立意范畴各准备一个生动题材，考场直接调用"},{"name":"细节描写","例子":["写人：外貌/动作/神态/语言/心理","写事：细节+环境描写","抓住“最动人的那个细节”","动作链：\"抓起书包—冲出门—跳上车\"（连续动词）","神态+心理：\"他低头抠着衣角，心里像打翻了调料瓶\"","环境烘托：\"蝉鸣聒噪\"衬烦躁，\"细雨如丝\"衬忧愁","忌：流水账\"然后…然后…\"（无细节=无画面）"],"口诀":"人物六描写，事件抓细节","易错":"没有细节的叙事是流水账","讲解":"细节是记叙文的生命，环境描写烘托气氛"}],"name":"选材"},{"id":"jiegou","items":[{"name":"总分总结构","例子":["开头点题→中间分述→结尾升华","记叙文可用1-3-1或1-4-1（开头1段、中间3-4段、结尾1段）","开头：开门见山点题，别绕三圈","中间：3-4个小片段/分论点，各成一段","结尾：回扣标题+升华（抒情/议论）","忌\"大肚子\"：中间一段写半页，头尾各两行"],"口诀":"总分总最稳，六七段最顺","易错":"忌“大肚子作文”（中间一段超长）/大头/大尾巴","讲解":"考场最保险的结构；六七百字配六七段，视觉协调"},{"name":"一线穿珠","例子":["以人物品质为主线，串起几个典型片段","如《我的老师》","线索可是物品：《背影》以\"背影\"串起四次相见","线索可是情感：从\"讨厌\"到\"理解\"母亲","线索可是时间：童年—少年—现在","每个\"珠子\"（片段）都要扣住这根线"],"口诀":"一线串珠不旁逸","易错":"","讲解":"无贯穿中心事件时，以人物活动/品质为主线组织材料"},{"name":"开头技巧","例子":["一句话开头：直接交代时间地点人物事件","悬念开头/名句开头/排比开头","名句开头：\"长风破浪会有时\"→引出\"追梦\"主题","排比开头：\"母爱是伞，父爱是山…\"→排比造势","悬念开头：\"那天，我做了一个决定…\"→勾住读者","忌：开头超过5行还不见主题"],"口诀":"开头不过5行，开门见山最行","易错":"开头玩技巧过长会喧宾夺主","讲解":"开篇两三句点出记叙要点或明确主题，简洁洗练"},{"name":"结尾技巧","例子":["抒情结尾：升华情感","议论结尾：点明哲理、照应标题","首尾呼应：开头\"灯\"，结尾\"这盏灯，至今照着我\"","名句收束：\"会当凌绝顶\"→升华\"进取\"主题","戛然而止：故事停在高潮，余味悠长","忌：结尾另起新话题（跑题前兆）"],"口诀":"结尾抒情或议论，照应标题点中心","易错":"结尾忌另起新话题","讲解":"记叙文结尾抒情+哲理，议论文结尾重申论点"}],"name":"结构"},{"id":"yuyan","items":[{"name":"短句为主","例子":["一个句子主谓宾定状补齐了，就用句号","忌一逗到底","长句拆短：\"他跑进教室放下书包拿出课本\"→\"他跑进教室。放下书包，拿出课本。\"","短句有节奏感：适合写紧张场面","一逗到底最易犯语病（成分残缺/搭配不当）","长短结合：叙事用短句，抒情可偶用长句"],"口诀":"短句有力，长句易病","易错":"长句最易犯语病（呼应语法库病句）","讲解":"句子短促有力，节奏好且不易出错"},{"name":"修辞点缀","例子":["比喻拟人排比设问，点缀2-3处即可","比喻：\"父爱如山\"（2-3处，多了就腻）","排比：开头/结尾各一组，气势立现","设问自答：\"什么是勇敢？勇敢是…\"","忌：为修辞而修辞，堆砌成\"油腻文\""],"口诀":"修辞2-3处，语言即出彩","易错":"堆砌修辞会油腻","讲解":"呼应语法库8种修辞，恰当使用让语言出彩"},{"name":"描写升级","例子":["动作描写：连续动词","语言描写：神态+潜台词","环境描写：烘托人物心情","\"讲故事\"变\"演故事\"：别说\"他很生气\"，写\"他攥紧拳头，指节发白\"","五感调动：写雨不只写\"大\"，写\"砸在伞上的脆响\"","动静结合：\"蝉鸣\"动+\"树影\"静","忌：通篇叙述无描写=嚼蜡"],"口诀":"写人要有动作语言，写事要有细节环境","易错":"","讲解":"描写是把“讲故事”变成“演故事”的关键"}],"name":"语言"}],"module":"写作技巧库","标准":"综合中高考作文指导（审题/立意/选材/结构/语言）与课标写作要求整理","说明":"覆盖考场作文全流程：审题→立意→选材→结构→语言，与语法库（病句/修辞/句式）联动"}}